/**
 * Parent-level `--mode` ergonomics for the verb-first `search` namespace.
 *
 * The generated `search <scope>` leaves own the real `mode` body or query option (projected from
 * the Kotlin owner). This shim only lets that flag also appear before the scope
 * (`aventure-cli search --mode semantic entities "…"`): it registers one parent option whose
 * choices are read from the generated leaf specs and forwards the value to the dispatched leaf.
 * No mode vocabulary or contract facts are authored here; when no generated `search` leaf
 * carries a `mode` option there is nothing to forward and nothing is registered.
 */
import { InvalidArgumentError, Option, type Command } from "commander";
import type { OpenApiCommandSpec as GeneratedCommandSpec } from "../../mcp-server/contract.ts";

const SEARCH_ROOT = "search";
const MODE_OPTION_KEY = "mode";
const MODE_FLAG = "--mode";

export function registerSearchParentModeOption(
  program: Command,
  specs: readonly GeneratedCommandSpec[],
): void {
  const search = program.commands.find((command) => command.name() === SEARCH_ROOT);
  if (search === undefined) return;
  const scopeChoices = new Map<string, readonly string[]>();
  for (const spec of specs) {
    const [root, scope, extra] = spec.cliPath;
    if (root !== SEARCH_ROOT || scope === undefined || extra !== undefined) continue;
    const mode = [...spec.parameters, ...spec.bodyParameters].find(
      (parameter) => parameter.optionKey === MODE_OPTION_KEY,
    );
    if (mode?.choices !== undefined) scopeChoices.set(scope, mode.choices);
  }
  if (scopeChoices.size === 0) return;
  const choices = [...new Set([...scopeChoices.values()].flat())];
  // Order is load-bearing: .choices() installs its own parser, which the .argParser() below must
  // override — the manual checks carry BOTH duplicate rejection and choice validation.
  search.addOption(
    new Option(
      `${MODE_FLAG} <mode>`,
      "search strategy, forwarded to the scope command's generated --mode option",
    )
      .choices(choices)
      .argParser((value: string, previous: string | undefined): string => {
        if (previous !== undefined) {
          throw new InvalidArgumentError(`${MODE_FLAG} was already given; pass it once.`);
        }
        if (!choices.includes(value)) {
          throw new InvalidArgumentError(`${MODE_FLAG} must be one of: ${choices.join(", ")}.`);
        }
        return value;
      }),
  );
  search.hook("preSubcommand", (thisCommand, actionCommand) => {
    const mode: unknown = thisCommand.opts()[MODE_OPTION_KEY];
    if (typeof mode !== "string") return;
    if (!scopeChoices.has(actionCommand.name())) {
      thisCommand.error(`${MODE_FLAG} is not supported by 'search ${actionCommand.name()}'`);
    }
    actionCommand.setOptionValueWithSource(MODE_OPTION_KEY, mode, "cli");
  });
}
