import { aventureMethod, type AventureMethod } from "../api/client.ts";
import {
  OPENAPI_CLI_COMPOSITE_ROLES,
  OPENAPI_METHODS,
  type OpenApiCliCompositeLocalOption,
  type OpenApiCliCompositeRole,
  type OpenApiDocument,
  type OpenApiMutationReadback,
  type OpenApiOperation,
} from "../api/openapi-document.ts";
import { cliOptionDescription, cliPlaceholder } from "../config/cli-help-policy.ts";
import {
  flagName,
  normalizeToolName,
  toolProjectionFor,
  type OperationIntent,
  type ToolProjection,
} from "../config/tool-policy.ts";
import {
  cliBodyParameterInputName,
  cliParameterInputName,
  toContractParameter,
  type McpGenerationParameter,
} from "./contract-parameter.ts";
import {
  errorResponseContract,
  toResponseContract,
  type ModuleBinding,
  type OpenApiResponseStatus,
} from "./openapi-binding.ts";
import { toRequestBody, type McpGenerationBody } from "./request-body-contract.ts";

export type McpGenerationContract = {
  readonly operationId: string;
  readonly method: AventureMethod;
  readonly path: string;
  readonly resource: string;
  readonly intent: OperationIntent;
  readonly summary: string;
  readonly description: string;
  readonly security: readonly { readonly requirement: Record<string, readonly string[]> }[];
  readonly parameter: readonly McpGenerationParameter[];
  readonly requestBody?: McpGenerationBody;
  readonly response: readonly (Partial<ModuleBinding> & OpenApiResponseStatus)[];
  readonly errorResponse: readonly OpenApiResponseStatus[];
  readonly mutationReadback?: OpenApiMutationReadback;
  readonly projection: ToolProjection;
};

export type OpenApiCommandParameter<
  Location extends "path" | "query" | "body" = "path" | "query" | "body",
> = {
  readonly name: string;
  readonly optionKey: string;
  readonly flag: string;
  readonly required: boolean;
  readonly description: string;
  readonly location: Location;
  readonly schemaType?: string;
  readonly schemaFormat?: string;
  readonly itemSchemaType?: string;
  readonly defaultValue?: string | boolean | readonly string[];
  readonly choices?: readonly string[];
  readonly visibility?: NonNullable<McpGenerationParameter["visibility"]>;
};

export type OpenApiPathQueryCommandParameter = OpenApiCommandParameter<"path" | "query">;
export type OpenApiBodyCommandParameter = OpenApiCommandParameter<"body">;

export type OpenApiCommandSpec = {
  readonly operationId: string;
  readonly method: AventureMethod;
  readonly path: string;
  readonly resource: string;
  readonly intent: OperationIntent;
  readonly cliPath: readonly string[];
  readonly cliAliasPath?: readonly string[];
  readonly summary: string;
  readonly description: string;
  readonly hasBody: boolean;
  readonly bodyKind?: McpGenerationBody["kind"];
  /** Root JSON container type used by generated CLI input validation. */
  readonly bodySchemaType?: NonNullable<McpGenerationBody["schemaType"]>;
  readonly bodyRequired: boolean;
  readonly bodyDescription: string;
  readonly bodyRequiredPath: readonly string[];
  readonly bodyParameters: readonly OpenApiBodyCommandParameter[];
  readonly cliConflicts?: readonly (readonly string[])[];
  readonly mutationReadback?: OpenApiMutationReadback;
  readonly dryRun: boolean;
  readonly scope: ToolProjection["scope"];
  readonly auth: ToolProjection["auth"];
  readonly errorResponse: readonly OpenApiResponseStatus[];
  readonly parameters: readonly OpenApiPathQueryCommandParameter[];
};

export type OpenApiCompositeSpec = {
  readonly command: string;
  readonly role: OpenApiCliCompositeRole;
  readonly summary: string;
  readonly description: string;
  readonly operationId: string;
  readonly method: AventureMethod;
  readonly path: string;
  readonly bodyOption: readonly Pick<
    OpenApiBodyCommandParameter,
    "name" | "optionKey" | "flag" | "required" | "description"
  >[];
  readonly localOption: readonly OpenApiCliCompositeLocalOption[];
};

export function buildMcpGenerationContracts(
  openApi: OpenApiDocument,
): readonly McpGenerationContract[] {
  const contracts: McpGenerationContract[] = [];
  for (const [template, pathItem] of Object.entries(openApi.paths)) {
    for (const method of OPENAPI_METHODS) {
      const operation = pathItem[method];
      if (operation === undefined) continue;
      const httpMethod = aventureMethod(method);
      const projection = toolProjectionFor({ method: httpMethod, path: template, operation });
      if (projection === null) continue;
      const usedNames = new Set<string>();
      contracts.push({
        operationId: operation.operationId,
        method: httpMethod,
        path: template,
        resource: projection.resource,
        intent: projection.intent,
        summary: operation.summary ?? "",
        description: operation.description ?? "",
        security: (operation.security ?? []).map((entry) => ({ requirement: entry })),
        parameter: (operation.parameters ?? [])
          .filter((parameter) => parameter.in !== "header")
          .map((parameter) => toContractParameter(openApi, parameter, usedNames)),
        requestBody: toRequestBody(openApi, usedNames, operation),
        response: toResponseContract(openApi, operation.responses),
        errorResponse: errorResponseContract(openApi, operation.responses),
        mutationReadback: operation["x-aventure-mutation-readback"],
        projection,
      });
    }
  }
  return disambiguateCliPaths(contracts);
}

export function openApiCommandSpecs(
  contract: readonly McpGenerationContract[],
): readonly OpenApiCommandSpec[] {
  return [...contract]
    .toSorted(
      (left, right) =>
        left.projection.cliPath.length - right.projection.cliPath.length ||
        left.projection.cliPath.join(" ").localeCompare(right.projection.cliPath.join(" ")) ||
        left.operationId.localeCompare(right.operationId),
    )
    .map((source) => {
      const parameters = source.parameter.flatMap((parameter) => {
        if (parameter.in !== "path" && parameter.in !== "query") return [];
        const location = parameter.in;
        const projected =
          parameter.in === "query" && parameter.itemProperty !== undefined
            ? parameter.itemProperty
            : [parameter];
        return projected.map<OpenApiPathQueryCommandParameter>((input) =>
          cliParameterBase(input, cliParameterInputName(source, input), location),
        );
      });
      const bodyParameters = cliBodyParameters(source, parameters);
      const cliConflicts = cliConflictGroups(source.requestBody?.cliConflicts, bodyParameters);
      return {
        operationId: source.operationId,
        method: source.method,
        path: source.path,
        resource: source.resource,
        intent: source.intent,
        cliPath: source.projection.cliPath,
        cliAliasPath: source.projection.cliAliasPath,
        summary: source.summary,
        description: source.description,
        hasBody: source.requestBody !== undefined,
        bodyKind: source.requestBody?.kind,
        bodySchemaType: source.requestBody?.schemaType,
        bodyRequired: source.requestBody?.required ?? false,
        bodyDescription: source.requestBody?.description ?? "",
        bodyRequiredPath: source.requestBody?.requiredPath ?? [],
        bodyParameters,
        mutationReadback: source.mutationReadback,
        dryRun: source.projection.dryRun,
        scope: source.projection.scope,
        auth: source.projection.auth,
        errorResponse: source.errorResponse,
        parameters,
        cliConflicts: cliConflicts.length === 0 ? undefined : cliConflicts,
      };
    });
}

export function buildOpenApiCompositeSpecs(
  openApi: OpenApiDocument,
  ordinaryCommand: readonly OpenApiCommandSpec[],
): readonly OpenApiCompositeSpec[] {
  const composite = Object.entries(openApi.paths).flatMap(([path, pathItem]) =>
    OPENAPI_METHODS.flatMap((method) => {
      const operation = pathItem[method];
      const extension = operation?.["x-aventure-cli-composite"];
      return operation === undefined || extension === undefined
        ? []
        : [compositeCandidate(openApi, path, aventureMethod(method), operation, extension)];
    }),
  );
  const start = openApiCompositeSpec(composite, "start");
  const poll = openApiCompositeSpec(composite, "poll");
  const acknowledge = openApiCompositeSpec(composite, "acknowledge");
  const revoke = openApiCompositeSpec(composite, "revoke");
  if (poll.command !== start.command || acknowledge.command !== start.command) {
    throw new Error(`Composite CLI command '${start.command}' has an incomplete role set`);
  }
  for (const role of [poll, acknowledge]) {
    if (role.bodyOption.length + role.localOption.length === 0) continue;
    throw new Error(
      `Composite CLI command '${start.command}' declares options outside its start role`,
    );
  }
  const loginCommandPath = start.command.split(" ");
  const logoutCommandPath = revoke.command.split(" ");
  const ordinaryPath = ordinaryCommand.flatMap(({ cliPath, cliAliasPath }) =>
    cliAliasPath === undefined ? [cliPath] : [cliPath, cliAliasPath],
  );
  if (
    pathsCollide(loginCommandPath, logoutCommandPath) ||
    [loginCommandPath, logoutCommandPath].some((path) =>
      ordinaryPath.some((ordinary) => pathsCollide(path, ordinary)),
    )
  ) {
    throw new Error("Composite CLI command collides with another command");
  }
  return composite.toSorted(
    (left, right) =>
      OPENAPI_CLI_COMPOSITE_ROLES.indexOf(left.role) -
      OPENAPI_CLI_COMPOSITE_ROLES.indexOf(right.role),
  );
}

/** Resolves generated runtime request metadata and rechecks the generator's closed-role invariant. */
export function openApiCompositeSpec(
  composite: readonly OpenApiCompositeSpec[],
  role: OpenApiCliCompositeRole,
): OpenApiCompositeSpec {
  const [match, duplicate] = composite.filter((entry) => entry.role === role);
  if (match === undefined || duplicate !== undefined) {
    throw new Error(`Generated composite CLI role '${role}' is incomplete`);
  }
  return match;
}

function compositeCandidate(
  openApi: OpenApiDocument,
  path: string,
  method: AventureMethod,
  operation: OpenApiOperation,
  extension: NonNullable<OpenApiOperation["x-aventure-cli-composite"]>,
): OpenApiCompositeSpec {
  if (!path.startsWith("/v1/auth/")) {
    throw new Error(`Composite CLI operation '${operation.operationId}' is outside /v1/auth/**`);
  }
  const requestBody = toRequestBody(openApi, new Set(), operation);
  const bodyOption = (extension.bodyOption ?? []).map((name) => {
    const parameter = requestBody?.parameter.find((entry) => entry.name === name);
    if (parameter === undefined)
      throw new Error(
        `Composite CLI body option '${name}' is not an addressable request-body field`,
      );
    if (parameter.description.trim() === "")
      throw new Error(`Composite CLI body option '${name}' has no Kotlin schema description`);
    const projected = cliParameterBase(parameter, parameter.inputName, "body");
    return {
      name,
      optionKey: projected.optionKey,
      flag: projected.flag,
      required: projected.required,
      description: projected.description,
    };
  });
  const localOption = extension.localOption ?? [];
  const option = [...bodyOption, ...localOption];
  const identity = option.flatMap(({ optionKey, flag }) => [optionKey, flag.split(" ")[0]]);
  if (new Set(identity).size !== identity.length) {
    throw new Error(`Composite CLI command '${extension.command}' has colliding options`);
  }
  const summary = operation.summary?.trim();
  const description = operation.description?.trim();
  const operationId = operation.operationId.trim();
  if (!summary || !description || !operationId) {
    throw new Error(`Composite CLI command '${extension.command}' has incomplete metadata`);
  }
  return {
    command: extension.command,
    role: extension.role,
    summary,
    description,
    operationId,
    method,
    path,
    bodyOption,
    localOption,
  };
}

function pathsCollide(left: readonly string[], right: readonly string[]): boolean {
  const shared = Math.min(left.length, right.length);
  return left.slice(0, shared).every((segment, index) => segment === right[index]);
}

/** Maps canonical body-property names to the Commander option keys generated for this command. */
function cliConflictGroups(
  groups: readonly (readonly string[])[] | undefined,
  bodyParameters: readonly OpenApiBodyCommandParameter[],
): readonly (readonly string[])[] {
  const optionKeyByName = new Map(bodyParameters.map(({ name, optionKey }) => [name, optionKey]));
  return (groups ?? []).map((group) =>
    group.map((name) => {
      const optionKey = optionKeyByName.get(name);
      if (optionKey === undefined) {
        throw new Error(
          `x-aventure-cli-conflicts field '${name}' was removed from the generated CLI projection`,
        );
      }
      return optionKey;
    }),
  );
}

function cliBodyParameters(
  contract: McpGenerationContract,
  parameters: readonly OpenApiPathQueryCommandParameter[],
) {
  const usedInputName = new Set(parameters.map((parameter) => parameter.optionKey));
  const usedPathWireName = new Set(
    parameters
      .filter((parameter) => parameter.location === "path")
      .map((parameter) => parameter.name),
  );
  return [...(contract.requestBody?.parameter ?? [])]
    .toSorted((left, right) => rangeBoundOrder(left.name) - rangeBoundOrder(right.name))
    .flatMap((parameter) => {
      if (
        !parameter.required &&
        (usedInputName.has(parameter.inputName) || usedPathWireName.has(parameter.name))
      ) {
        return [];
      }
      const inputName = cliBodyParameterInputName(contract, parameter, usedInputName);
      usedInputName.add(inputName);
      return [cliParameterBase(parameter, inputName, "body")];
    });
}

function rangeBoundOrder(name: string): number {
  const leaf = name.split(".").at(-1);
  if (leaf === "min") return 0;
  return leaf === "max" ? 1 : 2;
}

function cliParameterBase<Location extends OpenApiCommandParameter["location"]>(
  parameter: McpGenerationParameter,
  inputName: string,
  location: Location,
) {
  return {
    name: parameter.name,
    optionKey: inputName,
    flag: `${flagName(inputName)} <${cliPlaceholder(parameter.schemaType, parameter.itemSchemaType, parameter.schemaFormat, inputName)}>`,
    required: parameter.required && parameter.schemaDefault === undefined,
    description: cliOptionDescription(parameter.description, cliChoices(parameter)),
    schemaType: parameter.schemaType,
    schemaFormat: parameter.schemaFormat,
    itemSchemaType: parameter.itemSchemaType,
    defaultValue: cliDefaultValue(parameter.schemaDefault),
    choices: cliChoices(parameter),
    ...(parameter.visibility && { visibility: parameter.visibility }),
    location,
  };
}

const cliDefaultValue = (value: McpGenerationParameter["schemaDefault"]) => {
  if (Array.isArray(value)) return value.map(String);
  return typeof value === "number" ? String(value) : value;
};

const cliChoices = (parameter: McpGenerationParameter): readonly string[] | undefined =>
  parameter.itemSchemaEnum ?? parameter.schemaEnum;

function disambiguateCliPaths(contracts: readonly McpGenerationContract[]) {
  const cliPath = contracts.map((contract) => contract.projection.cliPath);
  const parentPath = new Set(
    cliPath
      .filter((candidate) =>
        cliPath.some(
          (other) =>
            other.length > candidate.length &&
            candidate.every((segment, index) => other[index] === segment),
        ),
      )
      .map((path) => path.join(" ")),
  );
  const normalized = contracts.map((contract) =>
    contract.method === "GET" && parentPath.has(contract.projection.cliPath.join(" "))
      ? withCliPath(contract, [...contract.projection.cliPath, defaultLeafSegment(contract)])
      : contract,
  );
  const contractsByPath = new Map<string, McpGenerationContract[]>();
  for (const contract of normalized) {
    const key = contract.projection.cliPath.join(" ");
    contractsByPath.set(key, [...(contractsByPath.get(key) ?? []), contract]);
  }
  const disambiguated = normalized.map((contract) => {
    const group = contractsByPath.get(contract.projection.cliPath.join(" "));
    const [primary] = group?.toSorted(compareDuplicateCliPathPriority) ?? [];
    return group === undefined || group.length <= 1 || primary === contract
      ? contract
      : withCliPath(contract, disambiguatedCliPath(contract));
  });
  return removeNamespaceCliAliases(disambiguated);
}

function withCliPath(
  contract: McpGenerationContract,
  cliPath: readonly string[],
): McpGenerationContract {
  return { ...contract, projection: { ...contract.projection, cliPath } };
}

function removeNamespaceCliAliases(contracts: readonly McpGenerationContract[]) {
  const reservedCliPath = new Set(
    contracts.flatMap((contract) =>
      [...contract.projection.cliPath.keys()].map((index) =>
        contract.projection.cliPath.slice(0, index + 1).join(" "),
      ),
    ),
  );
  return contracts.map((contract) =>
    contract.projection.cliAliasPath !== undefined &&
    reservedCliPath.has(contract.projection.cliAliasPath.join(" "))
      ? { ...contract, projection: { ...contract.projection, cliAliasPath: undefined } }
      : contract,
  );
}

const defaultLeafSegment = (contract: McpGenerationContract): string =>
  contract.method === "GET" && contract.operationId.startsWith("get") ? "get" : "list";

function compareDuplicateCliPathPriority(
  a: McpGenerationContract,
  b: McpGenerationContract,
): number {
  return (
    Number(b.projection.scope === "write") - Number(a.projection.scope === "write") ||
    pathParameterCount(a) - pathParameterCount(b) ||
    Number(a.requestBody !== undefined) - Number(b.requestBody !== undefined) ||
    b.path.length - a.path.length ||
    a.operationId.localeCompare(b.operationId)
  );
}

const pathParameterCount = (contract: McpGenerationContract): number =>
  contract.parameter.filter((parameter) => parameter.in === "path").length;

function disambiguatedCliPath(contract: McpGenerationContract): readonly string[] {
  const pathParameters = contract.parameter
    .filter((parameter) => parameter.in === "path")
    .map((parameter) => `by-${normalizeToolName(parameter.name)}`);
  const verb = contract.projection.cliPath.at(-1);
  const disambiguatedVerb =
    contract.requestBody !== undefined && verb !== undefined ? `${verb}-from-file` : verb;
  const prefix = contract.projection.cliPath.slice(0, -1);
  if (disambiguatedVerb !== undefined) return [...prefix, ...pathParameters, disambiguatedVerb];
  return pathParameters.length === 0
    ? [...contract.projection.cliPath, normalizeToolName(contract.operationId)]
    : [...contract.projection.cliPath, ...pathParameters];
}
