import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { mcpToolForIntent } from "../../config/tool-policy.ts";
import { MCP_GENERATION_CONTRACT } from "../../mcp-server/generated/mcp-generation-contract.ts";
import type { AventureMethod } from "../../api/client.ts";
import type { OperationIntent } from "../../config/tool-policy.ts";
import type { McpGenerationContract, OpenApiCommandSpec } from "../../mcp-server/contract.ts";

export interface UnifiedOperation {
  readonly operationId: string;
  readonly method: AventureMethod;
  readonly path: string;
  readonly resource: string;
  readonly intent: OperationIntent;
  readonly cliCommand: string;
  readonly cliPath: readonly string[];
  readonly cliAliasCommand: string | null;
  readonly cliAliasPath: readonly string[] | null;
  readonly mcpTool: string;
  readonly bodySchemaName: string | null;
  readonly bodySchemaImport: string | null;
  readonly auth: OpenApiCommandSpec["auth"];
  readonly scope: "read" | "write";
  readonly dryRunSupported: boolean;
  readonly destructive: boolean;
}

export interface UnifiedOperations {
  readonly schemaVersion: 1;
  readonly generatedFrom: string;
  readonly generatedAt: string;
  readonly totalOperations: number;
  readonly note: string;
  readonly operations: readonly UnifiedOperation[];
}

export interface UnifiedOperationsWriteResult {
  readonly target: string;
  readonly byteLength: number;
  readonly totalOperations: number;
}

export function buildUnifiedOperations(
  generatedAt: Date = new Date(),
  contracts: readonly McpGenerationContract[] = MCP_GENERATION_CONTRACT,
): UnifiedOperations {
  const operations = projectUnifiedOperations(contracts);
  return {
    schemaVersion: 1,
    generatedFrom: "mcp/mcp-server/generated/mcp-generation-contract.ts",
    generatedAt: generatedAt.toISOString(),
    totalOperations: operations.length,
    note: "Projection of MCP_GENERATION_CONTRACT - see mcp/scripts/build-unified-operations.ts header for SSOT rules.",
    operations,
  };
}

export function unifiedOperationsJson(payload: UnifiedOperations): string {
  return `${JSON.stringify(payload, null, 2)}\n`;
}

export function writeUnifiedOperationsJson(
  out: string,
  payload: UnifiedOperations = buildUnifiedOperations(),
): UnifiedOperationsWriteResult {
  const target = resolve(out);
  const body = unifiedOperationsJson(payload);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, body);
  return {
    target,
    byteLength: Buffer.byteLength(body, "utf8"),
    totalOperations: payload.totalOperations,
  };
}

function projectUnifiedOperations(
  contracts: readonly McpGenerationContract[],
): readonly UnifiedOperation[] {
  return contracts
    .map((contract) => ({
      operationId: contract.operationId,
      method: contract.method,
      path: contract.path,
      resource: contract.resource,
      intent: contract.intent,
      cliCommand: contract.projection.cliPath.join(" "),
      cliPath: contract.projection.cliPath,
      cliAliasCommand: contract.projection.cliAliasPath?.join(" ") ?? null,
      cliAliasPath: contract.projection.cliAliasPath ?? null,
      mcpTool: mcpToolForIntent(contract.intent),
      bodySchemaName: contract.requestBody?.schemaName ?? null,
      bodySchemaImport: contract.requestBody?.schemaImport ?? null,
      auth: contract.projection.auth,
      scope: contract.projection.scope,
      dryRunSupported: contract.projection.dryRun,
      destructive: contract.projection.destructive,
    }))
    .toSorted(
      (left, right) =>
        left.path.localeCompare(right.path) ||
        left.method.localeCompare(right.method) ||
        left.operationId.localeCompare(right.operationId),
    );
}
