import type { Option } from "commander";
import {
  cliOptionDescription,
  generatedOptionGroupRank,
  generatedOptionHelpGroup,
  withTerminalPunctuation,
  type GeneratedOptionHelpEntry,
} from "../../config/cli-help-policy.ts";
import { firstArrayItemPath } from "./generated-body-path.ts";

export type GeneratedOptionOrderEntry = GeneratedOptionHelpEntry & {
  readonly optionKey: string;
  readonly flag?: string;
  readonly required?: boolean;
};

export function orderedGeneratedOptions<T extends GeneratedOptionOrderEntry>(
  items: readonly T[],
): readonly T[] {
  return [...items].toSorted(compareGeneratedOption);
}

export function applyGeneratedOptionHelpLayout(
  options: readonly Option[],
  entries: readonly GeneratedOptionOrderEntry[],
): void {
  const entriesByLongFlag = new Map<string, GeneratedOptionOrderEntry>();
  for (const entry of entries) {
    const flag = entry.flag?.split(" ")[0];
    if (flag !== undefined) {
      entriesByLongFlag.set(flag, flag === "--from-file" ? { ...entry, inputType: "file" } : entry);
    }
  }
  for (const option of options) {
    const entry = option.long === undefined ? undefined : entriesByLongFlag.get(option.long);
    if (entry !== undefined) option.helpGroup(generatedOptionHelpGroup(entry));
  }
  const mutableOptions = options as Option[];
  mutableOptions.sort((left: Option, right: Option) => {
    const leftEntry = left.long === undefined ? undefined : entriesByLongFlag.get(left.long);
    const rightEntry = right.long === undefined ? undefined : entriesByLongFlag.get(right.long);
    if (leftEntry !== undefined && rightEntry !== undefined) {
      return compareGeneratedOption(leftEntry, rightEntry);
    }
    if (leftEntry !== undefined) return -1;
    if (rightEntry !== undefined) return 1;
    return 0;
  });
}

type GeneratedBodyHelpSpec = {
  readonly bodyKind?: string;
};

export function generatedBodyFileDescription(
  spec: GeneratedBodyHelpSpec,
  requiredBodyPath: readonly string[],
): string {
  const description =
    spec.bodyKind === "multipart"
      ? "Read a JSON object keyed by multipart part name from a file, or use - for stdin"
      : "Read the JSON request body from a file, or use - for stdin";
  // A file body must carry the required leaf, not just the object that contains it, so a container
  // path is dropped whenever a deeper required path already names what has to be inside it.
  const requiredFilePath = requiredBodyPath.filter(
    (path) =>
      !requiredBodyPath.some(
        (candidate) => candidate.startsWith(`${path}.`) || candidate.startsWith(`${path}[].`),
      ),
  );
  return requiredFilePath.length === 0
    ? withTerminalPunctuation(description)
    : `${withTerminalPunctuation(description)} Required JSON paths: ${requiredFilePath.join(", ")}.`;
}

export function generatedBodyOptionDescription(
  spec: GeneratedBodyHelpSpec,
  parameter: GeneratedOptionOrderEntry & { readonly name: string; readonly description: string },
  bodyParameters: readonly { readonly name: string }[],
): string {
  const base = cliOptionDescription(parameter.description, undefined);
  const repeat =
    spec.bodyKind !== "multipart" && parameter.name === firstArrayItemPath(bodyParameters);
  return `${base}${repeat ? " Repeat to add another value." : ""}`;
}

export function compareGeneratedOption(
  left: GeneratedOptionOrderEntry,
  right: GeneratedOptionOrderEntry,
): number {
  return (
    generatedOptionGroupRank(left) - generatedOptionGroupRank(right) ||
    Number(left.required !== true) - Number(right.required !== true)
  );
}
