import { JsonValueSchema, type JsonValue } from "@aventurevc/api-schemas/http/json-value";
import { InvalidArgumentError, Option, type Command } from "commander";
import { failure, success, type ResultEnvelope } from "../../api/result-envelope.ts";
import type {
  OpenApiCommandParameter as GeneratedBodyParameter,
  OpenApiCommandSpec as GeneratedCommandSpec,
} from "../../mcp-server/contract.ts";
import {
  applyGeneratedOptionHelpLayout,
  generatedBodyFileDescription,
  generatedBodyOptionDescription,
  orderedGeneratedOptions,
  type GeneratedOptionOrderEntry,
} from "./generated-option-order.ts";
import {
  assignBodyParameter,
  hasBodyPath,
  isArrayItemPath,
  isJsonBody,
  requiredBodyFilePath,
  unknownBodyFilePath,
  type JsonBody,
} from "./generated-body-path.ts";
import { readJsonBody } from "./json-input.ts";

export type GeneratedCommandOptionValue = string | readonly string[] | boolean | undefined;
export type GeneratedCommandOpts = Readonly<Record<string, GeneratedCommandOptionValue>>;

export function addBodyOptions(command: Command, spec: GeneratedCommandSpec): void {
  if (supportsBodyFile(spec)) {
    command.addOption(
      new Option(
        "--from-file <path>",
        // Help names every required path the file itself must carry, including paths a direct
        // body flag can also satisfy; `requiredBodyFilePath` is the validation view, not this one.
        generatedBodyFileDescription(spec, spec.bodyRequiredPath),
      ).argParser(rejectRepeatedBodyOption("--from-file")),
    );
  }
  const bodyParameters = orderedGeneratedOptions(spec.bodyParameters ?? []);
  for (const parameter of bodyParameters) {
    const option = new Option(
      parameter.flag,
      generatedBodyOptionDescription(spec, parameter, bodyParameters),
    );
    const conflicts = bodyOptionConflicts(spec, parameter.optionKey);
    if (conflicts.length > 0) option.conflicts(conflicts);
    if (isArrayItemPath(parameter.name) || parameter.schemaType === "array")
      option.argParser(collectRepeatedBodyOption);
    else option.argParser(rejectRepeatedBodyOption(parameter.flag));
    command.addOption(option);
  }
  organizeGeneratedOptions(command, spec);
}

/** Expands conflict groups into the peer Commander attribute names for one generated option. */
function bodyOptionConflicts(spec: GeneratedCommandSpec, optionKey: string): string[] {
  return [
    ...new Set(
      (spec.cliConflicts ?? [])
        .filter((group) => group.includes(optionKey))
        .flatMap((group) => group.filter((candidate) => candidate !== optionKey)),
    ),
  ];
}

function collectRepeatedBodyOption(
  value: string,
  previous: readonly string[] | undefined,
): readonly string[] {
  return [...(previous ?? []), value];
}

/**
 * Non-variadic generated options take exactly one value; a silent last-wins overwrite hides the
 * caller's mistake, so a repeated flag is a usage error instead.
 */
function rejectRepeatedBodyOption(
  flag: string,
): (value: string, previous: string | undefined) => string {
  const optionName = flag.split(/\s+/u)[0] ?? flag;
  return (value: string, previous: string | undefined): string => {
    if (previous !== undefined) {
      throw new InvalidArgumentError(`${optionName} was already given; pass it once.`);
    }
    return value;
  };
}

/** Reads generated body inputs and rejects a root shape that contradicts OpenAPI metadata. */
export async function readGeneratedBody(
  spec: GeneratedCommandSpec,
  opts: GeneratedCommandOpts,
): Promise<ResultEnvelope<JsonValue | undefined>> {
  if (!spec.hasBody) return success("No body", undefined);
  if (spec.bodyKind === "multipart") return await readMultipartBody(spec, opts);
  const fromFile = await readBodyFile(opts);
  if (!fromFile.ok) return fromFile;
  const filePath = validateBodyFilePath(spec, fromFile.data);
  if (!filePath.ok) return filePath;
  const direct = readDirectBody(spec, opts);
  if (!direct.ok) return direct;
  if (fromFile.data === undefined && direct.data === undefined)
    return spec.bodyRequired
      ? failure(jsonBodyRequiredMessage(spec))
      : success("No body", undefined);
  const merged = mergeJsonBodies(spec, fromFile.data, direct.data);
  if (!merged.ok || merged.data === undefined) return merged;
  if (spec.bodySchemaType === "array" && !Array.isArray(merged.data)) {
    return failure(`${spec.operationId} requires a JSON array body.`);
  }
  if ((spec.bodyParameters?.length ?? 0) > 0 && !isJsonBody(merged.data)) {
    return failure(`${spec.operationId} requires a JSON object body.`);
  }
  const missing = missingRequiredBodyOption(spec, merged.data);
  if (missing.length > 0) {
    return failure(`${spec.operationId} requires body option(s): ${missing.join(", ")}`);
  }
  const body = merged.data;
  const missingPath = isJsonBody(body)
    ? requiredBodyFilePath(spec).filter((path) => !hasBodyPath(body, path))
    : [];
  if (missingPath.length > 0) {
    return failure(requiredJsonBodyPathMessage(spec, missingPath));
  }
  return merged;
}

async function readMultipartBody(
  spec: GeneratedCommandSpec,
  opts: GeneratedCommandOpts,
): Promise<ResultEnvelope<JsonValue | undefined>> {
  const fromFile = await readBodyFile(opts);
  if (!fromFile.ok) return fromFile;
  const filePath = validateBodyFilePath(spec, fromFile.data);
  if (!filePath.ok) return filePath;
  const direct = readDirectBody(spec, opts);
  if (!direct.ok) return direct;
  if (fromFile.data === undefined && direct.data === undefined)
    return spec.bodyRequired
      ? failure(jsonBodyRequiredMessage(spec))
      : success("No body", undefined);
  const merged = mergeJsonBodies(spec, fromFile.data, direct.data);
  if (!merged.ok || merged.data === undefined) return merged;
  const body = merged.data;
  if (!isJsonBody(body)) {
    return failure(`${spec.operationId} requires a JSON object keyed by multipart part name.`);
  }
  const missingPath = requiredBodyFilePath(spec).filter((path) => !hasBodyPath(body, path));
  return missingPath.length === 0
    ? merged
    : failure(requiredJsonBodyPathMessage(spec, missingPath));
}

function requiredJsonBodyPathMessage(
  spec: GeneratedCommandSpec,
  missingPath: readonly string[],
): string {
  const message = `${spec.operationId} requires JSON body path(s): ${missingPath.join(", ")}`;
  if (spec.bodyKind !== "multipart") return message;
  const hint = missingPath.includes("body")
    ? 'For multipart --from-file, wrap the endpoint JSON under top-level "body".'
    : 'For multipart --from-file, put the missing nested path(s) inside top-level "body".';
  return `${message}. ${hint}`;
}

function missingRequiredBodyOption(
  spec: GeneratedCommandSpec,
  directBody: JsonValue,
): readonly string[] {
  if (!isJsonBody(directBody)) return [];
  return (spec.bodyParameters ?? [])
    .filter((parameter) => parameter.required && !hasBodyPath(directBody, parameter.name))
    .map((parameter) => parameter.flag.split(" ")[0] ?? parameter.name);
}

function validateBodyFilePath(
  spec: GeneratedCommandSpec,
  body: JsonValue | undefined,
): ResultEnvelope<null> {
  const unknown = unknownBodyFilePath(spec, body);
  if (unknown === null) return success("Body file paths validated", null);
  const hint =
    unknown.suggestion === undefined
      ? ""
      : ` Use ${unknown.suggestion.path} (${unknown.suggestion.flag}).`;
  return failure(
    `${spec.operationId} --from-file contains unknown JSON path ${unknown.path}.${hint}`,
  );
}

async function readBodyFile(
  opts: GeneratedCommandOpts,
): Promise<ResultEnvelope<JsonValue | undefined>> {
  const file = typeof opts.fromFile === "string" ? opts.fromFile : undefined;
  if (file === undefined) return success("No body file", undefined);
  const raw = await readJsonBody(file);
  if (!raw.ok) return failure(raw.summary, raw.warnings);
  const parsed = JsonValueSchema.safeParse(raw.data);
  return parsed.success
    ? success("Input parsed", parsed.data)
    : failure(`Input is not valid JSON value: ${parsed.error.message}`);
}

function readDirectBody(
  spec: GeneratedCommandSpec,
  opts: GeneratedCommandOpts,
): ResultEnvelope<JsonValue | undefined> {
  const body: JsonBody = {};
  let hasOptions = false;
  for (const parameter of spec.bodyParameters ?? []) {
    const value = opts[parameter.optionKey];
    if (value === undefined) continue;
    const coerced = coerceBodyValue(parameter, value);
    if (!coerced.ok) return failure(coerced.summary, coerced.warnings);
    const assigned = assignBodyParameter(body, parameter.name, coerced.data);
    if (!assigned.ok) return assigned;
    hasOptions = true;
  }
  if (!hasOptions) return success("No direct body options", undefined);
  return success("Direct body options parsed", body);
}

function mergeJsonBodies(
  spec: GeneratedCommandSpec,
  fileBody: JsonValue | undefined,
  directBody: JsonValue | undefined,
): ResultEnvelope<JsonValue | undefined> {
  if (fileBody === undefined) return success("Direct body parsed", directBody);
  if (directBody === undefined) return success("Input parsed", fileBody);
  if (isJsonBody(fileBody) && isJsonBody(directBody)) {
    try {
      return success("Input parsed", mergeJsonBody(fileBody, directBody));
    } catch (cause) {
      return failure(`${spec.operationId} ${(cause as Error).message}`);
    }
  }
  return failure(
    `${spec.operationId} cannot combine --from-file with direct body options unless the file body is an object.`,
  );
}

function mergeJsonBody(fileBody: JsonBody, directBody: JsonBody): JsonBody {
  const merged: JsonBody = { ...fileBody };
  for (const [key, value] of Object.entries(directBody)) {
    const current = merged[key];
    if (Array.isArray(current) && Array.isArray(value))
      throw new Error(
        `cannot combine --from-file array '${key}' with array body options at the same key — move the per-item fields inside the matching '${key}[]' object(s) in the file body.`,
      );
    if (current !== undefined && jsonBodyShape(current) !== jsonBodyShape(value))
      throw new Error(
        `cannot combine --from-file ${jsonBodyShape(current)} '${key}' with ${jsonBodyShape(value)} body option(s) at the same key — align the file body shape with the schema.`,
      );
    merged[key] = isJsonBody(current) && isJsonBody(value) ? mergeJsonBody(current, value) : value;
  }
  return merged;
}

function jsonBodyShape(value: JsonValue): "array" | "object" | "scalar" {
  if (Array.isArray(value)) return "array";
  return isJsonBody(value) ? "object" : "scalar";
}

function coerceBodyValue(
  parameter: GeneratedBodyParameter,
  value: GeneratedCommandOptionValue,
): ResultEnvelope<JsonValue> {
  if (typeof value === "boolean") return success("Body value parsed", value);
  if (value === undefined || typeof value === "string") {
    return coerceScalar(parameter.name, parameter.schemaType, value ?? "");
  }
  const entries: JsonValue[] = [];
  const schemaType = isArrayItemPath(parameter.name)
    ? parameter.schemaType
    : parameter.itemSchemaType;
  for (const entry of value) {
    const coerced = coerceScalar(parameter.name, schemaType, entry);
    if (!coerced.ok) return coerced;
    entries.push(coerced.data);
  }
  return success("Body value parsed", entries);
}

function coerceScalar(
  parameterName: string,
  schemaType: string | undefined,
  value: string,
): ResultEnvelope<JsonValue> {
  if (schemaType === "boolean") {
    if (value === "true") return success("Body value parsed", true);
    if (value === "false") return success("Body value parsed", false);
    return failure(`${parameterName} must be true or false.`);
  }
  if (schemaType === "number" || schemaType === "integer") {
    const trimmed = value.trim();
    const parsed = Number(trimmed);
    if (trimmed === "" || !Number.isFinite(parsed)) {
      return failure(`${parameterName} must be a finite ${schemaType}.`);
    }
    if (schemaType === "integer" && !Number.isInteger(parsed)) {
      return failure(`${parameterName} must be an integer.`);
    }
    return success("Body value parsed", parsed);
  }
  return success("Body value parsed", value);
}

function jsonBodyRequiredMessage(spec: GeneratedCommandSpec): string {
  const filePath = requiredBodyFilePath(spec);
  if (filePath.length > 0) {
    return `${spec.operationId} requires --from-file with JSON body path(s): ${filePath.join(", ")}`;
  }
  const direct = (spec.bodyParameters ?? [])
    .map((parameter) => parameter.flag.split(" ")[0])
    .join(", ");
  return direct.length === 0
    ? `${spec.operationId} requires --from-file`
    : `${spec.operationId} requires --from-file or body option(s): ${direct}`;
}

function organizeGeneratedOptions(command: Command, spec: GeneratedCommandSpec): void {
  const entries: GeneratedOptionOrderEntry[] = [...spec.parameters, ...(spec.bodyParameters ?? [])];
  if (supportsBodyFile(spec)) {
    entries.push({
      optionKey: "fromFile",
      flag: "--from-file",
      location: "body",
    });
  }
  applyGeneratedOptionHelpLayout(command.options, entries);
}

function supportsBodyFile(spec: GeneratedCommandSpec): boolean {
  if (!spec.hasBody) return false;
  if (spec.bodyKind !== "multipart") return true;
  return (spec.bodyParameters ?? []).some((parameter) => parameter.schemaFormat !== "binary");
}
