/**
 * Built-in (non-generated) CLI selftest: `aventure-cli auth doctor`.
 *
 * Sibling of `builtin-auth.ts` / `builtin-update.ts` — a local diagnostic with no API contract, so
 * nothing to generate from a Kotlin `@Schema` owner. One call answers the questions an agent would
 * otherwise resolve by trial (running CLI current? installed schema contracts complete? API host
 * answering? which credential scope materialized? does the offline catalog still carry the status
 * operation?) as a check list any caller can branch on: `{ ok, check: [{ name, status, message }] }`.
 *
 * Every failing message names the next command. Exit is 0 only when no check failed; skipped checks
 * (no registry reachable) do not fail the run.
 */
import type { SystemStatus } from "@aventurevc/api-schemas/system/status";
import { Command } from "commander";

import packageJson from "../../package.json" with { type: "json" };
import {
  configPath,
  materializeAuth,
  readAuthConfig,
  resolveAuthStatus,
  type AuthResolutionMap,
} from "../../api/auth-resolver.ts";
import { AUTH_SECRET_NAMES, readEnv, type AuthSecretName } from "../../api/env.ts";
import { runOpenApiCall, type OpenApiCallContent } from "../../api/openapi-call.ts";
import { failure, success, type ResultEnvelope } from "../../api/result-envelope.ts";
import type { OpenApiCommandSpec } from "../../mcp-server/contract.ts";
import { emit } from "../output.ts";
import { addOutputModeOptions, resolveOutputMode, type CliOutputOptions } from "../output-mode.ts";
import { credentialSafeMessage } from "../auth/credential-redaction.ts";
import {
  canonicalPersonalCredentialHost,
  loadPersonalCredential,
  type PersonalCredentialLookup,
} from "../auth/personal-credential.ts";
import {
  GENERATED_OPENAPI_COMMAND_SPECS,
  GENERATED_OPERATION_FINGERPRINT,
} from "../generated/openapi-commands.ts";
import { runUpdate } from "./builtin-update.ts";

/**
 * The selftest inventory, in report order. Check names and the `--help` list read from here, and
 * `DoctorCheckName` types every result against it, so a renamed check stops compiling. The emitted
 * order is asserted against this list in `__tests__/cli/doctor.test.ts`.
 */
export const DOCTOR_CHECK = [
  { name: "cli-version", purpose: "running CLI against the latest published release" },
  { name: "api-schemas", purpose: "the installed @aventurevc/api-schemas contracts resolve" },
  { name: "api-host", purpose: "the selected API host answers its generated status operation" },
  { name: "auth", purpose: "which credential scope materialized locally, never the secret" },
  { name: "catalog", purpose: "this catalog was generated from the operation set the API serves" },
] as const;

/** Read from the canonical status contract, so a rename there stops compiling here. */
const SERVED_FINGERPRINT_FIELD = "operationFingerprint" satisfies keyof SystemStatus;

type DoctorCheckName = (typeof DOCTOR_CHECK)[number]["name"];
type DoctorCheckStatus = "pass" | "fail" | "skip";

/** One selftest answer: what was probed, how it came out, and the next command when it failed. */
export type DoctorCheck = {
  readonly name: DoctorCheckName;
  readonly status: DoctorCheckStatus;
  readonly message: string;
};

/** The report payload: the overall verdict plus every check, in `DOCTOR_CHECK` order. */
export type DoctorReport = {
  readonly ok: boolean;
  readonly check: readonly DoctorCheck[];
};

export function registerBuiltinDoctorCommand(parent: Command): void {
  addOutputModeOptions(
    parent
      .command("doctor")
      .summary("One-call selftest: CLI version, schemas, API host, auth scope, command catalog")
      .description(
        [
          "Run every environment check in one call and report `{ ok, check: [...] }`:",
          ...DOCTOR_CHECK.map((entry) => `  - ${entry.name}: ${entry.purpose}`),
          "",
          "Exit code is 0 only when no check failed; a skipped check (no registry reachable)",
          "does not fail the run. Each failing message names the command that fixes it.",
          "--json always carries the report at `.data`; --data prints the report directly when",
          "every check passes and the result envelope when one fails, like every other command.",
        ].join("\n"),
      ),
  ).action(async function (this: Command, opts: CliOutputOptions) {
    // Root --environment is validated by its own choices() list; apply it like builtin-auth does.
    const globals = this.optsWithGlobals<{ readonly environment?: string }>();
    if (globals.environment !== undefined) process.env.API_ENV = globals.environment;
    emit({ mode: resolveOutputMode(opts) }, await doctorEnvelope());
  });
}

async function doctorEnvelope(): Promise<ResultEnvelope<DoctorReport>> {
  const statusSpec = generatedStatusSpec();
  // `api-schemas` and `api-host` are independent I/O and run together; `cli-version` shells out
  // synchronously, and `auth` runs last because it reports state the earlier calls can populate.
  const cliVersion = cliVersionCheck();
  const [apiSchemas, apiHost] = await Promise.all([apiSchemasCheck(), apiHostCheck(statusSpec)]);
  const check: readonly DoctorCheck[] = [
    cliVersion.check,
    apiSchemas,
    apiHost.check,
    await authCheck(),
    catalogCheck(statusSpec, apiHost.servedFingerprint, cliVersion.upgradeAvailable),
  ];
  const counts = {
    pass: countStatus(check, "pass"),
    fail: countStatus(check, "fail"),
    skip: countStatus(check, "skip"),
  };
  const failureMessage = check
    .filter((entry) => entry.status === "fail")
    .map((entry) => entry.message);
  const report: DoctorReport = { ok: failureMessage.length === 0, check };
  const summary = [
    `doctor: ${counts.pass} pass, ${counts.fail} fail, ${counts.skip} skip`,
    ...check.map((entry) => `  ${entry.name} ${entry.status} — ${entry.message}`),
  ].join("\n");
  return report.ok
    ? success(summary, report, { counts })
    : { ...failure(summary, failureMessage, { counts }), data: report };
}

function countStatus(check: readonly DoctorCheck[], status: DoctorCheckStatus): number {
  return check.filter((entry) => entry.status === status).length;
}

function checkResult(
  name: DoctorCheckName,
  status: DoctorCheckStatus,
  message: string,
): DoctorCheck {
  return { name, status, message };
}

/**
 * The status operation resolved from the generated catalog the same way the MCP server resolves it
 * from its own contract (`mcp/scripts/build-mcp.ts` callStatus): intent and resource both `status`,
 * never a hand-coded route. `undefined` means this catalog lost it, which the catalog check reports.
 */
function generatedStatusSpec(): OpenApiCommandSpec | undefined {
  return GENERATED_OPENAPI_COMMAND_SPECS.find(
    (spec) => spec.intent === "status" && spec.resource === "status",
  );
}

/**
 * `upgradeAvailable` is null when the registry could not answer, so a caller cannot mistake
 * "no newer release" for "unknown".
 */
function cliVersionCheck(): {
  readonly check: DoctorCheck;
  readonly upgradeAvailable: boolean | null;
} {
  const update = runUpdate({});
  if (!update.ok || update.data === null) {
    return {
      check: checkResult(
        "cli-version",
        "skip",
        `Could not compare ${packageJson.version} against the registry (${update.summary}); rerun \`aventure-cli update\` with registry access.`,
      ),
      upgradeAvailable: null,
    };
  }
  const { targetPackage, currentVersion, latestVersion, upgradeAvailable } = update.data;
  return {
    check: upgradeAvailable
      ? checkResult(
          "cli-version",
          "fail",
          `Upgrade ${targetPackage} from ${currentVersion} to ${latestVersion}: run \`aventure-cli update --execute\`.`,
        )
      : checkResult(
          "cli-version",
          "pass",
          `${targetPackage} ${currentVersion} matches the latest published release.`,
        ),
    upgradeAvailable,
  };
}

/**
 * Probe a schema module that nothing on the CLI's startup path imports, so a partially built or
 * partially installed `@aventurevc/api-schemas` is detectable here. Probing a module the CLI itself
 * loads at startup would prove nothing: that failure kills the process before Commander dispatches,
 * so no check could ever report it.
 */
async function apiSchemasCheck(): Promise<DoctorCheck> {
  try {
    const { EntityDetailSchema } = await import("@aventurevc/api-schemas/entity/detail");
    if (typeof EntityDetailSchema.safeParse !== "function") {
      throw new Error("EntityDetailSchema does not expose a Zod parser");
    }
    return checkResult(
      "api-schemas",
      "pass",
      "Installed @aventurevc/api-schemas contracts resolve beyond the CLI startup path.",
    );
  } catch (error) {
    return checkResult(
      "api-schemas",
      "fail",
      `Reinstall the CLI: run \`aventure-cli update --execute\` — ${credentialSafeMessage(error)}.`,
    );
  }
}

/**
 * The status operation answers two questions in one call: is the host reachable, and which
 * operation set does it serve. The catalog check reads the served fingerprint from the same
 * response rather than calling again.
 */
async function apiHostCheck(
  statusSpec: OpenApiCommandSpec | undefined,
): Promise<{ readonly check: DoctorCheck; readonly servedFingerprint: string | null }> {
  if (statusSpec === undefined) {
    return {
      check: checkResult(
        "api-host",
        "skip",
        "No status operation resolved from the generated catalog; fix the catalog check first.",
      ),
      servedFingerprint: null,
    };
  }
  let host: string;
  try {
    host = readEnv().host;
  } catch (error) {
    return {
      check: checkResult(
        "api-host",
        "fail",
        `Correct API_ENV or pass \`--environment <name>\` — ${credentialSafeMessage(error)}.`,
      ),
      servedFingerprint: null,
    };
  }
  const envelope = await runOpenApiCall({
    method: statusSpec.method,
    path: statusSpec.path,
    auth: statusSpec.auth,
    execute: true,
    responseFormat: "json",
  }).catch((error: unknown) => failure(credentialSafeMessage(error)));
  return envelope.ok
    ? {
        check: checkResult(
          "api-host",
          "pass",
          `${statusSpec.method} ${statusSpec.path} answered at ${host}.`,
        ),
        servedFingerprint: servedOperationFingerprint(envelope.data),
      }
    : {
        check: checkResult(
          "api-host",
          "fail",
          `Point the CLI at a reachable API host with \`--environment <name>\` or API_URL, then rerun \`aventure-cli auth doctor\` — ${statusSpec.method} ${statusSpec.path} at ${host} returned ${envelope.summary}.`,
        ),
        servedFingerprint: null,
      };
}

/**
 * `operationFingerprint` off the status response, and only that field. Validating the whole
 * `SystemStatus` shape as a precondition would disable the drift check exactly when it matters: a
 * client stale enough to disagree about the operation set is the client most likely to disagree
 * about the rest of the payload, and the read would silently degrade to "unproven".
 */
function servedOperationFingerprint(content: OpenApiCallContent): string | null {
  if (typeof content !== "object" || content === null) return null;
  const { response } = content;
  if (typeof response !== "object" || response === null || Array.isArray(response)) return null;
  const fingerprint = response[SERVED_FINGERPRINT_FIELD];
  return typeof fingerprint === "string" && fingerprint.length > 0 ? fingerprint : null;
}

/**
 * Report which credential scope a real call would use, never the credential. Saved auth is
 * materialized first (idempotent, non-fatal) so the answer never depends on whether an earlier
 * check happened to trigger it.
 */
async function authCheck(): Promise<DoctorCheck> {
  await materializeAuth();
  let resolved: AuthResolutionMap;
  try {
    resolved = resolveAuthStatus(await readAuthConfig());
  } catch (error) {
    return checkResult(
      "auth",
      "fail",
      `Repair or remove ${configPath()} and run \`aventure-cli auth init\` — ${credentialSafeMessage(error)}.`,
    );
  }
  const personal = await inspectPersonalCredential();
  if (AUTH_SECRET_NAMES.some((name) => resolved[name].present) || personal.state === "found") {
    return checkResult(
      "auth",
      "pass",
      `Credential scope materialized: ${scopeText(resolved, personal)}.`,
    );
  }
  if (personal.state === "unavailable") {
    if (personal.cause === "environment") {
      return checkResult(
        "auth",
        "fail",
        `Fix the environment configuration first — ${personal.summary}.`,
      );
    }
    return checkResult(
      "auth",
      "fail",
      `Unlock OS credential storage before \`aventure-cli auth login\`, or inject ${AUTH_SECRET_NAMES.join("/")} through the environment — ${personal.summary}.`,
    );
  }
  return AUTH_SECRET_NAMES.some((name) => resolved[name].source === "config")
    ? checkResult(
        "auth",
        "fail",
        `The Doppler source in ${configPath()} resolved no credential: confirm your access to that project and config, or inject ${AUTH_SECRET_NAMES.join("/")} through the environment.`,
      )
    : checkResult(
        "auth",
        "fail",
        "Run `aventure-cli auth login` for a personal credential, or `aventure-cli auth init` to select a Doppler source.",
      );
}

async function inspectPersonalCredential(): Promise<PersonalCredentialLookup> {
  let canonicalHost: string;
  try {
    canonicalHost = canonicalPersonalCredentialHost(readEnv().host);
  } catch (error) {
    return { state: "unavailable", summary: credentialSafeMessage(error), cause: "environment" };
  }
  try {
    return await loadPersonalCredential(canonicalHost);
  } catch (error) {
    return { state: "unavailable", summary: credentialSafeMessage(error), cause: "keyring" };
  }
}

/** The three-way provenance `auth status` renders: resolved source, configured-but-unresolved, unset. */
function scopeText(resolved: AuthResolutionMap, personal: PersonalCredentialLookup): string {
  const credential = AUTH_SECRET_NAMES.map((name) => `${name}=${credentialText(resolved, name)}`);
  return [...credential, `personal=${personalText(personal)}`].join(" ");
}

function credentialText(resolved: AuthResolutionMap, name: AuthSecretName): string {
  const resolution = resolved[name];
  if (resolution.present) return resolution.source ?? "resolved";
  return resolution.source === "config" ? "config (unresolved)" : "unset";
}

function personalText(personal: PersonalCredentialLookup): string {
  if (personal.state === "found") return personal.stored.activation;
  return personal.state === "missing" ? "unset" : "unavailable";
}

/**
 * Catalog-vs-API drift. Both sides reduce the served operation set to the same short hash — the API
 * from its registered handlers, this catalog from the OpenAPI document it was generated from — so an
 * unequal pair means this CLI describes operations the deployment no longer serves, or misses ones
 * it does.
 *
 * A mismatch only *fails* when a newer CLI is published, because only then can the caller fix it.
 * Deploys and CLI releases are independent here: the API ships on every merge, the packages ship on
 * an explicit release lane, so "the newest published CLI predates the current deployment" is an
 * ordinary steady state. Failing there would exit non-zero on every machine until someone published,
 * and `aventure-cli update` would answer "already at latest" — a verdict no caller could clear.
 */
function catalogCheck(
  statusSpec: OpenApiCommandSpec | undefined,
  servedFingerprint: string | null,
  upgradeAvailable: boolean | null,
): DoctorCheck {
  const total = GENERATED_OPENAPI_COMMAND_SPECS.length;
  if (statusSpec === undefined) {
    return checkResult(
      "catalog",
      "fail",
      `Regenerate the command catalog with \`make mcp-generate-contracts\` and reinstall: none of its ${total} operations is the status operation.`,
    );
  }
  if (servedFingerprint === null) {
    return checkResult(
      "catalog",
      "skip",
      `Could not read the served operation fingerprint, so drift is unproven; this catalog holds ${total} operations at ${GENERATED_OPERATION_FINGERPRINT}.`,
    );
  }
  if (servedFingerprint === GENERATED_OPERATION_FINGERPRINT) {
    return checkResult(
      "catalog",
      "pass",
      `${total} generated operations match the set the API serves (${GENERATED_OPERATION_FINGERPRINT}).`,
    );
  }
  const drift = `This catalog describes a different operation set than the API serves (${GENERATED_OPERATION_FINGERPRINT} vs ${servedFingerprint})`;
  if (upgradeAvailable === true) {
    return checkResult("catalog", "fail", `${drift}: run \`aventure-cli update --execute\`.`);
  }
  return checkResult(
    "catalog",
    "skip",
    upgradeAvailable === false
      ? `${drift}, and no published release describes it yet: the CLI needs publishing (\`make npm-publish-train\`) before any caller can match this deployment.`
      : `${drift}, and the registry did not answer, so it is unknown whether a newer release describes it: rerun \`aventure-cli update\` with registry access.`,
  );
}
