/** Local, non-generated credential setup and diagnostic commands. */
import { stdin as input, stderr as prompts } from "node:process";
import { createInterface } from "node:readline/promises";

import { SystemBuildSchema } from "@aventurevc/api-schemas/system/system-build";
import { Command } from "commander";

import packageJson from "../../package.json" with { type: "json" };
import {
  configPath,
  materializeAuth,
  readAuthConfig,
  resolveAuthStatus,
  writeAuthConfig,
  type AuthResolutionMap,
  type DopplerSource,
} from "../../api/auth-resolver.ts";
import { AUTH_SECRET_NAMES, prepareCallEnv, readEnv, type AuthSecretName } from "../../api/env.ts";
import { runOpenApiCall } from "../../api/openapi-call.ts";
import { failure, success, type ResultEnvelope } from "../../api/result-envelope.ts";
import { openApiCompositeSpec, type OpenApiCompositeSpec } from "../../mcp-server/contract.ts";
import { emit } from "../output.ts";
import { addOutputModeOptions, resolveOutputMode, type CliOutputOptions } from "../output-mode.ts";
import { credentialSafeMessage, redactCredentialText } from "../auth/credential-redaction.ts";
import {
  canonicalPersonalCredentialHost,
  loadPersonalCredential,
  type PersonalCredentialLookup,
} from "../auth/personal-credential.ts";
import { loginPersonalCredential } from "../auth/personal-login.ts";
import { logoutPersonalCredential } from "../auth/personal-logout.ts";
import { GENERATED_OPENAPI_COMPOSITE_SPECS } from "../generated/openapi-composites.ts";
import { registerBuiltinAgentSetupCommand } from "./builtin-agent-setup.ts";
import { registerBuiltinDoctorCommand } from "./builtin-doctor.ts";

type AuthLoginCommandOptions = CliOutputOptions & {
  readonly browser: boolean;
  readonly clientLabel?: string;
};

type AuthLogoutCommandOptions = CliOutputOptions & {
  readonly forgetLocal?: boolean;
};

const AUTH_LOGIN_START = openApiCompositeSpec(GENERATED_OPENAPI_COMPOSITE_SPECS, "start");
const AUTH_LOGIN_POLL = openApiCompositeSpec(GENERATED_OPENAPI_COMPOSITE_SPECS, "poll");
const AUTH_LOGIN_ACKNOWLEDGE = openApiCompositeSpec(
  GENERATED_OPENAPI_COMPOSITE_SPECS,
  "acknowledge",
);
const AUTH_LOGOUT_REVOKE = openApiCompositeSpec(GENERATED_OPENAPI_COMPOSITE_SPECS, "revoke");

export function registerBuiltinAuthCommands(parent: Command): void {
  const auth = authCommand(parent);
  registerBuiltinDoctorCommand(auth);
  // `agents setup` belongs to the generated `agents` namespace, not to `auth`; it is chained from
  // the one built-in registration that already receives the root program, because `index.ts` is
  // closed to agent edits [MCP1b.1] and cannot gain a registration line of its own.
  registerBuiltinAgentSetupCommand(parent);

  addOutputModeOptions(
    compositeCommand(
      auth,
      AUTH_LOGIN_START,
      [AUTH_LOGIN_START, AUTH_LOGIN_POLL, AUTH_LOGIN_ACKNOWLEDGE]
        .map(({ description }) => description)
        .join("\n"),
    ),
  ).action(async function (this: Command, opts: AuthLoginCommandOptions) {
    forwardEnvironment(this);
    emit(
      { mode: resolveOutputMode(opts) },
      await loginPersonalCredential({
        noBrowser: !opts.browser,
        clientLabel: opts.clientLabel,
      }),
    );
  });

  addOutputModeOptions(
    compositeCommand(auth, AUTH_LOGOUT_REVOKE, AUTH_LOGOUT_REVOKE.description),
  ).action(async function (this: Command, opts: AuthLogoutCommandOptions) {
    forwardEnvironment(this);
    emit(
      { mode: resolveOutputMode(opts) },
      await logoutPersonalCredential({ forgetLocal: opts.forgetLocal === true }),
    );
  });

  addOutputModeOptions(
    auth
      .command("init")
      .summary("Interactive credential setup")
      .description(
        [
          "Interactively record the Doppler project/config used by aventure-cli + the MCP server.",
          "Credentials resolve from the injected environment first, then Doppler; auth init never writes credentials to disk.",
          "",
          "Prompts go to stderr so stdout stays reserved for the result envelope.",
        ].join("\n"),
      ),
  ).action(async function (this: Command, opts: CliOutputOptions) {
    forwardEnvironment(this);
    emit({ mode: resolveOutputMode(opts) }, await initEnvelope());
  });

  addOutputModeOptions(
    auth
      .command("status")
      .summary("Local credential provenance, API build, and server uptime")
      .description(
        [
          "Reports local credentials plus two independent remote health signals:",
          "  - auth: per-credential local provenance (env vs ~/.config/aventure/config.json vs unset)",
          "  - personal: OS-keyring metadata for the selected API host, without the secret",
          "  - api: running CLI package version plus GET /info build metadata",
          "  - system: GET /v1/status response (Better Stack uptime SLA)",
          "",
          "No headers are sent to the server. Credential provenance is computed locally; this",
          "answers whether service credentials or a personal CLI credential are wired without exposing them.",
          "To prove a credential survives transit, call any real endpoint that requires it.",
        ].join("\n"),
      ),
  ).action(async function (this: Command, opts: CliOutputOptions) {
    forwardEnvironment(this);
    emit({ mode: resolveOutputMode(opts) }, await statusEnvelope());
  });
}

function compositeCommand(
  parent: Command,
  composite: OpenApiCompositeSpec,
  description: string,
): Command {
  const command = parent
    .command(composite.command.slice(composite.command.indexOf(" ") + 1))
    .summary(composite.summary)
    .description(description);
  for (const option of composite.bodyOption) {
    if (option.required) command.requiredOption(option.flag, option.description);
    else command.option(option.flag, option.description);
  }
  for (const option of composite.localOption) command.option(option.flag, option.description);
  return command;
}

function authCommand(parent: Command): Command {
  const auth =
    parent.commands.find((command) => command.name() === "auth") ?? parent.command("auth");
  return auth
    .summary("Authentication, credential setup, API build, and uptime")
    .description(
      [
        `\`${AUTH_LOGIN_START.command}\`: ${AUTH_LOGIN_START.summary}.`,
        `\`${AUTH_LOGOUT_REVOKE.command}\`: ${AUTH_LOGOUT_REVOKE.summary}.`,
        "`auth status` reports local credential provenance plus CLI/API build and uptime.",
        "`auth doctor` runs the one-call selftest and prints `{ ok, check: [...] }`.",
        "`auth init` configures the local Doppler source used by generated API commands.",
      ].join("\n"),
    );
}

function forwardEnvironment(command: Command): void {
  const globals = command.optsWithGlobals<{ readonly environment?: string }>();
  if (globals.environment !== undefined) process.env.API_ENV = globals.environment;
}

async function statusEnvelope(): Promise<ResultEnvelope<unknown>> {
  let config: DopplerSource | null;
  try {
    config = await readAuthConfig();
  } catch (error) {
    return failure(
      `auth status: cannot read ${configPath()} — ${error instanceof Error ? error.message : String(error)}`,
      [
        `configPath=${configPath()}`,
        `errorName=${error instanceof Error ? error.name : "Error"}`,
        ...CONFIG_TEMPLATE_HINT,
      ],
    );
  }
  let personalHost: string;
  try {
    personalHost = canonicalPersonalCredentialHost(readEnv().host);
  } catch (error) {
    return failure(`auth status: invalid API host — ${credentialSafeMessage(error)}`);
  }
  const [system, apiInfo, personal] = await Promise.all([
    callPublicJsonEndpoint("/v1/status", "GET /v1/status"),
    callPublicJsonEndpoint("/info", "GET /info"),
    inspectPersonalCredential(personalHost),
  ]);
  const resolved = resolveAuthStatus(config);
  const summary =
    `cli=${packageJson.version} ${summarizeApiInfo(apiInfo)} ` +
    `${summarizeAuthOnly(resolved)} personal=${summarizePersonalCredential(personal)} | ${summarizeSystem(system)}`;
  const diagnostics = {
    cli: { version: packageJson.version },
    api: apiInfo.ok ? (apiInfo.data ?? null) : null,
    auth: authDiagnostics(config, resolved),
    personal: personalCredentialDiagnostics(personalHost, personal),
    system: system.ok ? (system.data ?? null) : null,
    ...(apiInfo.ok ? {} : { apiError: apiInfo.summary }),
    ...(system.ok ? {} : { systemError: system.summary }),
  };
  return hasResolvedCredential(resolved) || personal.state === "found"
    ? success(summary, diagnostics)
    : noCredentialsFailure(`auth status: no credentials resolved | ${summary}`, diagnostics);
}

type PersonalCredentialInspection =
  | PersonalCredentialLookup
  | { readonly state: "invalid"; readonly summary: string };

async function inspectPersonalCredential(host: string): Promise<PersonalCredentialInspection> {
  try {
    return await loadPersonalCredential(host);
  } catch (error) {
    return { state: "invalid", summary: credentialSafeMessage(error) };
  }
}

function summarizePersonalCredential(personal: PersonalCredentialInspection): string {
  return personal.state === "found"
    ? personal.stored.activation
    : personal.state === "missing"
      ? "unset"
      : "unavailable";
}

function personalCredentialDiagnostics(host: string, personal: PersonalCredentialInspection) {
  const stored = personal.state === "found" ? personal.stored : undefined;
  return {
    host,
    present: stored !== undefined,
    provider: stored === undefined ? null : "keyring",
    activation: stored?.activation ?? null,
    apiKeyId: stored?.credential.apiKey.id ?? null,
    name:
      stored === undefined
        ? null
        : redactCredentialText(stored.credential.apiKey.name, [stored.credential.secret]),
    status: stored?.credential.apiKey.status ?? null,
    expiresAt: stored?.credential.apiKey.expiresAt ?? null,
    keyringFailure: personal.state === "unavailable" ? personal.summary : null,
    error: personal.state === "invalid" ? personal.summary : null,
  };
}

function summarizeAuthOnly(resolved: AuthResolutionMap): string {
  return AUTH_SECRET_NAMES.map((name) => summarizeCredential(name, resolved)).join(" ");
}

function summarizeCredential(name: AuthSecretName, resolved: AuthResolutionMap): string {
  const resolution = resolved[name];
  if (resolution.present) return `${name}=${resolution.source ?? "resolved"}`;
  return `${name}=${resolution.source === "config" ? "config (unresolved)" : "unset"}`;
}

function summarizeSystem(envelope: ResultEnvelope<unknown>): string {
  if (!envelope.ok) return `system=error: ${envelope.summary}`;
  return `system=ok`;
}

function summarizeApiInfo(envelope: ResultEnvelope<unknown>): string {
  if (!envelope.ok) return `api=error: ${envelope.summary}`;
  return `api=${apiBuildVersion(envelope.data) ?? "unknown"}`;
}

function apiBuildVersion(data: unknown): string | null {
  if (!isRecord(data)) return null;
  const parsed = SystemBuildSchema.safeParse(Reflect.get(data, "response"));
  if (!parsed.success) return null;
  const version = parsed.data.build.version?.trim();
  return version && version.length > 0 ? version : null;
}

function isRecord(value: unknown): value is Record<PropertyKey, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

async function callPublicJsonEndpoint(
  path: string,
  label: string,
): Promise<ResultEnvelope<unknown>> {
  return await runOpenApiCall({
    method: "GET",
    path,
    auth: "none",
    execute: true,
    responseFormat: "json",
  }).catch((error: unknown) =>
    failure(`${label} failed: ${error instanceof Error ? error.message : String(error)}`),
  );
}

async function initEnvelope(): Promise<ResultEnvelope<unknown>> {
  if (!input.isTTY) {
    return failure("aventure-cli auth init requires an interactive TTY on stdin", [
      "non-interactive caller: hand-write `~/.config/aventure/config.json` directly",
      ...CONFIG_TEMPLATE_HINT,
    ]);
  }
  const rl = createInterface({ input, output: prompts });
  try {
    prompts.write("aventure-cli auth init\n\n");
    const config = await askDopplerSource(rl);
    try {
      await writeAuthConfig(config);
    } catch (error) {
      return failure(
        `auth init: cannot write ${configPath()} — ${error instanceof Error ? error.message : String(error)}`,
        [
          `configPath=${configPath()}`,
          `errorName=${error instanceof Error ? error.name : "Error"}`,
          ...CONFIG_TEMPLATE_HINT,
        ],
      );
    }
    await materializeAuth();
    return buildStatusResponse("saved", config);
  } finally {
    rl.close();
  }
}

async function askDopplerSource(rl: ReturnType<typeof createInterface>): Promise<DopplerSource> {
  const project = await readRequired(rl, "Doppler project: ");
  const config = await readRequired(rl, "Doppler config (e.g. staging): ");
  return { source: "doppler", project, config };
}

async function readRequired(
  rl: ReturnType<typeof createInterface>,
  prompt: string,
): Promise<string> {
  while (true) {
    const answer = (await rl.question(prompt)).trim();
    if (answer.length > 0) return answer;
    prompts.write("  required\n");
  }
}

function buildStatusResponse(verb: string, config: DopplerSource | null): ResultEnvelope<unknown> {
  const resolved = resolveAuthStatus(config);
  const summary = `${summarizeStatus(verb, config, resolved)} | ${summarizeScopeAvailability()}`;
  const diagnostics = authDiagnostics(config, resolved);
  return hasResolvedCredential(resolved)
    ? success(summary, diagnostics)
    : noCredentialsFailure(`no credentials resolved | ${summary}`, diagnostics);
}

function authDiagnostics(config: DopplerSource | null, resolved: AuthResolutionMap) {
  return {
    configPath: configPath(),
    configSource: config?.source ?? null,
    ...(config?.source === "doppler"
      ? { configProject: config.project, configConfig: config.config }
      : {}),
    resolved,
  };
}

function hasResolvedCredential(resolved: AuthResolutionMap): boolean {
  return AUTH_SECRET_NAMES.some((name) => resolved[name].present);
}

function noCredentialsFailure<T>(summary: string, data: T): ResultEnvelope<T> {
  return {
    ...failure(summary, [
      "Run `aventure-cli auth init` to select Doppler, or inject credentials through the environment.",
      "For a personal credential, run `aventure-cli auth login` in an interactive terminal.",
    ]),
    data,
  };
}

function summarizeScopeAvailability(): string {
  const read = prepareCallEnv("read").ok ? "available" : "unavailable";
  const write = prepareCallEnv("write").ok ? "available" : "unavailable";
  return `read=${read} write=${write}`;
}

function summarizeStatus(
  verb: string,
  config: DopplerSource | null,
  resolved: AuthResolutionMap,
): string {
  const keys = summarizeAuthOnly(resolved);
  const cfg = config === null ? "no config" : `doppler ${config.project}/${config.config}`;
  return `${verb}: ${keys} | ${cfg}`;
}

/** JSON template surfaced when the config is missing or unreadable. */
const CONFIG_TEMPLATE_HINT: readonly string[] = [
  "no config at the path above — run `aventure-cli auth init` in an interactive terminal, or write a non-secret Doppler source config:",
  '  {"auth":{"source":"doppler","project":"<project>","config":"<config>"}}',
  "legacy inline configs are rejected; move credentials to Doppler or the environment before replacing the config.",
];
