/** Generic NDJSON export/run drivers resolved from generated OpenAPI command specs. */
import { appendFileSync, writeFileSync } from "node:fs";

import { Command, Option } from "commander";

import type { JsonValue } from "@aventurevc/api-schemas/http/json-value";
import { runOpenApiCall } from "../../api/openapi-call.ts";
import { failure, success, type ResultEnvelope } from "../../api/result-envelope.ts";
import type { OpenApiCommandSpec } from "../../mcp-server/contract.ts";
import { emit } from "../output.ts";
import { addOutputModeOptions, resolveOutputMode, type CliOutputOptions } from "../output-mode.ts";
import {
  MAX_BATCH_CONCURRENCY,
  asJsonRecord,
  chunkRows,
  collectRepeatable,
  guardPathParameterFree,
  parseBoundedInt,
  parseQueryOptions,
  pathValue,
  readCheckpoint,
  readNdjsonRows,
  resolveSpec,
  responsePayload,
  writeCheckpoint,
} from "./batch-io.ts";
import { readJsonBody } from "./json-input.ts";

type BatchExportOptions = CliOutputOptions & {
  readonly command: string;
  readonly fromFile?: string;
  readonly query?: readonly string[];
  readonly out: string;
  readonly cursor?: string;
  readonly cursorParam: string;
  readonly rowsPath: string;
  readonly nextCursorPath: string;
  readonly maxPages: string;
};

type BatchRunOptions = CliOutputOptions & {
  readonly command: string;
  readonly input: string;
  readonly arrayField: string;
  readonly base?: string;
  readonly query?: readonly string[];
  readonly out: string;
  readonly chunkSize: string;
  readonly concurrency: string;
  readonly checkpoint?: string;
  readonly execute?: boolean;
  readonly haltOnFailure: boolean;
};

export function registerBuiltinBatchCommand(
  parent: Command,
  specs: readonly OpenApiCommandSpec[],
): void {
  const batch = parent
    .command("batch")
    .summary("Export reads to NDJSON files and run bulk NDJSON writes")
    .description(
      "batch export pages a cursor read into an NDJSON file; batch run sends chunked NDJSON writes with bounded concurrency and checkpoint/resume. Dry-run by default; --execute commits. Resolve targets with command-catalog search|show first.",
    );
  addExportCommand(batch, specs);
  addRunCommand(batch, specs);
}

function addExportCommand(parent: Command, specs: readonly OpenApiCommandSpec[]): void {
  const command = parent
    .command("export")
    .summary("Page a cursor read operation into an NDJSON row file")
    .description(
      [
        "Repeatedly call one generated cursor-paginated read operation and append",
        "every returned row to --out as NDJSON while stdout stays a compact summary.",
        '  aventure-cli batch export --command "<resource> <area> <operation>" \\',
        "    --from-file filter.json --query size=200 --out rows.ndjson",
      ].join("\n"),
    )
    .requiredOption("--command <command>", "Generated CLI command path or operationId")
    .option("--from-file <path>", "JSON request body sent on every page")
    .option("--query <key=value>", "Query parameter, repeatable", collectRepeatable, [])
    .requiredOption("--out <path>", "NDJSON output file; overwritten at start")
    .option("--cursor <cursor>", "Starting cursor value")
    .option("--cursor-param <name>", "Cursor query parameter name", "cursor")
    .option("--rows-path <path>", "Dot path to the row array in the response", "row")
    .option(
      "--next-cursor-path <path>",
      "Dot path to the next cursor in the response",
      "nextCursor",
    )
    .option("--max-pages <count>", "Safety cap on pages fetched", "1000");
  addOutputModeOptions(command);
  command.action(async function (this: Command) {
    const opts = this.optsWithGlobals<BatchExportOptions>();
    emit({ mode: resolveOutputMode(opts) }, await runExport(specs, opts));
  });
}

function addRunCommand(parent: Command, specs: readonly OpenApiCommandSpec[]): void {
  const command = parent
    .command("run")
    .summary("Send NDJSON rows through a batched write operation")
    .description(
      [
        "Chunk NDJSON rows into batched request bodies for one generated write",
        "operation and send them with bounded concurrency. Every chunk response is",
        "appended to --out as NDJSON; --checkpoint records completed chunks so an",
        "interrupted run resumes without resending them.",
        "",
        "Default is dry-run: it reports the chunk plan and sends nothing.",
        '  aventure-cli batch run --command "<resource> <area> <operation>" \\',
        "    --input rows.ndjson --array-field <bodyArrayField> --base base.json \\",
        '    --query sourceType=llm --query "sourceDetail=..." \\',
        "    --checkpoint state.json --out responses.ndjson --execute",
      ].join("\n"),
    )
    .requiredOption("--command <command>", "Generated CLI command path or operationId")
    .requiredOption("--input <path>", "NDJSON file; each line is one batch row")
    .requiredOption("--array-field <name>", "Body field receiving each chunk of rows")
    .option("--base <path>", "JSON file with fixed body fields merged into every chunk")
    .option("--query <key=value>", "Query parameter, repeatable", collectRepeatable, [])
    .requiredOption("--out <path>", "NDJSON file receiving one response line per chunk")
    .option("--chunk-size <count>", "Rows per request body", "25")
    .option("--concurrency <count>", `Concurrent requests, 1-${MAX_BATCH_CONCURRENCY}`, "2")
    .option("--checkpoint <path>", "JSON checkpoint file for resume")
    .option("--execute", "send the requests; default is a dry-run chunk plan", false)
    .addOption(
      new Option("--no-halt-on-failure", "keep sending remaining chunks after a failed chunk"),
    );
  addOutputModeOptions(command);
  command.action(async function (this: Command) {
    const opts = this.optsWithGlobals<BatchRunOptions>();
    emit({ mode: resolveOutputMode(opts) }, await runBatch(specs, opts));
  });
}

async function runExport(
  specs: readonly OpenApiCommandSpec[],
  opts: BatchExportOptions,
): Promise<ResultEnvelope<unknown>> {
  const spec = resolveSpec(specs, opts.command);
  if (!spec.ok || spec.data === null) return spec;
  if (spec.data.dryRun) {
    return failure(`${opts.command} is a write operation; use \`batch run\``, [spec.data.path]);
  }
  const guard = guardPathParameterFree(spec.data);
  if (!guard.ok) return guard;
  const query = parseQueryOptions(opts.query ?? []);
  if (!query.ok || query.data === null) return query;
  const maxPages = parseBoundedInt("--max-pages", opts.maxPages, 1, 1_000_000);
  if (!maxPages.ok || maxPages.data === null) return maxPages;
  const body = opts.fromFile === undefined ? undefined : await readJsonBody(opts.fromFile);
  if (body !== undefined && !body.ok) return body;
  const requestBody = body === undefined ? undefined : asJsonRecord(body.data);
  if (body !== undefined && requestBody === null) {
    return failure("--from-file must contain a JSON object", [opts.fromFile ?? ""]);
  }

  writeFileSync(opts.out, "");
  let cursor = opts.cursor;
  let pageCount = 0;
  let rowCount = 0;
  let exhausted = false;
  while (pageCount < maxPages.data) {
    const searchParams = {
      ...query.data,
      ...(cursor === undefined ? {} : { [opts.cursorParam]: cursor }),
    };
    const envelope = await runOpenApiCall({
      method: spec.data.method,
      path: spec.data.path,
      searchParams,
      body: requestBody ?? undefined,
      auth: spec.data.auth,
      execute: false,
      responseFormat: "json",
    });
    if (!envelope.ok) {
      return failure(`page ${pageCount + 1} failed: ${envelope.summary}`, [
        `rows already written to ${opts.out}: ${rowCount}`,
        ...(cursor === undefined ? [] : [`resume with --cursor "${cursor}"`]),
      ]);
    }
    const response = responsePayload(envelope.data);
    const rowValue = pathValue(response, opts.rowsPath);
    if (!Array.isArray(rowValue)) {
      return failure(`response has no array at --rows-path "${opts.rowsPath}"`, [
        `page ${pageCount + 1}`,
      ]);
    }
    appendFileSync(opts.out, rowValue.map((row) => `${JSON.stringify(row)}\n`).join(""));
    pageCount += 1;
    rowCount += rowValue.length;
    const nextCursor = pathValue(response, opts.nextCursorPath);
    if (typeof nextCursor !== "string" || nextCursor === "" || nextCursor === cursor) {
      exhausted = true;
      break;
    }
    cursor = nextCursor;
  }
  return success(
    `${rowCount} rows across ${pageCount} pages written to ${opts.out}${exhausted ? "" : `; PARTIAL export — hit --max-pages ${maxPages.data}, resume with --cursor "${cursor}"`}`,
    { outPath: opts.out, exhausted, lastCursor: cursor },
    { counts: { pageCount, rowCount } },
  );
}

async function runBatch(
  specs: readonly OpenApiCommandSpec[],
  opts: BatchRunOptions,
): Promise<ResultEnvelope<unknown>> {
  const spec = resolveSpec(specs, opts.command);
  if (!spec.ok || spec.data === null) return spec;
  if (!spec.data.dryRun) {
    return failure(`${opts.command} is not a write operation; use \`batch export\``, [
      spec.data.path,
    ]);
  }
  const guard = guardPathParameterFree(spec.data);
  if (!guard.ok) return guard;
  const query = parseQueryOptions(opts.query ?? []);
  if (!query.ok || query.data === null) return query;
  const chunkSize = parseBoundedInt("--chunk-size", opts.chunkSize, 1, 10_000);
  if (!chunkSize.ok || chunkSize.data === null) return chunkSize;
  const concurrency = parseBoundedInt("--concurrency", opts.concurrency, 1, MAX_BATCH_CONCURRENCY);
  if (!concurrency.ok || concurrency.data === null) return concurrency;
  const base = opts.base === undefined ? undefined : await readJsonBody(opts.base);
  if (base !== undefined && !base.ok) return base;
  const baseBody = asJsonRecord(base?.data ?? {});
  if (baseBody === null) return failure("--base must contain a JSON object", [opts.base ?? ""]);

  const input = readNdjsonRows(opts.input);
  if (!input.ok || input.data === null) return input;
  const chunkList = chunkRows(input.data.row, chunkSize.data);
  const checkpoint = readCheckpoint(opts.checkpoint, input.data.digest, chunkSize.data);
  if (!checkpoint.ok || checkpoint.data === null) return checkpoint;
  const completed = new Set(checkpoint.data.completedChunk);
  const pending = [...chunkList.keys()].filter((index) => !completed.has(index));

  if (opts.execute !== true) {
    return success(
      `PREVIEW ONLY — nothing sent. ${pending.length} of ${chunkList.length} chunks (${input.data.row.length} rows) would ${spec.data.method} ${spec.data.path}. Re-run with --execute to send.`,
      {
        dryRun: true,
        method: spec.data.method,
        endpoint: spec.data.path,
        arrayField: opts.arrayField,
        outPath: opts.out,
      },
      {
        counts: {
          rowCount: input.data.row.length,
          chunkCount: chunkList.length,
          pendingChunkCount: pending.length,
          skippedChunkCount: completed.size,
        },
      },
    );
  }

  writeFileSync(opts.out, "", { flag: completed.size > 0 ? "a" : "w" });
  const operation = spec.data;
  // Capture narrowed values: closure reads below do not retain the guard narrowing.
  const searchParams = query.data;
  const inputDigest = input.data.digest;
  const rowsPerChunk = chunkSize.data;
  const failedChunk: number[] = [];
  let halted = false;
  let nextSlot = 0;
  const sendChunk = async (index: number): Promise<boolean> => {
    const chunk = chunkList[index] ?? [];
    const body: Record<string, JsonValue> = { ...baseBody, [opts.arrayField]: chunk };
    const envelope = await runOpenApiCall({
      method: operation.method,
      path: operation.path,
      searchParams,
      body,
      auth: operation.auth,
      execute: true,
      responseFormat: "json",
    });
    const response = envelope.ok ? responsePayload(envelope.data) : null;
    appendFileSync(
      opts.out,
      `${JSON.stringify({
        chunk: index,
        rowCount: chunk.length,
        ok: envelope.ok,
        summary: envelope.summary,
        response: response ?? envelope.data ?? null,
      })}\n`,
    );
    if (envelope.ok) {
      completed.add(index);
      writeCheckpoint(opts.checkpoint, inputDigest, rowsPerChunk, completed);
      return true;
    }
    failedChunk.push(index);
    return false;
  };
  const worker = async (): Promise<void> => {
    while (!halted) {
      const index = pending[nextSlot];
      nextSlot += 1;
      if (index === undefined) return;
      if (!(await sendChunk(index)) && opts.haltOnFailure) halted = true;
    }
  };
  await Promise.all(Array.from({ length: concurrency.data }, worker));

  const summaryCounts = {
    rowCount: input.data.row.length,
    chunkCount: chunkList.length,
    completedChunkCount: completed.size,
    failedChunkCount: failedChunk.length,
    remainingChunkCount: chunkList.length - completed.size - failedChunk.length,
  };
  const context = { outPath: opts.out, checkpointPath: opts.checkpoint, failedChunk, halted };
  if (failedChunk.length > 0) {
    return failure(
      `${failedChunk.length} chunk(s) failed; responses in ${opts.out}${opts.checkpoint === undefined ? "" : `, resume via --checkpoint ${opts.checkpoint}`}`,
      [JSON.stringify({ ...context, ...summaryCounts })],
    );
  }
  return success(
    `${completed.size}/${chunkList.length} chunks sent; responses in ${opts.out}`,
    context,
    { counts: summaryCounts },
  );
}
