import { failure, success, type ResultEnvelope } from "../../api/result-envelope.ts";
import type { AventureMethod } from "../../api/client.ts";
import { mcpToolForIntent, type OperationIntent } from "../../config/tool-policy.ts";
import type { OpenApiCommandParameter, OpenApiCommandSpec } from "../../mcp-server/contract.ts";
import type { OpenApiResponseStatus } from "../../mcp-server/openapi-binding.ts";
import {
  addWithInflections,
  coversEveryQueryTerm,
  expandedTokens,
  normalize,
  queryTermForms,
} from "../../mcp-server/help-token.ts";
import type { CliOutputOptions } from "../output-mode.ts";

export type OperationFormat = "text" | "lines" | "compact" | "json" | "ndjson" | "usage";
type ScopeFilter = "read" | "write" | "all";
type BooleanFilter = "true" | "false" | "any";
type IntentFilter = OperationIntent | "all";
type MethodFilter = AventureMethod | "all";

export type OperationFilterOptions = {
  readonly q?: string;
  readonly root?: string;
  readonly scope?: ScopeFilter;
  readonly mutates?: BooleanFilter;
  readonly destructive?: BooleanFilter;
  readonly intent?: IntentFilter;
  readonly method?: MethodFilter;
  readonly limit?: string;
};

export type OperationRenderOptions = OperationFilterOptions &
  CliOutputOptions & {
    readonly format?: OperationFormat;
    readonly output?: string;
    readonly command?: string;
    readonly operationId?: string;
  };

export type OperationMetadata = {
  readonly operationId: string;
  readonly method: AventureMethod;
  readonly path: string;
  readonly resource: string;
  readonly intent: OperationIntent;
  readonly scope: OpenApiCommandSpec["scope"];
  readonly mutates: boolean;
  readonly destructive: boolean;
  readonly dryRunSupported: boolean;
  readonly auth: OpenApiCommandSpec["auth"];
  readonly cli: {
    readonly command: string;
    readonly path: readonly string[];
    readonly alias: string | null;
    readonly aliasPath: readonly string[] | null;
  };
  readonly mcpTool: string;
  readonly body: {
    readonly hasBody: boolean;
    readonly kind: OpenApiCommandSpec["bodyKind"] | null;
    readonly required: boolean;
    readonly description: string;
    readonly requiredPath: readonly string[];
  };
  readonly flags: readonly OperationFlag[];
  readonly errorResponse: readonly OpenApiResponseStatus[];
  readonly summary: string;
  readonly description: string;
};

type OperationFlag = {
  readonly name: string;
  readonly optionKey: string;
  readonly wireName: string;
  readonly location: OpenApiCommandParameter["location"];
  readonly required: boolean;
  readonly placeholder: string | null;
  readonly description: string;
  readonly choices: readonly string[];
};

type SearchScoreWeights = {
  readonly exactQuery: number;
  readonly partialQuery: number;
  readonly exactToken: number;
  readonly partialToken: number;
};

export type OperationCatalog = {
  readonly operation: readonly OperationMetadata[];
  readonly count: {
    readonly totalOperations: number;
    readonly matched: number;
    readonly returned: number;
  };
};

export type OperationDetail = {
  readonly operation: OperationMetadata;
  readonly usage: string;
};

export function searchOperations(
  opts: OperationFilterOptions,
  specs: readonly OpenApiCommandSpec[],
): ResultEnvelope<OperationCatalog> {
  const totalOperations = specs.length;
  const query = queryText(opts);
  const tokens = expandedTokens(query);
  const termForm = queryTermForms(query);
  const filtered = operationMetadata(specs)
    .filter((operation) => matchesFilters(operation, opts))
    .map((operation) => ({ operation, score: scoreOperation(query, tokens, termForm, operation) }))
    .filter(({ score }) => query === "" || score > 0)
    .toSorted(
      (left, right) =>
        right.score - left.score ||
        left.operation.cli.command.localeCompare(right.operation.cli.command) ||
        left.operation.operationId.localeCompare(right.operation.operationId),
    )
    .map(({ operation }) => operation);
  const limit = resolveLimit(opts.limit, filtered.length);
  const operation = filtered.slice(0, limit);
  return success("Operation catalog matches", {
    operation,
    count: { totalOperations, matched: filtered.length, returned: operation.length },
  });
}

export function showOperation(
  opts: OperationRenderOptions,
  specs: readonly OpenApiCommandSpec[],
): ResultEnvelope<OperationDetail | null> {
  const metadata = operationMetadata(specs);
  const selected =
    opts.operationId === undefined
      ? operationByCommand(metadata, opts.command)
      : metadata.find((operation) => operation.operationId === opts.operationId);
  if (selected === undefined) {
    return failure("Generated operation not found", [
      'List candidates with `aventure-cli command-catalog search "<text>"`.',
    ]);
  }
  return success("Generated operation detail", { operation: selected, usage: usageFor(selected) });
}

function operationByCommand(
  operations: readonly OperationMetadata[],
  command: string | undefined,
): OperationMetadata | undefined {
  if (command === undefined) return undefined;
  const normalized = normalizeCommand(command);
  return operations.find(
    (operation) =>
      normalizeCommand(operation.cli.command) === normalized ||
      (operation.cli.alias !== null && normalizeCommand(operation.cli.alias) === normalized),
  );
}

function operationMetadata(specs: readonly OpenApiCommandSpec[]): readonly OperationMetadata[] {
  return specs.map((spec) => {
    const flags = [...spec.parameters, ...spec.bodyParameters].map(operationFlag);
    const command = `aventure-cli ${spec.cliPath.join(" ")}`;
    const alias =
      spec.cliAliasPath === undefined ? null : `aventure-cli ${spec.cliAliasPath.join(" ")}`;
    const mutates = operationMutates(spec);
    const destructive = spec.method === "DELETE" || spec.intent === "delete";
    const bodyKind = spec.bodyKind ?? null;
    const operation: OperationMetadata = {
      operationId: spec.operationId,
      method: spec.method,
      path: spec.path,
      resource: spec.resource,
      intent: spec.intent,
      scope: spec.scope,
      mutates,
      destructive,
      dryRunSupported: spec.dryRun,
      auth: spec.auth,
      cli: {
        command,
        path: spec.cliPath,
        alias,
        aliasPath: spec.cliAliasPath ?? null,
      },
      mcpTool: mcpToolForIntent(spec.intent),
      body: {
        hasBody: spec.hasBody,
        kind: bodyKind,
        required: spec.bodyRequired,
        description: spec.bodyDescription,
        requiredPath: spec.bodyRequiredPath,
      },
      flags,
      errorResponse: spec.errorResponse,
      summary: spec.summary,
      description: spec.description,
    };
    return operation;
  });
}

function operationFlag(parameter: OpenApiCommandParameter): OperationFlag {
  const parts = parameter.flag.split(/\s+/u);
  return {
    name: parts[0] ?? parameter.flag,
    optionKey: parameter.optionKey,
    wireName: parameter.name,
    location: parameter.location,
    required: parameter.required,
    placeholder: parts.length <= 1 ? null : parts.slice(1).join(" "),
    description: parameter.description,
    choices: parameter.choices ?? [],
  };
}

function operationMutates(spec: OpenApiCommandSpec): boolean {
  return spec.intent === "write" || spec.intent === "delete";
}

function matchesFilters(operation: OperationMetadata, opts: OperationFilterOptions): boolean {
  if (opts.root !== undefined && !matchesRoot(operation, opts.root)) return false;
  if (opts.scope !== undefined && opts.scope !== "all" && opts.scope !== operation.scope)
    return false;
  if (
    opts.mutates !== undefined &&
    opts.mutates !== "any" &&
    (opts.mutates === "true") !== operation.mutates
  )
    return false;
  if (
    opts.destructive !== undefined &&
    opts.destructive !== "any" &&
    (opts.destructive === "true") !== operation.destructive
  )
    return false;
  if (opts.intent !== undefined && opts.intent !== "all" && opts.intent !== operation.intent)
    return false;
  if (opts.method !== undefined && opts.method !== "all" && opts.method !== operation.method)
    return false;
  return true;
}

function matchesRoot(operation: OperationMetadata, root: string): boolean {
  const normalizedRoot = normalize(root);
  if (normalizedRoot.length === 0) return true;
  return (
    normalize(operation.cli.path.at(0) ?? "") === normalizedRoot ||
    normalize(operation.cli.aliasPath?.at(0) ?? "") === normalizedRoot
  );
}

function scoreOperation(
  normalizedQuery: string,
  tokens: ReadonlySet<string>,
  termForm: readonly ReadonlySet<string>[],
  operation: OperationMetadata,
): number {
  if (normalizedQuery.length === 0) return 1;
  const identityCorpus = operationIdentitySearchCorpus(operation);
  let score =
    scoreSearchCorpus(normalizedQuery, tokens, identityCorpus, {
      exactQuery: 120,
      partialQuery: 60,
      exactToken: 18,
      partialToken: 6,
    }) +
    scoreSearchCorpus(normalizedQuery, tokens, operationContextSearchCorpus(operation), {
      exactQuery: 12,
      partialQuery: 6,
      exactToken: 2,
      partialToken: 1,
    });
  if (coversEveryQueryTerm(termForm, identityCorpus)) score += 200;
  for (const segment of operation.cli.path) {
    const segmentForms = new Set<string>();
    addWithInflections(segmentForms, segment);
    if ([...segmentForms].some((form) => tokens.has(form))) score += 15;
  }
  if (normalize(operation.cli.command).endsWith(normalizedQuery)) score += 40;
  return score;
}

function scoreSearchCorpus(
  normalizedQuery: string,
  tokens: ReadonlySet<string>,
  corpus: readonly string[],
  weights: SearchScoreWeights,
): number {
  let score = 0;
  if (corpus.includes(normalizedQuery)) score += weights.exactQuery;
  if (corpus.some((value) => value.includes(normalizedQuery))) score += weights.partialQuery;
  for (const token of tokens) {
    if (corpus.includes(token)) score += weights.exactToken;
    else if (corpus.some((value) => value.includes(token))) score += weights.partialToken;
  }
  return score;
}

function operationIdentitySearchCorpus(operation: OperationMetadata): readonly string[] {
  return normalizedSearchCorpus([
    operation.operationId,
    operation.cli.command,
    operation.cli.alias ?? "",
    operation.summary,
  ]);
}

function operationContextSearchCorpus(operation: OperationMetadata): readonly string[] {
  return normalizedSearchCorpus([
    operation.method,
    operation.path,
    operation.resource,
    operation.intent,
    operation.scope,
    operation.mutates ? "mutates mutation write" : "read only no mutation",
    operation.destructive ? "destructive delete" : "non destructive",
    operation.mcpTool,
    operation.body.kind ?? "",
    operation.body.description,
    operation.body.requiredPath.join(" "),
    operation.description,
    ...operation.flags.flatMap((flag) => [
      flag.name,
      flag.optionKey,
      flag.wireName,
      flag.description,
      flag.choices.join(" "),
    ]),
  ]);
}

function normalizedSearchCorpus(values: readonly string[]): readonly string[] {
  return values.map(normalize).filter((value) => value.length > 0);
}

function queryText(opts: Pick<OperationFilterOptions, "q">): string {
  return normalize(opts.q?.trim() ?? "");
}

function resolveLimit(value: string | undefined, fallback: number): number {
  if (value === undefined) return fallback;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? Math.max(0, Math.trunc(parsed)) : fallback;
}

function usageFor(operation: OperationMetadata): string {
  const required = operation.flags.filter((flag) => flag.required);
  const optional = operation.flags.filter((flag) => !flag.required);
  return [
    `cli: ${operation.cli.command}`,
    operation.cli.alias === null ? "" : `alias: ${operation.cli.alias}`,
    `${operation.method} ${operation.path}`,
    `operationId: ${operation.operationId}`,
    `resource: ${operation.resource}`,
    `intent: ${operation.intent}`,
    `scope: ${operation.scope}`,
    `mutates: ${operation.mutates}`,
    `destructive: ${operation.destructive}`,
    `mcpTool: ${operation.mcpTool}`,
    operation.body.hasBody
      ? `body: kind=${operation.body.kind ?? "unknown"} required=${operation.body.required} requiredPath=${operation.body.requiredPath.join(",")}`
      : "body: none",
    flagUsage("required path flags", required, "path"),
    flagUsage("required query flags", required, "query"),
    flagUsage("required body flags", required, "body"),
    flagUsage("optional path flags", optional, "path"),
    flagUsage("optional query flags", optional, "query"),
    flagUsage("optional body flags", optional, "body"),
    ...exampleUsage(operation),
    ...errorBlock(operation.errorResponse),
    "",
    operation.summary,
    operation.description,
  ]
    .filter((line) => line.length > 0)
    .join("\n");
}

/**
 * Renders the generated failure contract as `Errors:` plus one `<status> <description>` line, the
 * sole rendering of it: `command-catalog show`, `docs api`, and every generated `--help` share it.
 */
export function errorBlock(errorResponse: readonly OpenApiResponseStatus[]): readonly string[] {
  if (errorResponse.length === 0) return [];
  return [
    "Errors:",
    ...errorResponse.map(({ status, description }) => `  ${status} ${description}`),
  ];
}

/** Identity-flag suffixes in preference order, matched against the operation's own resource name. */
const EXAMPLE_IDENTITY_SUFFIX = ["-id", "-slug", "-url"] as const;

/** Identity flags that carry no resource prefix, in the same preference order. */
const EXAMPLE_BARE_IDENTITY_FLAG = ["--id", "--slug", "--url"] as const;

/** Body file flag registered by `addBodyOptions` when a required body graph has no required flag. */
const EXAMPLE_BODY_FILE_ARGUMENT = '--from-file "<path>"';

function exampleUsage(operation: OperationMetadata): readonly string[] {
  const invocation = [operation.cli.command, ...exampleArgument(operation), "--data"].join(" ");
  return operation.dryRunSupported
    ? [`example: ${invocation}`, `example (commit): ${invocation} --execute`]
    : [`example: ${invocation}`];
}

function exampleArgument(operation: OperationMetadata): readonly string[] {
  const required = operation.flags.filter((flag) => flag.required);
  const selected = required.length > 0 ? required : exampleIdentityFlag(operation);
  const argument = selected.map(exampleFlagArgument);
  const bodyNeedsFile =
    (operation.body.required || operation.body.requiredPath.length > 0) &&
    !required.some((flag) => flag.location === "body");
  return bodyNeedsFile ? [...argument, EXAMPLE_BODY_FILE_ARGUMENT] : argument;
}

/**
 * Picks the one selector an operation with no required flag needs. Anchoring the match to the
 * operation's own resource keeps filter, exclusion, and cursor flags that merely end in `-id`
 * (`--exclude-id`, `--after-entity-id`, `--correlation-id`) out of generated examples.
 */
function exampleIdentityFlag(operation: OperationMetadata): readonly OperationFlag[] {
  const resourceForm = new Set<string>();
  addWithInflections(resourceForm, operation.resource);
  for (const suffix of EXAMPLE_IDENTITY_SUFFIX) {
    for (const form of resourceForm) {
      const flag = operation.flags.find((candidate) => candidate.name === `--${form}${suffix}`);
      if (flag !== undefined) return [flag];
    }
  }
  for (const name of EXAMPLE_BARE_IDENTITY_FLAG) {
    const flag = operation.flags.find((candidate) => candidate.name === name);
    if (flag !== undefined) return [flag];
  }
  return [];
}

function exampleFlagArgument(flag: OperationFlag): string {
  return flag.placeholder === null ? flag.name : `${flag.name} "${flag.placeholder}"`;
}

function flagUsage(
  label: string,
  flags: readonly OperationFlag[],
  location: OperationFlag["location"],
): string {
  const locationFlags = flags.filter((flag) => flag.location === location);
  return `${label}: ${
    locationFlags.length === 0 ? "none" : locationFlags.map((flag) => flag.name).join(" ")
  }`;
}

export function normalizeCommand(command: string): string {
  return command
    .trim()
    .replace(/^aventure(?:-cli)?\s+/u, "")
    .replaceAll(/\s+/gu, " ");
}
