import process from "node:process";
import { Command, type Option as CommanderOption } from "commander";
import packageJson from "../../package.json" with { type: "json" };
import type { OpenApiCommandParameter, OpenApiCommandSpec } from "../../mcp-server/contract.ts";
import { GENERATED_OPENAPI_COMMAND_SPECS } from "../generated/openapi-commands.ts";
import {
  registerCompletionInstallCommands,
  registerCompletionSetupCommand,
} from "./completion-setup.ts";

type GeneratedParameter = OpenApiCommandParameter;

export function registerCompletionCommand(
  parent: Command,
  specs: readonly OpenApiCommandSpec[] = GENERATED_OPENAPI_COMMAND_SPECS,
): void {
  const completion = parent
    .command("completion")
    .summary("Generate shell completion scripts")
    .description("Generate shell completion scripts for the aVenture CLI.");

  for (const shell of ["bash", "fish", "zsh"] as const) {
    completion
      .command(shell)
      .summary(`Print ${shell} shell completions`)
      .description(`Print ${shell} completion definitions for aventure-cli and aventure.`)
      .action(() => {
        process.stdout.write(renderCompletion(parent, shell, specs));
      });
  }

  registerCompletionInstallCommands(completion);
  registerCompletionSetupCommand(completion);
}

function completionBins(): readonly string[] {
  return Object.keys(packageJson.aventurePublish.variants.cli.bin);
}

function renderCompletion(
  root: Command,
  shell: "bash" | "fish" | "zsh",
  specs: readonly OpenApiCommandSpec[] = GENERATED_OPENAPI_COMMAND_SPECS,
  bins: readonly string[] = completionBins(),
): string {
  const generated = generatedParameterIndex(specs);
  if (shell !== "fish") return renderTableCompletion(root, shell, generated, bins);
  return [
    `# fish completions for ${bins.join(", ")}`,
    ...fishFunctions(root),
    ...bins.map((bin) => `complete -c ${fishQuote(bin)} -e`),
    `${fishComplete(bins)} -f`,
    ...fishCommandLines(root, bins),
    ...optionCompletionLines(root, generated, bins),
    "",
  ].join("\n");
}

function renderTableCompletion(
  root: Command,
  shell: "bash" | "zsh",
  generated: ReadonlyMap<string, GeneratedParameter>,
  bins: readonly string[],
): string {
  const declaration = shell === "zsh" ? "typeset -ga " : "";
  const bashComplete = `complete -F _aventure_cli ${bins.map((bin) => bin.replaceAll("'", "'\\''")).join(" ")}`;
  const [commandRows, optionRows, valueRows] = tableRows(root, generated);
  return [
    ...(shell === "zsh" ? [`#compdef ${bins.join(" ")}`] : []),
    `# ${shell} completions for ${bins.join(", ")}`,
    `${declaration}_aventure_cli_commands=(`,
    ...commandRows.map((row) => `  ${row}`),
    ")",
    `${declaration}_aventure_cli_options=(`,
    ...optionRows.map((row) => `  ${row}`),
    ")",
    `${declaration}_aventure_cli_values=(`,
    ...valueRows.map((row) => `  ${row}`),
    ")",
    "",
    ...shellCompletionFunctionLines(shell),
    ...(shell === "bash" ? [bashComplete, ""] : [""]),
  ].join("\n");
}

function fishFunctions(root: Command): readonly string[] {
  const rootValueOptions = commandOptions(root)
    .filter((option) => option.required || option.optional)
    .flatMap((option) => optionLongName(option) ?? []);
  return [
    `function __aventure_cli_command_path\n    set -l global_value_options ${rootValueOptions.map(fishQuote).join(" ")}\n    set -l tokens (commandline -xpc)\n    if test (count $tokens) -gt 0\n        set -e tokens[1]\n    end\n    set -l path\n    set -l skip_next 0\n    for token in $tokens\n        if test $skip_next -eq 1\n            set skip_next 0\n            continue\n        end\n        if string match -q -- '--*=*' $token\n            set -l name (string replace -r '^--([^=]+)=.*$' '$1' -- $token)\n            contains -- $name $global_value_options; and continue\n        end\n        if string match -q -- '--*' $token\n            set -l name (string replace -r '^--' '' -- $token)\n            if contains -- $name $global_value_options\n                set skip_next 1\n                continue\n            end\n            break\n        end\n        if string match -q -- '-*' $token\n            break\n        end\n        set -a path $token\n    end\n    printf '%s\\n' $path\nend\n`,
    "function __aventure_cli_path_is\n    set -l expected $argv\n    set -l actual (__aventure_cli_command_path)\n    if test (count $actual) -ne (count $expected)\n        return 1\n    end\n    if test (count $expected) -eq 0\n        return 0\n    end\n    for index in (seq (count $expected))\n        if test $actual[$index] != $expected[$index]\n            return 1\n        end\n    end\n    return 0\nend\n",
  ].flatMap((block) => block.split("\n"));
}

function fishCommandLines(root: Command, bins: readonly string[]): readonly string[] {
  return commandEntries(root)
    .map(
      (entry) =>
        `${fishComplete(bins)} -f -n ${fishQuote(pathCondition(entry.parentPath))} -a ${fishQuote(entry.name)} -d ${fishQuote(entry.description)}`,
    )
    .toSorted((left, right) => left.localeCompare(right));
}

function optionCompletionLines(
  root: Command,
  generated: ReadonlyMap<string, GeneratedParameter>,
  bins: readonly string[],
): readonly string[] {
  return allCommands(root)
    .flatMap((command) => {
      const path = commandPath(command);
      const condition = path.length === 0 ? undefined : pathCondition(path);
      return commandOptions(command).flatMap((option) => {
        const generatedParameter = generated.get(generatedParameterKey(path, option));
        return completionParameterVisible(generatedParameter)
          ? fishOptionLines(option, condition, generatedParameter, bins)
          : [];
      });
    })
    .toSorted((left, right) => left.localeCompare(right));
}

function commandOptions(command: Command): readonly CommanderOption[] {
  return command.parent === null ? command.createHelp().visibleOptions(command) : command.options;
}

function fishOptionLines(
  option: CommanderOption,
  condition: string | undefined,
  generated: GeneratedParameter | undefined,
  bins: readonly string[],
): readonly string[] {
  const longName = optionLongName(option);
  if (longName === undefined) return [];
  const choices: readonly string[] | undefined = option.argChoices ?? generated?.choices;
  const optionFlags = [
    `-l ${fishQuote(longName)}`,
    option.short === undefined ? "" : `-s ${fishQuote(option.short.replace(/^-/, ""))}`,
  ].filter(Boolean);
  const conditionFlag = condition === undefined ? "" : ` -n ${fishQuote(condition)}`;
  const valueFlags =
    option.required || option.optional
      ? valueCompletionFlags(choices, forceFileCompletion(longName, generated))
      : "-f";
  const base = `${fishComplete(bins)}${conditionFlag} ${optionFlags.join(" ")} ${valueFlags}`;
  if (choices === undefined || choices.length === 0) {
    return [`${base} -d ${fishQuote(oneLine(option.description))}`];
  }
  return choices.map(
    (choice) => `${base} -a ${fishQuote(choice)} -d ${fishQuote(oneLine(option.description))}`,
  );
}

function valueCompletionFlags(choices: readonly string[] | undefined, forceFiles: boolean): string {
  if (choices !== undefined && choices.length > 0) return "-x";
  return forceFiles ? "-r -F" : "-r -f";
}

function forceFileCompletion(longName: string, generated: GeneratedParameter | undefined): boolean {
  if (longName === "from-file") return true;
  if (generated?.location !== "body") return false;
  if (generated.schemaFormat === "binary") return true;
  return ["file", "path"].includes(longName.split("-").at(-1) ?? "");
}

function generatedParameterIndex(
  specs: readonly OpenApiCommandSpec[],
): ReadonlyMap<string, GeneratedParameter> {
  return new Map(
    specs.flatMap((spec) =>
      [...spec.parameters, ...spec.bodyParameters].map(
        (parameter) => [generatedParameterKey(spec.cliPath, parameter), parameter] as const,
      ),
    ),
  );
}

function generatedParameterKey(
  path: readonly string[],
  value: GeneratedParameter | CommanderOption,
): string {
  const option =
    "flag" in value ? value.flag.split(/\s+/)[0]?.replace(/^--/, "") : optionLongName(value);
  if ("flag" in value && (option === undefined || option.length === 0 || option === value.flag)) {
    throw new Error(`Cannot render completion for option flag: ${value.flag}`);
  }
  return `${path.join("\u0000")}\u0000${option ?? ""}`;
}

function commandEntries(root: Command) {
  return allCommands(root).flatMap((parent) =>
    parent.commands.map((child) => ({
      parentPath: commandPath(parent),
      name: child.name(),
      description: oneLine(child.summary() || child.description() || child.name()),
    })),
  );
}

function tableRows(root: Command, generated: ReadonlyMap<string, GeneratedParameter>) {
  const options: string[] = [];
  const values: string[] = [];
  for (const command of allCommands(root)) {
    const path = commandPath(command);
    for (const option of commandOptions(command)) {
      const longName = optionLongName(option);
      if (longName === undefined) continue;
      const generatedParameter = generated.get(generatedParameterKey(path, option));
      if (!completionParameterVisible(generatedParameter)) continue;
      const choices = option.argChoices ?? generatedParameter?.choices;
      let mode = "none";
      if (option.required || option.optional) {
        mode = choices !== undefined && choices.length > 0 ? "choice" : "scalar";
        if (mode === "scalar" && forceFileCompletion(longName, generatedParameter)) mode = "file";
      }
      options.push(
        completionRow([
          path.join(" "),
          `--${longName}`,
          option.short ?? "",
          option.description,
          mode,
        ]),
      );
      for (const choice of choices ?? []) {
        values.push(completionRow([path.join(" "), `--${longName}`, choice, option.description]));
      }
    }
  }
  return [
    commandEntries(root)
      .map((entry) => completionRow([entry.parentPath.join(" "), entry.name, entry.description]))
      .toSorted((left, right) => left.localeCompare(right)),
    options.toSorted((left, right) => left.localeCompare(right)),
    values.toSorted((left, right) => left.localeCompare(right)),
  ];
}

function completionParameterVisible(generated: GeneratedParameter | undefined): boolean {
  return generated?.visibility !== "private";
}

function shellCompletionFunctionLines(shell: "bash" | "zsh"): readonly string[] {
  const bash = shell === "bash";
  const word = bash ? "COMP_WORDS" : "words";
  const cursor = bash ? "COMP_CWORD" : "CURRENT";
  const keyExpression = bash ? "${path[*]}" : "${(j: :)path}";
  const optionRowsExpression = bash ? '"${_aventure_cli_options[@]}"' : "$_aventure_cli_options";
  const valueRowsExpression = bash ? '"${_aventure_cli_values[@]}"' : "$_aventure_cli_values";
  const commandRowsExpression = bash ? '"${_aventure_cli_commands[@]}"' : "$_aventure_cli_commands";
  return [
    "function _aventure_cli {",
    `  local current="\${${word}[${cursor}]}" previous="\${${word}[${cursor}-1]}" row row_path long short description mode name value option token key prefix candidate file_current`,
    ...(bash ? ["  COMPREPLY=()"] : []),
    `  local index=${bash ? 1 : 2} skip_next=0; local -a path names descriptions`,
    `  while (( index < ${cursor} )); do`,
    `    token="\${${word}[index]}"; (( skip_next )) && { skip_next=0; (( index++ )); continue; }`,
    '    if [[ "$token" == -* && "$token" != "-" && "$token" != "--" ]]; then',
    `      option="\${token%%=*}"; key="${keyExpression}"; mode=''`,
    `      for row in ${optionRowsExpression}; do IFS='|' read -r row_path long short description mode <<< "$row"; [[ "$row_path" == "$key" && ( "$long" == "$option" || "$short" == "$option" ) ]] && break; mode=''; done`,
    '      [[ -n "$mode" && "$mode" != none && "$token" != *=* ]] && skip_next=1',
    '    elif [[ "$token" != -* ]]; then path+=("$token"); fi',
    "    (( index++ ))",
    "  done",
    `  key="${keyExpression}"`,
    '  if [[ "$current" == --*=* || ( "$previous" == -* && "$current" != -* ) ]]; then',
    `    option="$previous"; prefix=''; file_current="$current"; [[ "$current" == --*=* ]] && { option="\${current%%=*}"; prefix="$option="; file_current="\${current#*=}"; }`,
    `    for row in ${optionRowsExpression}; do IFS='|' read -r row_path long short description mode <<< "$row"; [[ "$row_path" == "$key" && ( "$long" == "$option" || "$short" == "$option" ) ]] && { option="$long"; break; }; mode=''; done`,
    bash
      ? '    [[ "$mode" == file ]] && { while IFS= read -r candidate; do COMPREPLY+=("$prefix$candidate"); done < <(compgen -f -- "$file_current"); return 0; }'
      : '    [[ "$mode" == file ]] && { _files; return 0; }',
    bash
      ? `    [[ "$mode" == choice ]] && for row in ${valueRowsExpression}; do IFS='|' read -r row_path long value description <<< "$row"; [[ "$row_path" == "$key" && "$long" == "$option" ]] && { candidate="$prefix$value"; [[ "$candidate" == "$current"* ]] && COMPREPLY+=("$candidate"); }; done`
      : `    [[ "$mode" == choice ]] && for row in ${valueRowsExpression}; do IFS='|' read -r row_path long value description <<< "$row"; [[ "$row_path" == "$key" && "$long" == "$option" ]] && { names+=("$prefix$value"); descriptions+=("$description"); }; done`,
    '  elif [[ "$current" == -* ]]; then',
    `    for row in ${optionRowsExpression}; do`,
    "      IFS='|' read -r row_path long short description mode <<< \"$row\"",
    bash
      ? '      [[ "$row_path" == "$key" ]] && { [[ "$long" == "$current"* ]] && COMPREPLY+=("$long"); [[ -n "$short" && "$short" == "$current"* ]] && COMPREPLY+=("$short"); }'
      : '      [[ "$row_path" == "$key" ]] && { names+=("$long"); descriptions+=("$description"); [[ -n "$short" ]] && { names+=("$short"); descriptions+=("$description"); }; }',
    "    done",
    '  elif [[ "$previous" != -* ]]; then',
    `    for row in ${commandRowsExpression}; do`,
    "      IFS='|' read -r row_path name description <<< \"$row\"",
    bash
      ? '      [[ "$row_path" == "$key" ]] && { [[ "$name" == "$current"* ]] && COMPREPLY+=("$name"); }'
      : '      [[ "$row_path" == "$key" ]] && { names+=("$name"); descriptions+=("$description"); }',
    "    done",
    "  fi",
    ...(bash ? [] : ["  (( ${#names} )) && compadd -d descriptions -a names"]),
    "  return 0",
    "}",
    ...(bash ? [] : ['_aventure_cli "$@"']),
  ];
}

function completionRow(parts: readonly string[]): string {
  return `$'${parts.map(shellEscape).join("|")}'`;
}

function shellEscape(value: string): string {
  return oneLine(value).replaceAll("\\", "\\\\").replaceAll("'", "\\'").replaceAll("|", " ");
}

function optionLongName(option: CommanderOption): string | undefined {
  return option.long?.replace(/^--/, "");
}

function allCommands(root: Command): readonly Command[] {
  return [root, ...root.commands.flatMap((command) => allCommands(command))];
}

function commandPath(command: Command): readonly string[] {
  const path: string[] = [];
  for (let current: Command | null = command; current?.parent !== null; current = current.parent) {
    path.unshift(current.name());
  }
  return path;
}

function fishComplete(bins: readonly string[]): string {
  return `complete ${bins.map((bin) => `-c ${fishQuote(bin)}`).join(" ")}`;
}

function pathCondition(path: readonly string[]): string {
  return ["__aventure_cli_path_is", ...path.map(fishQuote)].join(" ");
}

function oneLine(value: string): string {
  return value.replace(/\s+/g, " ").trim();
}

function fishQuote(value: string): string {
  const safe = value.replace(/[\r\n\t]/g, " ");
  return `'${safe.replaceAll("\\", "\\\\").replaceAll("'", "\\'")}'`;
}
