/** Shared CLI input helpers for commands that accept generated schema payloads. */
import { readFile } from "node:fs/promises";
import { failure, success, type ResultEnvelope } from "../../api/result-envelope.ts";

export async function readJsonBody(path: string): Promise<ResultEnvelope<unknown | null>> {
  let raw: string;
  try {
    raw = path === "-" ? await readStdinToString() : await readFile(path, "utf8");
  } catch (error) {
    return failure(`Could not read input: ${(error as Error).message}`, [`path=${path}`]);
  }
  try {
    if (raw.trim().length === 0) return success("No input provided", null);
    const parsedInput: unknown = JSON.parse(raw);
    return success("Input parsed", parsedInput);
  } catch (error) {
    return failure(`Input is not valid JSON: ${(error as Error).message}`);
  }
}

async function readStdinToString(): Promise<string> {
  if (process.stdin.isTTY) {
    throw new Error("--from-file - requires JSON on stdin, but stdin is a TTY");
  }
  process.stdin.setEncoding("utf8");
  let stdinText = "";
  for await (const chunk of process.stdin) stdinText += chunk;
  return stdinText;
}
