/**
 * CLI output helpers.
 *  - emitJson(): stdout-safe JSON line with 50KB structured cap.
 *  - emitHuman(): compact human-readable summary.
 *  - emit(): chooses emitter from resolved output mode and sets exitCode on failure.
 */
import type { AventureProblemDetail } from "../api/client.ts";
import { capEnvelope, type ResultEnvelope } from "../api/result-envelope.ts";
import { asCliResponseText } from "../api/text-response.ts";
import { logWarn } from "../logging.ts";
import type { CliOutputMode } from "./output-mode.ts";

export function emitJson(envelope: ResultEnvelope<unknown>): ResultEnvelope<unknown> {
  const emittedEnvelope = capEnvelope(envelope);
  logEnvelopeWarnings(emittedEnvelope);
  process.stdout.write(`${JSON.stringify(emittedEnvelope)}\n`);
  return emittedEnvelope;
}

export function emitHuman(envelope: ResultEnvelope<unknown>): void {
  logEnvelopeWarnings(envelope);
  const text = asCliResponseText(envelope.data, envelope.summary);
  if (envelope.ok && text !== null) {
    process.stdout.write(text.endsWith("\n") ? text : `${text}\n`);
    emitEnvelopeMetadata(envelope);
    return;
  }
  const status = envelope.ok ? "OK" : "FAIL";
  process.stdout.write(`[${status}] ${envelope.summary}\n`);
  if (!envelope.ok && envelope.problem !== undefined) {
    emitProblemDetail(envelope.problem);
  }
  emitEnvelopeMetadata(envelope);
}

function emitEnvelopeMetadata(envelope: ResultEnvelope<unknown>): void {
  if (envelope.ids.length > 0) {
    process.stdout.write(`  ids: ${envelope.ids.join(", ")}\n`);
  }
  for (const [key, value] of Object.entries(envelope.counts)) {
    process.stdout.write(`  ${key}: ${value}\n`);
  }
  for (const ref of envelope.references) {
    process.stdout.write(`  ref: ${ref}\n`);
  }
  if (envelope.truncation !== undefined) {
    const omitted = envelope.truncation.omitted.join(", ");
    process.stdout.write(
      `  truncated: byteLength=${envelope.truncation.byteLength} maxBytes=${envelope.truncation.maxBytes} omitted=${omitted}\n`,
    );
    process.stdout.write(`  recovery: ${envelope.truncation.recovery}\n`);
  }
  for (const warn of envelope.warnings) {
    process.stdout.write(`  warn: ${warn}\n`);
  }
}

/**
 * Single CLI emit point: routes envelope to JSON, data, or text form,
 * sets process.exitCode=1 when the envelope is a failure. Replaces four
 * identical inline `emit()` helpers across the commander wirings.
 */
export function emit(
  opts: { readonly mode: CliOutputMode },
  envelope: ResultEnvelope<unknown>,
): void {
  if (opts.mode === "data" || opts.mode === "data-full") {
    // Payload-only modes: emit the unwrapped `.data` on success so a consumer parses the
    // result directly (no envelope, no jq); on failure emit the full envelope so the
    // ProblemDetail is not lost. `data` shares --json's RESULT_ENVELOPE_BYTE_CAP: an
    // under-cap success is emitted byte-exact, and an over-cap result emits the capped
    // envelope instead — truncated/truncation/warnings announce the compaction in-band,
    // because a silently partial bare payload would be worse than a large one. `data-full`
    // skips the cap for programmatic consumers (harness reveal/detect/completion readers,
    // deploy make lanes) that validate complete records and bound their own reads; the
    // harness shell guard blocks it for LLM agents. Routine info/debug JSONL stays off
    // stderr under these flags while warn/error still land there (see logging.ts),
    // mirroring the MCP generic-tool `responseFormat` payload selection; OTEL ships the
    // failure/warning/truncation signal post-cap to keep parity with the --json/human paths.
    const emittedEnvelope = opts.mode === "data" ? capEnvelope(envelope) : envelope;
    logEnvelopeWarnings(emittedEnvelope);
    process.stdout.write(
      `${JSON.stringify(
        emittedEnvelope.ok && emittedEnvelope.truncated !== true
          ? dataPayload(emittedEnvelope.data)
          : emittedEnvelope,
      )}\n`,
    );
    if (!emittedEnvelope.ok) process.exitCode = 1;
    return;
  }
  const emittedEnvelope = opts.mode === "json" ? emitJson(envelope) : envelope;
  if (opts.mode === "text") emitHuman(emittedEnvelope);
  if (!emittedEnvelope.ok) process.exitCode = 1;
}

function dataPayload(payload: unknown): unknown {
  if (typeof payload !== "object" || payload === null || Array.isArray(payload)) {
    return payload;
  }
  if (!Reflect.has(payload, "method") || !Reflect.has(payload, "endpoint")) {
    return payload;
  }
  if (!("response" in payload)) return payload;
  return payload.response === undefined ? payload : payload.response;
}

/**
 * Render the RFC 9457 ProblemDetail fields that carry the actionable failure cause and recovery
 * path. The summary line only shows `<label>: <status> <title>`, so without this the human/MCP-text
 * surface drops the server's `detail`, `code`, `hint`, `suggestion`(s), parameter inventories, and
 * `resolution` — leaving callers a bare HTTP status with no guidance.
 */
function emitProblemDetail(problem: AventureProblemDetail): void {
  if (typeof problem.code === "string") process.stdout.write(`  code: ${problem.code}\n`);
  if (typeof problem.detail === "string") process.stdout.write(`  detail: ${problem.detail}\n`);
  if (typeof problem.hint === "string") process.stdout.write(`  hint: ${problem.hint}\n`);
  if (typeof problem.suggestion === "string") {
    process.stdout.write(`  suggestion: ${problem.suggestion}\n`);
  }
  const suggestionPairs = Object.entries(problem.suggestions ?? {});
  if (suggestionPairs.length > 0) {
    const rendered = suggestionPairs.map(([field, fix]) => `${field}=${fix}`).join("; ");
    process.stdout.write(`  suggestions: ${rendered}\n`);
  }
  emitProblemNameList("unknownParameters", problem.unknownParameters);
  emitProblemNameList("validParameters", problem.validParameters);
  emitProblemResolution(problem.resolution);
}

function emitProblemNameList(label: string, names: readonly string[] | null | undefined): void {
  if (names !== null && names !== undefined && names.length > 0) {
    process.stdout.write(`  ${label}: ${names.join(", ")}\n`);
  }
}

function emitProblemResolution(resolution: AventureProblemDetail["resolution"]): void {
  if (resolution === null || resolution === undefined) return;
  const parts = [`action=${resolution.action}`];
  if (typeof resolution.parameter === "string") parts.push(`parameter=${resolution.parameter}`);
  if (typeof resolution.fieldPath === "string") parts.push(`fieldPath=${resolution.fieldPath}`);
  if (typeof resolution.endpoint === "string") parts.push(`endpoint=${resolution.endpoint}`);
  if (resolution.acceptedValue !== null && resolution.acceptedValue !== undefined) {
    if (resolution.acceptedValue.length > 0) {
      parts.push(`acceptedValue=${resolution.acceptedValue.join(", ")}`);
    }
  }
  if (typeof resolution.retryable === "boolean") parts.push(`retryable=${resolution.retryable}`);
  process.stdout.write(`  resolution: ${parts.join(" ")}\n`);
}

function logEnvelopeWarnings(envelope: ResultEnvelope<unknown>): void {
  if (envelope.ok && envelope.warnings.length === 0) return;
  logWarn({
    component: "aventure-cli",
    event: envelope.ok ? "command_warning" : "command_failed",
    // Surface the warning TEXT (not just a count) so the stderr line — the one channel a
    // stdout-only `| jq` pipe cannot swallow — carries the actual signal (e.g. the write-scope
    // dry-run "NOT PERSISTED" notice), never a silent counter.
    message: envelope.warnings.length > 0 ? envelope.warnings.join(" | ") : envelope.summary,
    fields: { warningCount: envelope.warnings.length, summary: envelope.summary },
  });
}
