/**
 * Built-in (non-generated) CLI subcommand: `aventure-cli update`.
 *
 * Sibling of `builtin-auth.ts` — a local environment command with no API
 * contract, so nothing to generate from a Kotlin `@Schema` owner.
 *
 * Behavior matches the generated-mutation convention from `index.ts`:
 *   - default       : dry-run report (`currentVersion`, `latestVersion`,
 *                     `upgradeAvailable`); no network mutation.
 *   - `--execute`   : runs `npm install -g` against the prefix that owns the
 *                     running published bin. Refuses when the running CLI is
 *                     the npm-linked working-tree build (rebuild that via
 *                     `make` so dev tree stays SSOT).
 */
import { spawnSync, type SpawnSyncOptions } from "node:child_process";
import { existsSync, realpathSync } from "node:fs";
import { dirname, resolve, sep } from "node:path";

import { Command } from "commander";

import packageJson from "../../package.json" with { type: "json" };
import { failure, success, type ResultEnvelope } from "../../api/result-envelope.ts";
import { emit } from "../output.ts";
import { addOutputModeOptions, resolveOutputMode, type CliOutputOptions } from "../output-mode.ts";
import {
  refreshShellCompletionsIfManaged,
  type ShellCompletionRefresh,
} from "./completion-setup.ts";

const REGISTRY_URL = "https://npm.pkg.github.com/";
const VERSION_COLLATOR = new Intl.Collator(undefined, { numeric: true });
// `npm view` is a network round-trip on the critical path of `update` and of the
// `auth doctor` version check; bound it so an unreachable registry reports instead of hanging.
const NPM_VIEW_TIMEOUT_MS = 20_000;
/**
 * The published consumer package. The train (`scripts/release/publish-npm-train.mjs`)
 * ships `@aventurevc/api-schemas`, `@aventurevc/aventure-cli`, and
 * `@aventurevc/mcp-server` atomically at the same `X`, so the running version
 * always equals the CLI variant at `X` regardless of which package provided
 * the bin in PATH (standalone vs linked-mcp-server). Reading that variant from
 * package metadata keeps `--execute` from ever upgrading mcp-server (which, on
 * dev boxes, is intentionally npm-linked to the working tree).
 */
const CLI_PACKAGE = packageJson.aventurePublish.variants.cli.name;

type UpdateOptions = CliOutputOptions & { readonly execute?: boolean };

/** Installed-vs-published comparison; `aventure-cli auth doctor` reads it for its version check. */
export type CliVersionCheck = {
  readonly targetPackage: string;
  /** The package that owns the running `aventure-cli` bin; only that bin reaches this command. */
  readonly runningPackage: string;
  readonly currentVersion: string;
  readonly latestVersion: string;
  readonly upgradeAvailable: boolean;
  /** True only when this invocation installed the upgrade; a dry run reports false. */
  readonly upgradeInstalled: boolean;
  readonly installPrefix?: string;
  readonly verifiedVersion?: string;
  readonly completionRefreshed?: boolean;
  readonly completionRefreshMessage?: string;
};

// Cap on parent-directory walk in detectWorkingTreeBuild — enough to clear any
// node_modules/<scope>/<pkg>/dist/... chain without spinning toward filesystem root.
const WORKING_TREE_WALK_MAX_DEPTH = 8;
const NODE_GLOBAL_PACKAGE_MARKER = `${sep}lib${sep}node_modules${sep}${CLI_PACKAGE.replace(
  "/",
  sep,
)}`;

type PublishedInstall = {
  readonly entryPath: string;
  readonly installPrefix: string;
};

export function registerBuiltinUpdateCommand(parent: Command): void {
  addOutputModeOptions(
    parent
      .command("update")
      .summary("Check for or install the latest aventure-cli release")
      .description(
        [
          "Compare the running CLI version against the latest published",
          "release and (with --execute) install it.",
          "",
          "Default is dry-run (matches every other mutation in this CLI):",
          "  aventure-cli update                # report currentVersion vs latestVersion",
          "  aventure-cli update --execute      # update the active published bin prefix",
          "",
          "Refuses to install when the running binary is the working-tree build",
          "(use `make` to rebuild that). Requires npm authentication for",
          "@aventurevc packages when --execute is set.",
        ].join("\n"),
      )
      .option("--execute", "perform the upgrade; default is dry-run", false),
  ).action((options: UpdateOptions) =>
    emit({ mode: resolveOutputMode(options) }, runUpdate(options)),
  );
}

export function runUpdate(options: UpdateOptions): ResultEnvelope<CliVersionCheck | null> {
  // `packageJson.name` is the source workspace, never a published install target: the `aventure-cli`
  // bin ships only in the CLI variant, so that variant is the package this process is running from.
  const runningPackage = CLI_PACKAGE;
  const currentVersion = packageJson.version;

  const view = runNpm(["view", CLI_PACKAGE, "version", "--silent"], {
    timeout: NPM_VIEW_TIMEOUT_MS,
  });
  if (!view.ok) return { ...view, data: null };
  const latestVersion = (view.data ?? "").trim();
  if (latestVersion === "") {
    return failure(`npm view ${CLI_PACKAGE} returned empty version`, ["empty_stdout"]);
  }

  const upgradeAvailable = VERSION_COLLATOR.compare(currentVersion, latestVersion) < 0;
  const baseData: CliVersionCheck = {
    targetPackage: CLI_PACKAGE,
    runningPackage,
    currentVersion,
    latestVersion,
    upgradeAvailable,
    upgradeInstalled: false,
  };

  if (!options.execute) {
    const verb = upgradeAvailable ? "available" : "up to date";
    return success(
      `${runningPackage}@${currentVersion} → ${CLI_PACKAGE}@${latestVersion} (${verb})`,
      baseData,
    );
  }
  if (!upgradeAvailable) {
    return success(
      `${runningPackage}@${currentVersion} already matches ${CLI_PACKAGE}@${latestVersion}`,
      baseData,
    );
  }

  const dev = detectWorkingTreeBuild();
  if (dev !== null) {
    return failure(
      `Refusing to install over the working-tree build at ${dev}; rebuild via make instead`,
      ["running CLI is npm-linked from the back-end checkout — `update` is for published bins"],
    );
  }

  const publishedInstall = safeDetectPublishedInstall();
  const installArgs = ["install", "-g"];
  if (publishedInstall !== null) installArgs.push("--prefix", publishedInstall.installPrefix);
  installArgs.push(`${CLI_PACKAGE}@${latestVersion}`);
  const install = runNpm(installArgs, {
    stdio: ["ignore", "inherit", "inherit"],
  });
  if (!install.ok) return { ...install, data: null };
  const verifiedVersion =
    publishedInstall === null
      ? undefined
      : verifyInstalledCliVersion(publishedInstall.entryPath, latestVersion);
  if (verifiedVersion?.ok === false) return { ...verifiedVersion, data: null };
  const completionRefresh = refreshShellCompletions();
  return success(`${CLI_PACKAGE} upgraded to ${latestVersion}`, {
    ...baseData,
    upgradeInstalled: true,
    installPrefix: publishedInstall?.installPrefix,
    verifiedVersion: verifiedVersion?.data ?? undefined,
    completionRefreshed: completionRefresh.refreshed,
    completionRefreshMessage: completionRefresh.message,
  });
}

/**
 * One spawn point for every npm call this command makes. The aVenture scope stays pinned to GitHub
 * Packages, while npm configuration owns cache and authentication and the default registry remains
 * available for public transitive dependencies.
 *
 * Stdout-capturing callers (`npm view`) get a `success` envelope carrying
 * stdout; pass-through callers (`npm install`) inherit stdio and the `data`
 * payload is the empty string.
 */
function runNpm(
  args: readonly string[],
  options: Pick<SpawnSyncOptions, "stdio" | "timeout"> = {},
): ResultEnvelope<string | null> {
  const env = { ...process.env };
  env.NODE_AUTH_TOKEN ??= env.GH_PACKAGES_TOKEN;
  const fullArgs = [...args, `--@aventurevc:registry=${REGISTRY_URL}`];
  const result = spawnSync("npm", fullArgs, { env, encoding: "utf8", ...options });
  if (result.error) {
    // spawnSync reports a `timeout` expiry through `error`, which would otherwise read as a
    // launch failure and send the caller looking for a broken npm.
    const timedOut = result.signal === "SIGTERM" && options.timeout !== undefined;
    return timedOut
      ? failure(`npm ${args[0] ?? ""} did not answer within ${options.timeout}ms`, ["timeout"])
      : failure(`npm ${args[0] ?? ""} failed to start: ${result.error.message}`, ["spawn_error"]);
  }
  if (result.status !== 0) {
    const tail = (result.stderr ?? "").trim().split("\n").slice(-3).join(" | ");
    return failure(`npm ${args.join(" ")} exited ${result.status}`, [tail || "no stderr"]);
  }
  return success("npm ok", result.stdout ?? "");
}

function verifyInstalledCliVersion(
  entryPath: string,
  expectedVersion: string,
): ResultEnvelope<string | null> {
  const result = spawnSync(process.execPath, [entryPath, "--version"], {
    encoding: "utf8",
  });
  if (result.error) {
    return failure(`updated ${CLI_PACKAGE} verification failed: ${result.error.message}`, [
      "spawn_error",
    ]);
  }
  const actualVersion = (result.stdout ?? "").trim();
  if (result.status !== 0 || actualVersion !== expectedVersion) {
    const tail = (result.stderr ?? "").trim().split("\n").slice(-3).join(" | ");
    return failure(
      `updated ${CLI_PACKAGE} verification expected ${expectedVersion} but active bin reported ${
        actualVersion || "empty output"
      }`,
      [tail || `active bin: ${entryPath}`],
    );
  }
  return success("active CLI version verified", actualVersion);
}

/**
 * Returns the working-tree root when this process is running from an npm-linked
 * dev build (e.g. `~/.nvm/.../node_modules/@aventurevc/mcp-server` is a symlink
 * back into the back-end checkout), otherwise `null`. We walk from
 * `process.argv[1]` up to the package root and check for the TypeScript
 * sources that are excluded from the published tarball.
 */
function detectWorkingTreeBuild(): string | null {
  const entry = process.argv[1];
  if (!entry) return null;
  let cursor: string;
  try {
    cursor = realpathSync(entry);
  } catch {
    // entry path missing or not resolvable means we aren't in a dev tree
    return null;
  }
  for (let i = 0; i < WORKING_TREE_WALK_MAX_DEPTH; i += 1) {
    const parent = dirname(cursor);
    if (parent === cursor) return null;
    if (existsSync(resolve(parent, "aventure-cli", "index.ts"))) return parent;
    cursor = parent;
  }
  return null;
}

function safeDetectPublishedInstall(): PublishedInstall | null {
  const entry = process.argv[1];
  if (!entry) return null;
  let entryPath: string;
  try {
    entryPath = realpathSync(entry);
  } catch {
    // Unresolvable entry means there is no published package prefix to preserve.
    return null;
  }
  let cursor = entryPath;
  for (let i = 0; i < WORKING_TREE_WALK_MAX_DEPTH; i += 1) {
    const parent = dirname(cursor);
    if (parent === cursor) return null;
    if (existsSync(resolve(parent, "package.json"))) {
      const markerIndex = parent.lastIndexOf(NODE_GLOBAL_PACKAGE_MARKER);
      if (markerIndex < 0) return null;
      return { entryPath, installPrefix: parent.slice(0, markerIndex) };
    }
    cursor = parent;
  }
  return null;
}

function refreshShellCompletions(): ShellCompletionRefresh {
  try {
    return refreshShellCompletionsIfManaged();
  } catch (error) {
    return {
      refreshed: false,
      message: error instanceof Error ? error.message : String(error),
    };
  }
}
