import { spawnSync } from "node:child_process";
import {
  copyFileSync,
  existsSync,
  lstatSync,
  mkdirSync,
  readFileSync,
  realpathSync,
  renameSync,
  writeFileSync,
} from "node:fs";
import { createInterface } from "node:readline/promises";
import { homedir } from "node:os";
import { basename, dirname, resolve } from "node:path";
import process from "node:process";
import { Command } from "commander";

const BEGIN_MARKER = "# >>> aventure-cli completion setup (managed by aventure-cli) >>>";
const END_MARKER = "# <<< aventure-cli completion setup (managed by aventure-cli) <<<";
const BACKUP_SUFFIX = ".aventure-cli-completion.bak";

type ApplyMode = "install" | "uninstall";
type BlockKind = "fpath-only" | "fpath-and-compinit";
type Prompter = (message: string) => boolean | Promise<boolean>;
type ApplyManagedBlockOptions = {
  readonly rcFile: string;
  readonly installerPath: string;
  readonly mode: ApplyMode;
  readonly dryRun?: boolean;
  readonly prompter?: Prompter;
};
type ApplyManagedBlockResult = {
  readonly changed: boolean;
  readonly cancelled: boolean;
  readonly message: string;
  readonly content: string;
};
type SetupCommandOptions = {
  readonly dryRun?: boolean;
  readonly yes?: boolean;
  readonly uninstall?: boolean;
};
type CompletionInstallerOutput = {
  readonly stdout?: string;
  readonly stderr?: string;
  readonly status: number | null;
};
export type ShellCompletionRefresh = {
  readonly refreshed: boolean;
  readonly message: string;
};

export function registerCompletionInstallCommands(parent: Command): void {
  parent
    .command("install")
    .summary("install shell completion loaders")
    .description("Install managed shell completion loaders for supported shells.")
    .action(() => runCompletionInstaller([]));

  parent
    .command("uninstall")
    .summary("remove shell completion loaders")
    .description("Remove managed shell completion loaders installed by aventure-cli.")
    .action(() => runCompletionInstaller(["--uninstall"]));
}

export function registerCompletionSetupCommand(parent: Command): void {
  parent
    .command("setup")
    .summary("configure zsh completion startup")
    .description("Configure ~/.zshrc so zsh loads aventure-cli completion loaders.")
    .option("--dry-run", "print the managed zshrc block without writing")
    .option("--yes", "apply without prompting")
    .option("--uninstall", "remove the managed zshrc block")
    .action(async (options: SetupCommandOptions) => {
      const installerPath = completionInstallerPath();
      const result = await applyManagedBlock({
        rcFile: resolve(homedir(), ".zshrc"),
        installerPath,
        mode: options.uninstall ? "uninstall" : "install",
        dryRun: options.dryRun,
        prompter: options.yes || options.dryRun ? undefined : promptYesNo,
      });
      process.stdout.write(`${result.message}\n`);
      if (!result.cancelled && !options.dryRun) {
        runCompletionInstaller(options.uninstall ? ["--uninstall"] : []);
      }
    });
}

export function renderManagedBlock(installerPath: string, kind: BlockKind = "fpath-only"): string {
  const body = [
    `# installer: ${installerPath}`,
    'fpath=("${XDG_DATA_HOME:-$HOME/.local/share}/zsh/site-functions" $fpath)',
    ...(kind === "fpath-and-compinit" ? ["autoload -Uz compinit", "compinit"] : []),
  ];
  return [BEGIN_MARKER, ...body, END_MARKER].join("\n");
}

export function refreshShellCompletionsIfManaged(): ShellCompletionRefresh {
  const status = runCompletionInstaller(["--status"], "pipe");
  if (status.status !== 0) {
    return {
      refreshed: false,
      message: `completion status exited ${status.status ?? 1}`,
    };
  }
  if (!hasManagedCompletion(status.stdout ?? "")) {
    return { refreshed: false, message: "no managed shell completions found" };
  }

  const install = runCompletionInstaller([], "pipe");
  if (install.status !== 0) {
    return {
      refreshed: false,
      message: `completion refresh exited ${install.status ?? 1}`,
    };
  }
  return {
    refreshed: true,
    message: (install.stdout ?? "").trim() || "shell completions refreshed",
  };
}

export async function applyManagedBlock({
  rcFile,
  installerPath,
  mode,
  dryRun = false,
  prompter,
}: ApplyManagedBlockOptions): Promise<ApplyManagedBlockResult> {
  const existing = readRegularFile(rcFile);
  const lines = existing.length === 0 ? [] : existing.split("\n");
  const bounds = managedBlockBounds(lines, rcFile);
  if (mode === "uninstall" && bounds === null) {
    return {
      changed: false,
      cancelled: false,
      message: `${rcFile}: already up-to-date`,
      content: existing,
    };
  }
  const next =
    mode === "install"
      ? installContent(lines, bounds, installerPath, rcFile)
      : uninstallContent(lines, bounds);
  if (next === existing) {
    return {
      changed: false,
      cancelled: false,
      message: `${rcFile}: already up-to-date`,
      content: next,
    };
  }
  if (dryRun) return { changed: true, cancelled: false, message: next, content: next };
  if (prompter !== undefined && !(await prompter(`Update ${rcFile}?`))) {
    return { changed: true, cancelled: true, message: `${rcFile}: cancelled`, content: existing };
  }
  writeFileAtomically(rcFile, next);
  return { changed: true, cancelled: false, message: `${rcFile}: updated`, content: next };
}

export function completionInstallerPath(entryPath = process.argv[1]): string {
  // PATH bins are symlink chains (~/.local/bin → prefix bin → package dist) and
  // ESM entries keep the symlink in argv[1]; without the physical entry the
  // package-relative scripts/ lookup escapes the package and the spawn exits 1.
  const entry = entryPath === undefined ? "" : physicalEntryPath(entryPath);
  const builtPackagePath = resolve(
    dirname(entry),
    "..",
    "..",
    "scripts",
    "install-zsh-completion-loader.mjs",
  );
  if (existsSync(builtPackagePath)) return builtPackagePath;
  return resolve(dirname(entry), "..", "scripts", "install-zsh-completion-loader.mjs");
}

function physicalEntryPath(entryPath: string): string {
  try {
    return realpathSync(entryPath);
  } catch {
    return resolve(entryPath);
  }
}

function runCompletionInstaller(args: readonly string[]): void;
function runCompletionInstaller(args: readonly string[], stdio: "inherit"): void;
function runCompletionInstaller(args: readonly string[], stdio: "pipe"): CompletionInstallerOutput;
function runCompletionInstaller(
  args: readonly string[],
  stdio: "inherit" | "pipe" = "inherit",
): void | CompletionInstallerOutput {
  const result = spawnSync(process.execPath, [completionInstallerPath(), ...args], {
    encoding: stdio === "pipe" ? "utf8" : undefined,
    stdio,
  });
  if (result.error !== undefined) throw result.error;
  if (stdio === "inherit") {
    if (result.status !== 0) process.exitCode = result.status ?? 1;
    return;
  }
  return {
    stdout: result.stdout?.toString(),
    stderr: result.stderr?.toString(),
    status: result.status,
  };
}

function hasManagedCompletion(statusOutput: string): boolean {
  return statusOutput.split(/\r?\n/u).some((line) => line.trim().endsWith(": managed"));
}

function readRegularFile(file: string): string {
  if (!existsSync(file)) return "";
  refuseSymlink(file);
  return readFileSync(file, "utf8");
}

function managedBlockBounds(
  lines: readonly string[],
  file: string,
): readonly [number, number] | null {
  const begin = lineIndexes(lines, BEGIN_MARKER);
  const end = lineIndexes(lines, END_MARKER);
  if (begin.length === 0 && end.length === 0) return null;
  if (begin.length !== 1 || end.length !== 1 || begin[0] >= end[0]) {
    throw new Error(
      `${file} has malformed aventure-cli completion setup markers; fix manually before retrying.`,
    );
  }
  return [begin[0], end[0]];
}

function installContent(
  lines: readonly string[],
  bounds: readonly [number, number] | null,
  installerPath: string,
  file: string,
): string {
  const withoutBlock =
    bounds === null ? [...lines] : [...lines.slice(0, bounds[0]), ...lines.slice(bounds[1] + 1)];
  const existingCompinit = firstCompinitLine(withoutBlock);
  const kind: BlockKind = existingCompinit === -1 ? "fpath-and-compinit" : "fpath-only";
  const block = renderManagedBlock(installerPath, kind).split("\n");
  const insertion = bounds === null ? existingCompinit : bounds[0];
  const target = insertion === -1 ? withoutBlock.length : insertion;
  if (bounds !== null && existingCompinit !== -1 && existingCompinit < target) {
    throw new Error(
      `${file} runs compinit before the managed block; move the block above compinit manually.`,
    );
  }
  return finish([...withoutBlock.slice(0, target), ...block, ...withoutBlock.slice(target)]);
}

function uninstallContent(
  lines: readonly string[],
  bounds: readonly [number, number] | null,
): string {
  if (bounds === null) return finish(lines);
  return finish([...lines.slice(0, bounds[0]), ...lines.slice(bounds[1] + 1)]);
}

function lineIndexes(lines: readonly string[], marker: string): readonly number[] {
  return lines.flatMap((line, index) => (line === marker ? [index] : []));
}

function firstCompinitLine(lines: readonly string[]): number {
  return lines.findIndex((line) => /^\s*(autoload\s+.*\bcompinit\b|compinit(?:\s|$))/.test(line));
}

function writeFileAtomically(file: string, content: string): void {
  mkdirSync(dirname(file), { recursive: true });
  if (existsSync(file)) {
    refuseSymlink(file);
    refuseSymlink(`${file}${BACKUP_SUFFIX}`);
    copyFileSync(file, `${file}${BACKUP_SUFFIX}`);
  }
  const temporary = resolve(dirname(file), `.${basename(file)}.${process.pid}.tmp`);
  refuseSymlink(temporary);
  writeFileSync(temporary, content, { mode: 0o644 });
  renameSync(temporary, file);
}

function refuseSymlink(file: string): void {
  if (existsSync(file) && lstatSync(file).isSymbolicLink()) {
    throw new Error(`refusing to write symlink: ${file}`);
  }
}

function finish(lines: readonly string[]): string {
  const text = lines.join("\n");
  return text.length === 0 || text.endsWith("\n") ? text : `${text}\n`;
}

async function promptYesNo(message: string): Promise<boolean> {
  const readline = createInterface({ input: process.stdin, output: process.stdout });
  try {
    const answer = await readline.question(`${message} [y/N] `);
    return /^(y|yes)$/i.test(answer.trim());
  } finally {
    readline.close();
  }
}
