import { hostname, platform } from "node:os";
import { stdin as input, stderr as prompts } from "node:process";
import { setTimeout as wait } from "node:timers/promises";

import type { CliAuthorizationDelivery } from "@aventurevc/api-schemas/cli/authorization-delivery";
import {
  CliAuthorizationMutationSchema,
  type CliAuthorizationMutation,
} from "@aventurevc/api-schemas/cli/authorization-mutation";
import type { CliAuthorizationStart } from "@aventurevc/api-schemas/cli/authorization-start";
import type { PersonalApiKey } from "@aventurevc/api-schemas/personal/api-key";
import { readEnv } from "../../api/env.ts";
import { failure, success, type ResultEnvelope } from "../../api/result-envelope.ts";
import { browserOriginForApiHost } from "./api-target.ts";
import {
  createCliAuthorizationKeyPair,
  decryptCliAuthorizationCredential,
  type CliAuthorizationKeyPair,
} from "./authorization-crypto.ts";
import {
  openVerificationUrl,
  redactedVerificationUrl,
  type BrowserOpenResult,
} from "./browser-opening.ts";
import {
  acknowledgeCliAuthorization,
  CliAuthorizationRequestError,
  CliAuthorizationTransportError,
  pollCliAuthorization,
  startCliAuthorization,
} from "./cli-authorization-client.ts";
import { credentialSafeMessage, redactCredentialText } from "./credential-redaction.ts";
import {
  canonicalPersonalCredentialHost,
  forgetPersonalCredential,
  loadPersonalCredential,
  savePersonalCredential,
  type StoredPersonalCredential,
} from "./personal-credential.ts";
import { verifyPersonalCredentialAccess } from "./personal-credential-verification.ts";
import { revokeStoredCredential } from "./personal-logout.ts";

const ENCRYPTION_ALGORITHM = "RSA_OAEP_256_A256_GCM_V1";
const MINIMUM_POLL_INTERVAL_SECONDS = 1;
const MAXIMUM_POLL_INTERVAL_SECONDS = 30;

/**
 * Acknowledgment is the only thing that lifts a delivered key from the authorization deadline
 * (`app.clerk-auth.cli-authorization.request-ttl`, 10m) to the granted lifetime
 * (`app.clerk-auth.personal-api-key.acknowledged-key-lifetime`, 365d), and
 * `AppClerkAuthProperties.kt:57` requires the latter to exceed the former. One day sits inside
 * that gap, so the server-issued `expiresAt - createdAt` span separates the two lifetimes without
 * consulting the client clock.
 */
const ACKNOWLEDGED_KEY_MINIMUM_LIFETIME_MILLISECONDS = 24 * 60 * 60 * 1000;

type CliAuthorizationClientPlatform = NonNullable<CliAuthorizationMutation["clientPlatform"]>;

export interface PersonalLoginOptions {
  readonly noBrowser: boolean;
  readonly clientLabel?: string;
}

interface PersonalLoginDiagnostics {
  readonly host: string;
  readonly provider: "keyring";
  readonly personalApiKeyId: string;
  readonly name: string;
  readonly activation: "pending" | "active";
  readonly verified: boolean;
}

/** Run one browser-approved login without persisting the poll secret or private key. */
export async function loginPersonalCredential(
  options: PersonalLoginOptions,
): Promise<ResultEnvelope<PersonalLoginDiagnostics | null>> {
  if (!input.isTTY) {
    return failure("aventure-cli auth login requires an interactive TTY on stdin", [
      "For non-interactive automation, inject CLIENT_SECRET, ADMIN_API_KEY, or AUTH_TOKEN through the environment or configured Doppler source.",
    ]);
  }
  let host: string;
  let browserOrigin: string;
  try {
    const apiHost = readEnv().host;
    host = canonicalPersonalCredentialHost(apiHost);
    browserOrigin = browserOriginForApiHost(apiHost);
  } catch (error) {
    return failure(
      `auth login: invalid environment configuration — ${credentialSafeMessage(error)}`,
    );
  }

  let existing: Awaited<ReturnType<typeof loadPersonalCredential>>;
  try {
    existing = await loadPersonalCredential(host);
  } catch (error) {
    return failure(
      `auth login: stored credential could not be read — ${credentialSafeMessage(error)}`,
    );
  }
  if (existing.state === "unavailable") {
    return failure(`auth login: ${existing.summary}`);
  }
  if (existing.state === "found") {
    const resolved = await existingCredential(existing.stored);
    if (resolved !== null) return resolved;
  }

  let keyPair: CliAuthorizationKeyPair;
  try {
    keyPair = await createCliAuthorizationKeyPair();
  } catch (error) {
    return failure(
      `auth login: ephemeral encryption key could not be created — ${credentialSafeMessage(error)}`,
    );
  }
  const mutation = CliAuthorizationMutationSchema.safeParse({
    clientLabel: options.clientLabel?.trim() || (hostname().trim() || "aventure-cli").slice(0, 120),
    clientPlatform: clientPlatform(),
    encryptionAlgorithm: ENCRYPTION_ALGORITHM,
    encryptionPublicKey: keyPair.publicKey,
  });
  if (!mutation.success) return failure("auth login: local authorization input is invalid");

  let started: CliAuthorizationStart;
  try {
    started = await startCliAuthorization(mutation.data);
  } catch (error) {
    return failure(
      `auth login: could not start browser authorization — ${credentialSafeMessage(error)}`,
    );
  }
  let verificationReference: string;
  try {
    verificationReference = redactedVerificationUrl(started, browserOrigin);
  } catch (error) {
    return failure(
      `auth login: unsafe browser authorization URL rejected — ${credentialSafeMessage(error)}`,
    );
  }
  const browser = await openVerificationUrl(started, browserOrigin, {
    noBrowser: options.noBrowser,
  });
  if (!printVerificationInstructions(browser, started, verificationReference)) {
    return failure(
      "auth login: browser authorization requires an interactive terminal for manual handoff",
      [
        "Automatic browser opening did not complete, and the approval URL was withheld because stderr is not an interactive terminal. Retry from an interactive terminal.",
      ],
      { references: [verificationReference] },
    );
  }

  let delivery: CliAuthorizationDelivery;
  try {
    delivery = await waitForCredential(started);
  } catch (error) {
    return failure(
      `auth login: authorization did not complete — ${credentialSafeMessage(error)}`,
      [],
      {
        references: [verificationReference],
      },
    );
  }
  if (delivery.algorithm !== ENCRYPTION_ALGORITHM) {
    return failure("auth login: broker selected an unsupported encryption algorithm");
  }

  let oneTimeSecret: string;
  try {
    oneTimeSecret = await decryptCliAuthorizationCredential(keyPair.privateKey, delivery);
  } catch (error) {
    return failure(
      `auth login: encrypted credential could not be opened — ${credentialSafeMessage(error)}`,
    );
  }

  const verification = await verifyPersonalCredentialAccess(oneTimeSecret);
  if (verification.state !== "verified") {
    return failure(
      `auth login: decrypted credential was neither stored nor acknowledged — ${verification.summary}`,
    );
  }

  let stored: StoredPersonalCredential;
  try {
    stored = await savePersonalCredential(
      host,
      { apiKey: verification.apiKey, secret: oneTimeSecret },
      "pending",
    );
  } catch (error) {
    return failure(
      `auth login: credential could not be durably stored — ${credentialSafeMessage(error)}`,
    );
  }

  let acknowledged: Awaited<ReturnType<typeof acknowledgeCliAuthorization>>;
  try {
    acknowledged = await acknowledgeUntilAuthorizationDeadline(started);
  } catch (error) {
    return pendingAcknowledgementFailure(
      stored,
      `auth login: credential was stored and verified, but broker acknowledgment was not confirmed — ${credentialSafeMessage(error, [started.pollSecret])}`,
    );
  }
  if (acknowledged.status !== "CONSUMED") {
    return pendingAcknowledgementFailure(
      stored,
      `auth login: broker returned ${acknowledged.status} after acknowledgment`,
    );
  }
  let active: StoredPersonalCredential;
  try {
    active = await savePersonalCredential(host, stored.credential, "active");
  } catch (error) {
    return pendingAcknowledgementFailure(
      stored,
      `auth login: remote acknowledgment succeeded, but local activation could not be confirmed — ${credentialSafeMessage(error)}`,
    );
  }
  return success(
    "Personal CLI credential stored; authenticated identity and broker acknowledgment verified.",
    diagnostics(active, true),
    { ids: [active.credential.apiKey.id] },
  );
}

function pendingAcknowledgementFailure(
  stored: StoredPersonalCredential,
  summary: string,
): ResultEnvelope<PersonalLoginDiagnostics | null> {
  return {
    ...failure(summary, [
      "The local record remains pending and unavailable to ordinary commands. Re-run `aventure-cli auth login`; it recovers the credential when the broker acknowledged it, and otherwise clears the stale record.",
    ]),
    data: diagnostics(stored, true),
  };
}

/** Resolves a stored credential to a terminal envelope, or null once a stale pending record is cleared. */
async function existingCredential(
  stored: StoredPersonalCredential,
): Promise<ResultEnvelope<PersonalLoginDiagnostics | null> | null> {
  const verification = await verifyPersonalCredentialAccess(stored.credential.secret);
  if (stored.activation !== "pending") {
    if (verification.state !== "verified") {
      return {
        ...failure(
          `auth login: stored credential ${verification.state} — ${verification.summary}`,
          ["Run `aventure-cli auth logout` to revoke/remove it before authorizing a replacement."],
        ),
        data: diagnostics(stored, false),
      };
    }
    return success(
      "Personal CLI credential is already stored and its authenticated identity was verified.",
      diagnostics(stored, true),
      { ids: [stored.credential.apiKey.id] },
    );
  }
  // A pending keyring record re-emerges when the broker acknowledged (and so extended) the remote
  // key but the local promotion to "active" failed — the poll secret is not persisted, so local
  // state can never activate itself. An acknowledged key carries the granted lifetime and is
  // recovered in place; only an authentication rejection proves the remote key is inert.
  if (verification.state === "verified" && isAcknowledgedLifetime(verification.apiKey)) {
    // Persist the freshly-verified metadata: the stored copy predates acknowledgment, so its
    // expiresAt still reflects the authorization deadline rather than the granted lifetime.
    try {
      const active = await savePersonalCredential(
        stored.host,
        { apiKey: verification.apiKey, secret: stored.credential.secret },
        "active",
      );
      return success(
        "Recovered pending CLI credential: broker acknowledgment had succeeded.",
        diagnostics(active, true),
        { ids: [active.credential.apiKey.id] },
      );
    } catch (error) {
      return {
        ...failure(
          `auth login: credential is valid but could not be promoted locally — ${credentialSafeMessage(error, [stored.credential.secret])}`,
          [
            "The remote key remains valid. Re-run `aventure-cli auth login` to retry local activation; it will recover the pending credential automatically.",
          ],
        ),
        data: diagnostics(stored, true),
      };
    }
  }
  if (verification.state === "unavailable") {
    // No authentication verdict was reached: every transport failure and every non-401/403 status
    // lands here, so the remote key may still be a live acknowledged credential. Preserve the
    // keyring record and the remote key rather than destroying a possibly valid credential.
    return {
      ...failure(
        `auth login: the stored pending credential could not be verified — ${verification.summary}`,
        [
          "The stored record and the remote key were both preserved. Re-run `aventure-cli auth login` when the API is reachable; it recovers an acknowledged credential and clears an unacknowledged one.",
        ],
      ),
      data: diagnostics(stored, false),
    };
  }
  // Authentication rejected the key, or it expires at the authorization deadline and was never
  // acknowledged; either way the remote key is inert and the stale record is cleared.
  const revocation = await revokeStoredCredential(stored);
  if (revocation.outcome === "unconfirmed") {
    return {
      ...failure(
        "auth login: a prior credential is durably stored but broker acknowledgment was not confirmed",
        [
          `Remote revocation of the stale pending key was not confirmed — ${revocation.summary}. Retry when the API is reachable.`,
        ],
      ),
      data: diagnostics(stored, false),
    };
  }
  try {
    await forgetPersonalCredential(stored.host);
  } catch (error) {
    return {
      ...failure(
        `auth login: stale pending credential could not be removed — ${credentialSafeMessage(error, [stored.credential.secret])}`,
      ),
      data: diagnostics(stored, false),
    };
  }
  prompts.write(
    revocation.outcome === "revoked"
      ? "Revoked and cleared a stale pending CLI credential; starting a fresh browser authorization.\n"
      : "Cleared a stale pending CLI credential whose remote key can no longer authenticate; starting a fresh browser authorization.\n",
  );
  return null;
}

/**
 * Retry retryable acknowledgment failures (transport-unknown outcomes, 5xx, 429) at the poll
 * cadence until the authorization deadline; the broker's replay proof keeps replays idempotent.
 */
async function acknowledgeUntilAuthorizationDeadline(
  started: CliAuthorizationStart,
): Promise<Awaited<ReturnType<typeof acknowledgeCliAuthorization>>> {
  const expiresAt = new Date(started.expiresAt).getTime();
  let intervalSeconds = boundedPollInterval(started.intervalSeconds);
  for (;;) {
    try {
      return await acknowledgeCliAuthorization(started.id, started.pollSecret);
    } catch (error) {
      if (error instanceof CliAuthorizationRequestError) {
        if (!error.retryable) throw error;
        intervalSeconds = boundedPollInterval(error.retryAfterSeconds ?? intervalSeconds);
      } else if (!(error instanceof CliAuthorizationTransportError)) throw error;
      if (Date.now() >= expiresAt) throw error;
      prompts.write("Broker acknowledgment was interrupted; retrying.\n");
      await waitForNextPoll(intervalSeconds, expiresAt);
    }
  }
}

async function waitForCredential(
  started: CliAuthorizationStart,
): Promise<CliAuthorizationDelivery> {
  const expiresAt = new Date(started.expiresAt).getTime();
  let intervalSeconds = boundedPollInterval(started.intervalSeconds);
  let lastRetryableFailure: unknown;
  prompts.write("Waiting for browser approval...\n");
  while (Date.now() < expiresAt) {
    let result: Awaited<ReturnType<typeof pollCliAuthorization>>;
    try {
      result = await pollCliAuthorization(started.id, started.pollSecret);
    } catch (error) {
      if (error instanceof CliAuthorizationRequestError) {
        if (!error.retryable) throw error;
        intervalSeconds = boundedPollInterval(error.retryAfterSeconds ?? intervalSeconds);
      }
      lastRetryableFailure = error;
      prompts.write("Authorization poll was interrupted; retrying.\n");
      await waitForNextPoll(intervalSeconds, expiresAt);
      continue;
    }
    lastRetryableFailure = undefined;
    const authorization = result.authorization;
    switch (authorization.status) {
      case "PENDING":
      case "ISSUING":
      case "REVOKING":
        intervalSeconds = boundedPollInterval(result.retryAfterSeconds ?? intervalSeconds);
        await waitForNextPoll(intervalSeconds, expiresAt);
        break;
      case "KEY_READY":
        if (authorization.delivery === null || authorization.delivery === undefined) {
          throw new Error("broker returned KEY_READY without an encrypted delivery");
        }
        return authorization.delivery;
      case "DENIED":
      case "EXPIRED":
      case "FAILED":
        throw new Error(
          redactCredentialText(authorization.terminalReason?.trim() ?? "", [started.pollSecret]) ||
            `broker entered terminal state ${authorization.status}`,
        );
      case "CONSUMED":
        throw new Error("broker credential was already consumed; restart login");
    }
  }
  if (lastRetryableFailure !== undefined) {
    throw new Error(
      `browser authorization expired after a retryable broker failure: ${credentialSafeMessage(lastRetryableFailure, [started.pollSecret])}`,
    );
  }
  throw new Error("browser authorization expired before approval completed");
}

/**
 * Keep successful automatic opening free of the raw URL, exposing it only for an interactive
 * manual handoff when the browser opener cannot carry the possession secret itself.
 */
function printVerificationInstructions(
  browser: BrowserOpenResult,
  started: CliAuthorizationStart,
  verificationReference: string,
): boolean {
  const opened = browser.state === "opened";
  if (!opened && !prompts.isTTY) return false;
  prompts.write(
    [
      ...(opened
        ? [
            "Browser approval opened for this request.",
            `Approval reference: ${verificationReference}`,
          ]
        : [
            `Browser not opened automatically (${browser.reason}).`,
            "Open this one-time approval URL in your browser:",
            started.verificationUrl,
          ]),
      `Comparison code: ${started.comparisonCode}`,
      "Confirm that the browser shows the same code before approving.",
      "",
    ].join("\n"),
  );
  return true;
}

function clientPlatform(): CliAuthorizationClientPlatform {
  switch (platform()) {
    case "darwin":
      return "MACOS";
    case "linux":
      return "LINUX";
    case "win32":
      return "WINDOWS";
    default:
      return "OTHER";
  }
}

function boundedPollInterval(seconds: number): number {
  return Math.min(MAXIMUM_POLL_INTERVAL_SECONDS, Math.max(MINIMUM_POLL_INTERVAL_SECONDS, seconds));
}

async function waitForNextPoll(intervalSeconds: number, expiresAt: number): Promise<void> {
  const remainingMilliseconds = expiresAt - Date.now();
  if (remainingMilliseconds > 0) {
    await wait(Math.min(intervalSeconds * 1_000, remainingMilliseconds));
  }
}

function diagnostics(
  stored: StoredPersonalCredential,
  verified: boolean,
): PersonalLoginDiagnostics {
  return {
    host: stored.host,
    provider: "keyring",
    personalApiKeyId: stored.credential.apiKey.id,
    name: redactCredentialText(stored.credential.apiKey.name, [stored.credential.secret]),
    activation: stored.activation,
    verified,
  };
}

/**
 * True only when the server-issued lifetime span proves the broker acknowledged the key. Both
 * timestamps come from the provider, so no client clock is consulted. A nullish expiry is treated
 * as unacknowledged, never as a permanent key.
 */
function isAcknowledgedLifetime(apiKey: PersonalApiKey): boolean {
  if (apiKey.expiresAt === null || apiKey.expiresAt === undefined) return false;
  const grantedLifetimeMilliseconds =
    new Date(apiKey.expiresAt).getTime() - new Date(apiKey.createdAt).getTime();
  return grantedLifetimeMilliseconds > ACKNOWLEDGED_KEY_MINIMUM_LIFETIME_MILLISECONDS;
}
