import { inspect } from "node:util";

import {
  CliAuthorizationSchema,
  type CliAuthorization,
} from "@aventurevc/api-schemas/cli/authorization";
import type { CliAuthorizationMutation } from "@aventurevc/api-schemas/cli/authorization-mutation";
import {
  CliAuthorizationPollSchema,
  type CliAuthorizationPoll,
} from "@aventurevc/api-schemas/cli/authorization-poll";
import {
  CliAuthorizationStartSchema,
  type CliAuthorizationStart,
} from "@aventurevc/api-schemas/cli/authorization-start";
import {
  HTTP_SERVER_ERROR_MIN,
  HTTP_TOO_MANY_REQUESTS,
} from "@aventurevc/api-schemas/client/http/status-code";

import {
  aventureRequest,
  type AventureProblemDetail,
  type AventureResponse,
} from "../../api/client.ts";
import { readEnv } from "../../api/env.ts";
import { buildOpenApiTemplatePath } from "../../api/openapi-document.ts";
import { buildRequiredOpenApiHeader } from "../../api/openapi-call.ts";
import { openApiCompositeSpec } from "../../mcp-server/contract.ts";
import { GENERATED_OPENAPI_COMPOSITE_SPECS } from "../generated/openapi-composites.ts";
import { normalizeCliApiEnvironment } from "./api-target.ts";
import { credentialSafeMessage, credentialSafeProblemSummary } from "./credential-redaction.ts";

const START_AUTHORIZATION = openApiCompositeSpec(GENERATED_OPENAPI_COMPOSITE_SPECS, "start");
const POLL_AUTHORIZATION = openApiCompositeSpec(GENERATED_OPENAPI_COMPOSITE_SPECS, "poll");
const ACKNOWLEDGE_AUTHORIZATION = openApiCompositeSpec(
  GENERATED_OPENAPI_COMPOSITE_SPECS,
  "acknowledge",
);

export class CliAuthorizationRequestError extends Error {
  readonly httpStatus: number;
  readonly retryAfterSeconds: number | null;
  /** Whether the failure is a transient broker condition (5xx or 429) worth retrying. */
  readonly retryable: boolean;

  constructor(
    operation: string,
    problem: AventureProblemDetail,
    credentialValue: readonly string[] = [],
  ) {
    super(
      `CLI authorization ${operation} failed: ${credentialSafeProblemSummary(problem, credentialValue)}`,
    );
    this.name = "CliAuthorizationRequestError";
    this.httpStatus = problem.status;
    this.retryAfterSeconds = validatedRetryAfterSeconds(problem.retryAfterSeconds);
    this.retryable =
      problem.status >= HTTP_SERVER_ERROR_MIN || problem.status === HTTP_TOO_MANY_REQUESTS;
  }
}

/** Marks an acknowledgment whose server-side result is unknown because transport never returned. */
export class CliAuthorizationTransportError extends Error {
  constructor(operation: string, error: unknown, credentialValue: readonly string[] = []) {
    super(
      `CLI authorization ${operation} transport failed: ${credentialSafeMessage(error, credentialValue)}`,
      { cause: error },
    );
    this.name = "CliAuthorizationTransportError";
  }
}

/** Keep one-time start credentials usable while making ordinary object stringification safe. */
export async function startCliAuthorization(
  mutation: CliAuthorizationMutation,
): Promise<CliAuthorizationStart> {
  const response = await aventureRequest(
    normalizeCliApiEnvironment(readEnv()),
    {
      method: START_AUTHORIZATION.method,
      path: buildOpenApiTemplatePath(START_AUTHORIZATION.path, {}, START_AUTHORIZATION.operationId),
      headers: {},
      contentType: "application/json",
      body: mutation,
    },
    CliAuthorizationStartSchema,
  );
  if (!response.ok) throw new CliAuthorizationRequestError("start", response.problem);
  return protectedCliAuthorizationStart(response.data);
}

export interface CliAuthorizationPollResult {
  readonly authorization: CliAuthorizationPoll;
  readonly retryAfterSeconds: number | null;
}

export async function pollCliAuthorization(
  authorizationId: string,
  pollSecret: string,
): Promise<CliAuthorizationPollResult> {
  const pollSecretHeader = buildRequiredOpenApiHeader(POLL_AUTHORIZATION.operationId);
  const response = await aventureRequest(
    normalizeCliApiEnvironment(readEnv()),
    {
      method: POLL_AUTHORIZATION.method,
      path: buildOpenApiTemplatePath(
        POLL_AUTHORIZATION.path,
        { cliAuthorizationId: authorizationId },
        POLL_AUTHORIZATION.operationId,
      ),
      headers: { [pollSecretHeader]: pollSecret },
    },
    CliAuthorizationPollSchema,
  );
  if (!response.ok) {
    throw new CliAuthorizationRequestError("poll", response.problem, [pollSecret]);
  }
  return {
    authorization: response.data,
    retryAfterSeconds: headerRetryAfterSeconds(response.headers["retry-after"]),
  };
}

export async function acknowledgeCliAuthorization(
  authorizationId: string,
  pollSecret: string,
): Promise<CliAuthorization> {
  const pollSecretHeader = buildRequiredOpenApiHeader(ACKNOWLEDGE_AUTHORIZATION.operationId);
  let response: AventureResponse<CliAuthorization>;
  try {
    response = await aventureRequest(
      normalizeCliApiEnvironment(readEnv()),
      {
        method: ACKNOWLEDGE_AUTHORIZATION.method,
        path: buildOpenApiTemplatePath(
          ACKNOWLEDGE_AUTHORIZATION.path,
          { cliAuthorizationId: authorizationId },
          ACKNOWLEDGE_AUTHORIZATION.operationId,
        ),
        headers: { [pollSecretHeader]: pollSecret },
      },
      CliAuthorizationSchema,
    );
  } catch (error) {
    throw new CliAuthorizationTransportError("acknowledge", error, [pollSecret]);
  }
  if (!response.ok) {
    throw new CliAuthorizationRequestError("acknowledge", response.problem, [pollSecret]);
  }
  return response.data;
}

function headerRetryAfterSeconds(value: string | undefined): number | null {
  if (value === undefined) return null;
  const parsed = Number(value);
  return Number.isInteger(parsed) && parsed > 0 ? parsed : null;
}

function validatedRetryAfterSeconds(value: unknown): number | null {
  return typeof value === "number" && Number.isInteger(value) && value > 0 ? value : null;
}

/** Hide both the browser URL and poll credential from JSON, inspection, snapshots, and spreads. */
function protectedCliAuthorizationStart(started: CliAuthorizationStart): CliAuthorizationStart {
  const { verificationUrl, pollSecret, ...nonSecretField } = started;
  const protectedStart: CliAuthorizationStart = { ...started };
  const redacted = () => ({
    ...nonSecretField,
    verificationUrl: "<redacted>",
    pollSecret: "<redacted>",
  });
  return Object.defineProperties(protectedStart, {
    verificationUrl: { enumerable: false, get: () => verificationUrl },
    pollSecret: { enumerable: false, get: () => pollSecret },
    toJSON: { enumerable: false, value: redacted },
    toString: {
      enumerable: false,
      value: () => `CliAuthorizationStart(${JSON.stringify(redacted())})`,
    },
    [inspect.custom]: { enumerable: false, value: redacted },
  });
}
