#!/usr/bin/env node
/**
 * LLM AGENTS MAY NOT EDIT THIS FILE UNDER ANY CIRCUMSTANCES.
 *
 * All MCP/CLI/API-schema contract, schema, annotation, option-help, or tool-shape edits
 * must be made at the canonical Kotlin `.kt` source owner and its direct
 * annotations, then regenerated through the approved OpenAPI/api-schemas/MCP pipeline.
 *
 * Canonical law: `AGENTS.md` [MCP1b.1], [AS1m], [PG1e/f], [PG1g], [SS1a/b/i],
 * and [RC1]. Supporting docs: `docs/code-change.md` OpenAPI Auto-Generation Procedure,
 * `docs/api-contracts/openapi.md`, and `docs/kotlin-endpoint-structure.md`.
 * Supporting skills: `aventure`, `openapi`, `springdoc`, `zod`, and `mcp-builder`.
 */
/**
 * aventure-cli entrypoint.
 *  - Commander program + subcommands; each command registers via register*(parent).
 *  - Help text is first-class per AGENTS.md [MCP1c]: summary + description on every
 *    command/option, environment block on root --help, showHelpAfterError().
 *  - Stdout contract: clean text on a terminal, the --data payload when stdout is piped or
 *    redirected (`output-mode.ts` owns that default); --json emits the stable envelope.
 *    Fatal crashes still emit an envelope so MCP/server-side callers do not lose the root cause.
 */
import { Command, Option } from "commander";
import packageJson from "../package.json" with { type: "json" };
import { logError } from "../logging.ts";
import { buildOpenApiPath, runOpenApiCall } from "../api/openapi-call.ts";
import { environmentNames, normalizeEnvironmentName } from "../api/env.ts";
import { materializeAuth } from "../api/auth-resolver.ts";
import { failure, success, type ResultEnvelope } from "../api/result-envelope.ts";
import {
  addBodyOptions,
  readGeneratedBody,
  type GeneratedCommandOpts,
} from "./commands/generated-body.ts";
import { registerCuratedHelpCommand } from "./commands/curated-help.ts";
import { registerSearchParentModeOption } from "./commands/search-parent-mode.ts";
import { CLI_COMMAND_SECTION, CLI_NAMESPACE_SECTION } from "../config/cli-help-policy.ts";
import { CLI_SHELL_INPUT_GUIDANCE, cliShellSensitiveSchema } from "../config/tool-policy.ts";
import type {
  OpenApiCommandSpec as GeneratedCommandSpec,
  OpenApiCommandParameter as GeneratedParameter,
} from "../mcp-server/contract.ts";
import { visibleOpenApiCommandSpecsForCurrentAuth } from "../mcp-server/contract-visibility.ts";
import { GENERATED_CLI_NAMESPACES } from "./generated/cli-namespaces.ts";
import { GENERATED_OPENAPI_COMMAND_SPECS } from "./generated/openapi-commands.ts";
import { emit, emitJson } from "./output.ts";
import {
  addOutputModeOptions,
  outputModeJsonAccept,
  resolveOutputMode,
  type CliOutputMode,
  type CliOutputOptions,
} from "./output-mode.ts";
import { registerBuiltinAuthCommands } from "./commands/builtin-auth.ts";
import { registerBuiltinBatchCommand } from "./commands/builtin-batch.ts";
import { registerBuiltinUpdateCommand } from "./commands/builtin-update.ts";
import { registerCompletionCommand } from "./commands/completion.ts";
import { installMissingOptionExitHandlers } from "./commands/missing-option-hint.ts";
import { registerOperationsCommand } from "./commands/operations.ts";
import { commandNeedsMaterializedAuth } from "./auth/startup-auth.ts";

type CliOptions = GeneratedCommandOpts & CliOutputOptions & { readonly environment?: string };

/**
 * Emit a structured failure envelope on stdout AND a full stack on stderr,
 * then exit 1. Replaces the prior stderr-only fatal handler so MCP callers
 * always parse valid JSON from stdout regardless of crash kind.
 */
function writeFatalEnvelope(error: Error, kind: string): never {
  logError({ component: "aventure-cli", event: "fatal", message: error.message, error });
  process.stderr.write(`aventure-cli fatal (${kind}): ${error.stack ?? error.message}\n`);
  emitJson({
    ...failure(`aventure-cli ${kind}: ${error.message}`, [error.name || "Error"]),
    counts: { exitCode: 1 },
  });
  process.exit(1);
}

/** Root-help section heading for one top-level command; built-ins default to the CLI section. */
function commandSection(topLevelName: string) {
  return CLI_COMMAND_SECTION[CLI_NAMESPACE_SECTION[topLevelName] ?? "cli"];
}

function registerGeneratedOpenApiCommands(
  parent: Command,
  specs: readonly GeneratedCommandSpec[],
): void {
  // Commander renders help groups in first-registration order and commands in
  // registration order, so a stable (section rank, top-level name) sort shows
  // sections in CLI_COMMAND_SECTION rank order with alphabetical commands
  // inside, while leaf order within each namespace keeps the generated spec order.
  const ordered = specs
    .map((spec) => {
      const top = spec.cliPath[0] ?? "";
      return { spec, top, rank: commandSection(top).rank };
    })
    .toSorted((left, right) => left.rank - right.rank || left.top.localeCompare(right.top))
    .map((entry) => entry.spec);
  for (const spec of ordered) {
    registerLeaf(parent, spec, spec.cliPath);
    if (spec.cliAliasPath !== undefined && spec.cliAliasPath.join(" ") !== spec.cliPath.join(" ")) {
      registerLeaf(parent, spec, spec.cliAliasPath);
    }
  }
}

function registerLeaf(
  parent: Command,
  spec: GeneratedCommandSpec,
  cliPath: readonly string[],
): void {
  let current = parent;
  let namespacePath = "";
  for (const segment of cliPath.slice(0, -1)) {
    namespacePath = namespacePath === "" ? segment : `${namespacePath} ${segment}`;
    current = childCommand(current, segment, namespacePath);
  }
  const leafName = cliPath.at(-1) ?? spec.operationId;
  const leaf =
    current.commands.find((command) => command.name() === leafName) ?? current.command(leafName);
  leaf
    .summary(spec.summary || spec.operationId)
    .description(
      [
        `${spec.method} ${spec.path}.`,
        spec.description,
        spec.bodyKind === "json" ||
        [...spec.parameters, ...spec.bodyParameters].some((parameter) =>
          cliShellSensitiveSchema(parameter.schemaType, parameter.itemSchemaType),
        )
          ? CLI_SHELL_INPUT_GUIDANCE
          : "",
      ]
        .filter(Boolean)
        .join("\n"),
    );
  for (const parameter of spec.parameters) {
    addParameterOption(leaf, parameter);
  }
  addBodyOptions(leaf, spec);
  if (spec.dryRun) leaf.option("--execute", "send the request; default is dry-run", false);
  addOutputModeOptions(leaf);
  const positionalText = positionalTextParameter(spec);
  if (positionalText !== undefined) {
    leaf.argument(
      "[text...]",
      positionalText.description || `Same as ${longFlag(positionalText.flag)}.`,
    );
    leaf.action(async function (this: Command, text: readonly string[]) {
      const opts = this.optsWithGlobals<CliOptions>();
      const mode = resolveOutputMode(opts);
      const merged = withSearchText(positionalText, text, opts);
      return emit(
        { mode },
        merged.ok && merged.data !== null
          ? await runGeneratedCommand(spec, merged.data, mode)
          : merged,
      );
    });
    return;
  }
  leaf.action(async function (this: Command) {
    const opts = this.optsWithGlobals<CliOptions>();
    const mode = resolveOutputMode(opts);
    emit({ mode }, await runGeneratedCommand(spec, opts, mode));
  });
}

function positionalTextParameter(spec: GeneratedCommandSpec): GeneratedParameter | undefined {
  // A command whose only required input is a single string body field accepts it positionally.
  // Root-search leaves also accept their sole optional canonical query/search body string, so a
  // filterable list such as `search news` keeps the same casual grammar without endpoint facts.
  if (spec.parameters.some((parameter) => parameter.required)) return undefined;
  const requiredBody = spec.bodyParameters.filter((parameter) => parameter.required);
  if (requiredBody.length === 1 && requiredBody[0]?.schemaType === "string") {
    return requiredBody[0];
  }
  if (requiredBody.length !== 0 || spec.cliPath[0] !== "search") return undefined;
  const canonicalSearchText = spec.bodyParameters.filter((parameter) => {
    const leaf = parameter.name.split(".").at(-1);
    return parameter.schemaType === "string" && (leaf === "query" || leaf === "search");
  });
  return canonicalSearchText.length === 1 ? canonicalSearchText[0] : undefined;
}

function withSearchText(
  parameter: GeneratedParameter,
  text: readonly string[],
  opts: CliOptions,
): ResultEnvelope<CliOptions | null> {
  const value = text.join(" ").trim();
  if (value.length === 0) return success("No positional text", opts);
  if (opts[parameter.optionKey] !== undefined) {
    return failure(`Use either the positional argument or ${longFlag(parameter.flag)}, not both.`);
  }
  return success("Positional text parsed", { ...opts, [parameter.optionKey]: value });
}

function longFlag(flag: string): string {
  return flag.split(" ")[0] ?? flag;
}

function childCommand(parent: Command, segment: string, namespacePath: string): Command {
  const existing = parent.commands.find((command) => command.name() === segment);
  if (existing !== undefined) return existing;
  const entry = GENERATED_CLI_NAMESPACES[namespacePath];
  const cmd = parent.command(segment);
  if (entry !== undefined) cmd.summary(entry.summary).description(entry.summary);
  return cmd;
}

function addParameterOption(command: Command, parameter: GeneratedParameter): void {
  const description = parameter.description || `${parameter.name} ${parameter.location} parameter`;
  if (parameter.defaultValue !== undefined) {
    const defaultValue: string | boolean | string[] =
      typeof parameter.defaultValue === "string" || typeof parameter.defaultValue === "boolean"
        ? parameter.defaultValue
        : [...parameter.defaultValue];
    command.option(parameter.flag, description, defaultValue);
    return;
  }
  if (parameter.required) {
    command.requiredOption(parameter.flag, description);
    return;
  }
  command.option(parameter.flag, description);
}

async function runGeneratedCommand(
  spec: GeneratedCommandSpec,
  opts: CliOptions,
  mode: CliOutputMode,
): Promise<ResultEnvelope<unknown>> {
  if (opts.environment !== undefined) {
    const normalized = normalizeEnvironmentName(opts.environment);
    if (normalized === null) {
      return failure(`Unknown aVenture environment '${opts.environment}'`, [
        `Use one of: ${environmentNames().join(", ")}`,
      ]);
    }
    process.env.API_ENV = normalized;
  }
  const body = await readGeneratedBody(spec, opts);
  if (!body.ok) return body;
  const pathParams = Object.fromEntries(
    spec.parameters
      .filter((parameter) => parameter.location === "path")
      .map((parameter) => {
        const optionValue = opts[parameter.optionKey];
        if (Array.isArray(optionValue)) return [parameter.name, optionValue.at(0) ?? ""];
        if (optionValue === undefined)
          throw new Error(`Missing required option ${parameter.optionKey}`);
        return [parameter.name, String(optionValue)];
      }),
  );
  const searchParams = Object.fromEntries(
    spec.parameters
      .filter((parameter) => parameter.location === "query")
      .flatMap((parameter) => {
        const value = opts[parameter.optionKey];
        if (value === undefined || (Array.isArray(value) && value.length === 0)) return [];
        const searchValue =
          Array.isArray(value) || typeof value === "boolean" ? value : String(value);
        return [[parameter.name, searchValue]];
      }),
  );
  return await runOpenApiCall({
    method: spec.method,
    path: buildOpenApiPath(spec.operationId, pathParams),
    searchParams,
    body: body.data,
    auth: spec.auth,
    execute: spec.dryRun ? Boolean(opts.execute) : false,
    responseFormat: outputModeJsonAccept(mode) ? "json" : "auto",
  });
}

// Belt-and-suspenders: catch even errors that escape Commander's parseAsync.
process.on("uncaughtException", (error: Error) => writeFatalEnvelope(error, "uncaughtException"));
process.on("unhandledRejection", (reason: unknown) =>
  writeFatalEnvelope(
    reason instanceof Error ? reason : new Error(String(reason)),
    "unhandledRejection",
  ),
);

if (commandNeedsMaterializedAuth(process.argv.slice(2), GENERATED_OPENAPI_COMMAND_SPECS)) {
  await materializeAuth();
}
const generatedSpecs = visibleOpenApiCommandSpecsForCurrentAuth(GENERATED_OPENAPI_COMMAND_SPECS);
const program = new Command();
program
  .name("aventure-cli")
  .version(packageJson.version)
  .summary(
    "CLI for the aVenture API: read and maintain venture-research data — entities, people, funding, news, media, and search",
  )
  .description(
    [
      "CLI for the aVenture API: read and maintain venture-research data —",
      "entities, people, funding, news, media, and search.",
      "",
      "Runs generated aVenture API commands and prints clean text by default,",
      "or machine-readable --data / --json output when requested.",
      "Write-scope operations are dry-run by default; pass --execute to send the request.",
      "The aventure-mcp-server tools execute through this same CLI.",
    ].join("\n"),
  )
  .addOption(
    new Option(
      "--environment <environment>",
      "route all API calls to a mapped API environment (default: API_URL host, else API_ENV, else staging)",
    ).choices([...environmentNames()]),
  )
  .showHelpAfterError("(run `aventure-cli --help` for usage)");

registerGeneratedOpenApiCommands(program, generatedSpecs);
registerBuiltinAuthCommands(program);
registerBuiltinUpdateCommand(program);
registerBuiltinBatchCommand(program, generatedSpecs);
registerCompletionCommand(program, generatedSpecs);
registerOperationsCommand(program, generatedSpecs);
registerCuratedHelpCommand(program, generatedSpecs);
registerSearchParentModeOption(program, generatedSpecs);
// Commander groups help by first registration order, and the generated specs
// were registered in section-rank order above, so assigning each top-level
// command's section here yields sections in rank order with built-ins under
// the CLI section.
for (const command of program.commands) {
  if (!command.helpGroup()) command.helpGroup(commandSection(command.name()).heading);
}
installMissingOptionExitHandlers(program);

program.addHelpText(
  "after",
  [
    "",
    "Environment (credentials by command group):",
    "  CLIENT_SECRET   read commands (public data reads, search, lookups)",
    "  ADMIN_API_KEY   admin and write commands (mutations, media, jobs, harness)",
    "  AUTH_TOKEN      user/RBAC commands (Supabase bearer; never the client secret)",
    "  Check what this shell holds with: aventure-cli auth status",
    "",
    "Output modes (per command):",
    "  --text (compact; default on a terminal), --data (response data JSON; default when piped/non-TTY), --json (full envelope);",
    "  --data-full is uncapped, for bounded programmatic consumers only — never LLM agents.",
    "",
    "Exit codes:",
    "  0   envelope.ok === true",
    "  1   envelope.ok === false",
    "",
    "Examples:",
    "  $ aventure-cli auth status",
    "  $ aventure-cli entities get --entity-slug acme",
    "  $ bash -lc 'aventure-cli entities get --entity-slug acme'",
  ].join("\n"),
);

try {
  await program.parseAsync();
} catch (error) {
  writeFatalEnvelope(error instanceof Error ? error : new Error(String(error)), "parseAsync");
}
