/**
 * Curated `help` command shim, plus the generated failure contract on every leaf's `--help`.
 *
 * The generated command tree owns the grounded `help ask` leaf (projected from the Kotlin
 * `answerAgentHelpQuestion` owner). A user-registered `help` command suppresses and shadows
 * Commander's built-in help subcommand, which would otherwise lose `help <command>` dispatch, so
 * this shim reuses the generated `help` parent (never a second `help` registration) and gives it
 * two local behaviors:
 *
 *  - `help [command...]` prints the same local, deterministic text as `<command...> --help`.
 *  - `help --ask <question>` dispatches the generated grounded-help operation, resolved
 *    structurally from the generated specs — no operation ids, cli paths, routes, or schema facts
 *    authored here; without a qualifying generated leaf the flag is not registered.
 *
 * It also attaches the generated `Errors:` block to every generated leaf's `--help` — the same
 * block `command-catalog show` and `docs api` print, rendered by the one owner in
 * `operations-metadata`.
 *
 * `--help` everywhere stays local and deterministic.
 */
import type { Command } from "commander";
import { buildOpenApiPath, runOpenApiCall } from "../../api/openapi-call.ts";
import { failure, type ResultEnvelope } from "../../api/result-envelope.ts";
import type {
  OpenApiCommandParameter as GeneratedParameter,
  OpenApiCommandSpec as GeneratedCommandSpec,
} from "../../mcp-server/contract.ts";
import { emit } from "../output.ts";
import {
  addOutputModeOptions,
  outputModeJsonAccept,
  resolveOutputMode,
  type CliOutputMode,
  type CliOutputOptions,
} from "../output-mode.ts";
import { readGeneratedBody } from "./generated-body.ts";
import { errorBlock } from "./operations-metadata.ts";

type CuratedHelpOptions = CliOutputOptions & {
  readonly ask?: string;
  readonly environment?: string;
};

export function registerCuratedHelpCommand(
  program: Command,
  specs: readonly GeneratedCommandSpec[],
): void {
  // Explicitly disable the built-in help subcommand: a real `help` command already suppresses it
  // at dispatch, and this keeps the curated command authoritative if generation ever changes.
  program.helpCommand(false);
  const help =
    program.commands.find((command) => command.name() === "help") ?? program.command("help");
  help
    .summary("Show command help, or ask the platform a grounded question")
    .description(
      [
        "Show local --help output for a command path (deterministic, offline),",
        "or answer a natural-language platform question with --ask via the grounded",
        "help operation (the same generated operation as `help ask`).",
      ].join("\n"),
    )
    .argument("[command...]", "command path to show help for, e.g. `help search entities`");
  const grounded = groundedHelpSpec(specs);
  // The flag form of the generated `help ask` leaf; its description is the Kotlin-owned summary.
  if (grounded !== undefined) help.option("--ask <question>", grounded.summary);
  addOutputModeOptions(help);
  help.action(async function (this: Command, commandPath: readonly string[]) {
    const opts = this.optsWithGlobals<CuratedHelpOptions>();
    if (grounded !== undefined && opts.ask !== undefined) {
      const mode = resolveOutputMode(opts);
      if (commandPath.length > 0) {
        emit({ mode }, failure("Use either a command path or --ask, not both."));
        return;
      }
      emit({ mode }, await runGroundedHelp(grounded, opts.ask, opts.environment, mode));
      return;
    }
    const target = commandAtPath(program, commandPath);
    if (target === undefined) {
      this.error(
        `unknown command '${commandPath.join(" ")}' (run \`aventure-cli --help\` for the command tree)`,
      );
    }
    target.outputHelp();
  });
  installGeneratedErrorHelp(program, specs);
}

/**
 * Attaches the generated failure contract to every generated leaf's `--help`, so an agent that
 * reads help never has to also run `command-catalog show` to learn what the operation can return.
 */
function installGeneratedErrorHelp(program: Command, specs: readonly GeneratedCommandSpec[]): void {
  const documented = new Set<Command>();
  for (const spec of specs) {
    const block = errorBlock(spec.errorResponse);
    if (block.length === 0) continue;
    for (const path of [spec.cliPath, spec.cliAliasPath]) {
      const leaf = path === undefined ? undefined : commandAtPath(program, path);
      if (leaf === undefined || documented.has(leaf)) continue;
      documented.add(leaf);
      leaf.addHelpText("after", `\n${block.join("\n")}\n`);
    }
  }
}

/**
 * The sole generated single-question leaf under the curated help parent, when one exists. Derived
 * structurally (a two-segment `help` path taking one required text body) so no operation id, cli
 * path, or description is authored here; without such a leaf, `--ask` is not registered at all.
 */
function groundedHelpSpec(
  specs: readonly GeneratedCommandSpec[],
): GeneratedCommandSpec | undefined {
  const candidates = specs.filter((spec) => {
    const [root, leaf, extra] = spec.cliPath;
    return (
      root === "help" &&
      leaf !== undefined &&
      extra === undefined &&
      singleRequiredStringBodyParameter(spec) !== undefined
    );
  });
  const [sole, ...rest] = candidates;
  return rest.length === 0 ? sole : undefined;
}

function commandAtPath(program: Command, path: readonly string[]): Command | undefined {
  let current: Command = program;
  for (const segment of path) {
    const next = current.commands.find(
      (command) => command.name() === segment || command.aliases().includes(segment),
    );
    if (next === undefined) return undefined;
    current = next;
  }
  return current;
}

async function runGroundedHelp(
  spec: GeneratedCommandSpec,
  question: string,
  environment: string | undefined,
  mode: CliOutputMode,
): Promise<ResultEnvelope<unknown>> {
  const questionParameter = singleRequiredStringBodyParameter(spec);
  if (questionParameter === undefined) {
    return failure(
      `The \`${spec.cliPath.join(" ")}\` operation no longer takes a single required text body; run it directly instead of \`help --ask\`.`,
    );
  }
  // Root --environment is validated by its own choices() list; apply it like builtin-auth does.
  if (environment !== undefined) process.env.API_ENV = environment;
  const body = await readGeneratedBody(spec, { [questionParameter.optionKey]: question });
  if (!body.ok) return body;
  return await runOpenApiCall({
    method: spec.method,
    path: buildOpenApiPath(spec.operationId, {}),
    searchParams: {},
    body: body.data,
    auth: spec.auth,
    // The grounded help operation is read intent; never auto-execute a dry-run spec from here.
    execute: false,
    responseFormat: outputModeJsonAccept(mode) ? "json" : "auto",
  });
}

/** Mirrors the generated positional-text rule: one required string body field, no required params. */
function singleRequiredStringBodyParameter(
  spec: GeneratedCommandSpec,
): GeneratedParameter | undefined {
  if (spec.parameters.some((parameter) => parameter.required)) return undefined;
  const requiredBody = spec.bodyParameters.filter((parameter) => parameter.required);
  return requiredBody.length === 1 && requiredBody[0]?.schemaType === "string"
    ? requiredBody[0]
    : undefined;
}
