import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { success } from "../../api/result-envelope.ts";
import type { OpenApiCommandSpec } from "../../mcp-server/contract.ts";
import { visibleOpenApiCommandSpecs } from "../../mcp-server/contract-visibility.ts";
import { emit } from "../output.ts";
import type { CliOutputMode } from "../output-mode.ts";
import { GENERATED_OPENAPI_COMMAND_SPECS } from "../generated/openapi-commands.ts";
import {
  searchOperations,
  showOperation,
  type OperationFormat,
  type OperationMetadata,
  type OperationRenderOptions,
  type OperationCatalog,
  type OperationDetail,
} from "./operations-metadata.ts";

/** File name of the compact catalog written at build time and shipped in the published tarball. */
const COMPACT_CATALOG_FILE = "command-catalog.compact.txt";

/** Package-relative location of that shipped compact catalog. */
const COMPACT_CATALOG_PACKAGE_PATH = `dist/aventure-cli/${COMPACT_CATALOG_FILE}`;

/** Field separator for compact rows; one middle dot keeps a row narrow and still splittable. */
const COMPACT_FIELD_SEPARATOR = " · ";

/** Required-flag field for an operation that requires no flag. */
const COMPACT_NO_REQUIRED_FLAG = "-";

/**
 * Writes the shipped compact catalog into one built `dist/aventure-cli` directory, rendering the
 * same generated specs the runtime uses, projected the way a caller without an admin key sees them,
 * so the file and `command-catalog dump --format compact` agree byte for byte.
 */
export function writeCompactCatalog(outDir: string): void {
  const catalog = searchOperations(
    {},
    visibleOpenApiCommandSpecs(GENERATED_OPENAPI_COMMAND_SPECS, false),
  );
  const target = resolve(outDir, COMPACT_CATALOG_FILE);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, `${renderCatalog(catalog.data, "compact")}\n`);
}

/** Absolute path of the compact catalog shipped with this install, for offline `grep`. */
export function compactCatalogPath(): string {
  return resolve(
    packageRoot(dirname(fileURLToPath(import.meta.url))),
    COMPACT_CATALOG_PACKAGE_PATH,
  );
}

function packageRoot(from: string): string {
  let directory = from;
  for (;;) {
    if (existsSync(resolve(directory, "package.json"))) return directory;
    const parent = dirname(directory);
    if (parent === directory) {
      throw new Error(`No package.json above ${from}; aventure-cli is not in a package layout.`);
    }
    directory = parent;
  }
}

export function withQuery(
  opts: OperationRenderOptions,
  query: readonly string[],
): OperationRenderOptions {
  const positional = query.join(" ").trim();
  if (positional.length === 0) return opts;
  return { ...opts, q: opts.q === undefined ? positional : `${opts.q} ${positional}` };
}

export function writeSearchResult(
  opts: OperationRenderOptions,
  specs: readonly OpenApiCommandSpec[],
  mode: CliOutputMode,
): void {
  const result = searchOperations(opts, specs);
  if (!result.ok) {
    emit({ mode }, result);
    return;
  }
  writeOperationResult({
    opts,
    mode,
    data: result.data,
    defaultFormat: "lines",
    rendered: renderCatalog(result.data, resolveFormat(opts.format, "lines")),
    summary: "Generated operation matches",
  });
}

export function writeShowResult(
  opts: OperationRenderOptions,
  specs: readonly OpenApiCommandSpec[],
  mode: CliOutputMode,
): void {
  const result = showOperation(opts, specs);
  if (!result.ok || result.data === null) {
    emit({ mode }, result);
    return;
  }
  writeOperationResult({
    opts,
    mode,
    data: result.data,
    defaultFormat: "usage",
    rendered: renderDetail(result.data, resolveFormat(opts.format, "usage")),
    summary: "Generated operation detail",
  });
}

function writeOperationResult(input: {
  readonly opts: OperationRenderOptions;
  readonly mode: CliOutputMode;
  readonly data: OperationCatalog | OperationDetail;
  readonly defaultFormat: OperationFormat;
  readonly rendered: string;
  readonly summary: string;
}): void {
  const mode = input.mode;
  const withTerminator = input.rendered.endsWith("\n") ? input.rendered : `${input.rendered}\n`;
  if (input.opts.output !== undefined) {
    writeFileSync(input.opts.output, withTerminator);
    emit(
      { mode },
      success(
        input.summary,
        {
          outputPath: input.opts.output,
          byteLength: Buffer.byteLength(withTerminator, "utf8"),
          format: resolveFormat(input.opts.format, input.defaultFormat),
        },
        { counts: resultCounts(input.data) },
      ),
    );
    return;
  }
  if (mode === "text") {
    process.stdout.write(withTerminator);
    return;
  }
  emit({ mode }, success(input.summary, input.data, { counts: resultCounts(input.data) }));
}

function resolveFormat(
  value: OperationFormat | undefined,
  fallback: OperationFormat,
): OperationFormat {
  return value ?? fallback;
}

function renderCatalog(data: OperationCatalog, format: OperationFormat): string {
  if (format === "json") return JSON.stringify(data, null, 2);
  if (format === "ndjson")
    return data.operation.map((operation) => JSON.stringify(operation)).join("\n");
  if (format === "text") return renderTextRows(data.operation);
  if (format === "compact") return data.operation.map(compactLineForOperation).join("\n");
  return data.operation.map(lineForOperation).join("\n");
}

function renderDetail(data: OperationDetail, format: OperationFormat): string {
  if (format === "json") return JSON.stringify(data, null, 2);
  if (format === "ndjson") return JSON.stringify(data.operation);
  if (format === "lines") return lineForOperation(data.operation);
  if (format === "compact") return compactLineForOperation(data.operation);
  return data.usage;
}

function compactLineForOperation(operation: OperationMetadata): string {
  const requiredFlags = requiredFlagNames(operation);
  return [
    operation.cli.command,
    operation.summary,
    requiredFlags.length === 0 ? COMPACT_NO_REQUIRED_FLAG : requiredFlags.join(" "),
  ].join(COMPACT_FIELD_SEPARATOR);
}

function requiredFlagNames(operation: OperationMetadata): readonly string[] {
  return operation.flags.filter((flag) => flag.required).map((flag) => flag.name);
}

function renderTextRows(operations: readonly OperationMetadata[]): string {
  return operations
    .map((operation) => `${operation.cli.command}\n  ${lineForOperation(operation)}`)
    .join("\n");
}

function lineForOperation(operation: OperationMetadata): string {
  const requiredFlags = requiredFlagNames(operation);
  return [
    lineField("operationId", operation.operationId),
    lineField("scope", operation.scope),
    lineField("mutates", String(operation.mutates)),
    lineField("destructive", String(operation.destructive)),
    lineField("intent", operation.intent),
    lineField("resource", operation.resource),
    lineField("cli", operation.cli.command),
    operation.cli.alias === null ? "" : lineField("alias", operation.cli.alias),
    lineField("mcpTool", operation.mcpTool),
    lineField("method", operation.method),
    lineField("path", operation.path),
    lineField("auth", operation.auth),
    lineField("dryRunSupported", String(operation.dryRunSupported)),
    lineField("flags", operation.flags.map((flag) => flag.name).join(" ")),
    lineField("requiredFlags", requiredFlags.join(" ")),
    lineField("bodyKind", operation.body.kind ?? ""),
    lineField("bodyRequired", String(operation.body.required)),
    lineField("summary", operation.summary),
  ]
    .filter((part) => part.length > 0)
    .join(" ");
}

function lineField(name: string, value: string): string {
  return value.length === 0 ? "" : `${name}=${JSON.stringify(value)}`;
}

function resultCounts(data: OperationCatalog | OperationDetail): Record<string, number> {
  if ("count" in data) return data.count;
  return { returned: 1 };
}
