import { Command, Option } from "commander";
import { aventureMethod } from "../../api/client.ts";
import { resolveOpenApiOperationSelector } from "../../api/openapi-call.ts";
import { OPENAPI_METHODS } from "../../api/openapi-document.ts";
import { failure, success, type ResultEnvelope } from "../../api/result-envelope.ts";
import type { OpenApiCommandSpec } from "../../mcp-server/contract.ts";
import { emit } from "../output.ts";
import { addOutputModeOptions, resolveOutputMode } from "../output-mode.ts";
import {
  compactCatalogPath,
  withQuery,
  writeSearchResult,
  writeShowResult,
} from "./operations-catalog.ts";
import type { OperationRenderOptions } from "./operations-metadata.ts";
import {
  buildUnifiedOperations,
  unifiedOperationsJson,
  writeUnifiedOperationsJson,
} from "./unified-operations.ts";

const ROOT_FILTER_HELP = "Match only the first canonical or CLI-alias command segment";

export function registerOperationsCommand(
  parent: Command,
  specs: readonly OpenApiCommandSpec[],
): void {
  registerDocsCommand(parent, specs);
  const catalog = parent
    .command("command-catalog")
    .summary("LLM agent only: search generated CLI metadata")
    .description(
      [
        "LLM agent only: search and dump generated aventure-cli command metadata.",
        "This is read-only command metadata derived from the generated OpenAPI command specs.",
        "Use --format lines for rg/grep/ag/ack and --format ndjson|json for ast-grep/sg/parsers.",
        "Use --format compact for one `cli · summary · requiredFlags` row per operation.",
      ].join("\n"),
    );
  catalog.addHelpText(
    "after",
    () =>
      `\nShipped compact catalog, greppable without running this CLI:\n  ${compactCatalogPath()}\n`,
  );

  addSearchCommand(catalog, specs);
  addShowCommand(catalog, specs);
  addDumpCommand(catalog, specs);
  addUnifiedCommand(catalog);
}

function addSearchCommand(parent: Command, specs: readonly OpenApiCommandSpec[]): void {
  const command = parent
    .command("search")
    .summary("Search generated operations")
    .description("Search generated operation metadata without calling the API.")
    .argument("[query...]", "Search query; same as --q.")
    .option("--q <query>", "Search generated command metadata")
    .option("--root <root>", ROOT_FILTER_HELP)
    .addOption(
      new Option("--scope <scope>", "Filter by required auth scope")
        .choices(["read", "write", "all"])
        .default("all"),
    )
    .addOption(
      new Option("--mutates <mutates>", "Filter mutating operations")
        .choices(["true", "false", "any"])
        .default("any"),
    )
    .addOption(
      new Option("--destructive <destructive>", "Filter destructive operations")
        .choices(["true", "false", "any"])
        .default("any"),
    )
    .addOption(
      new Option("--intent <intent>", "Filter by operation intent")
        .choices(["read", "lookup", "search", "write", "delete", "status", "all"])
        .default("all"),
    )
    .addOption(
      new Option("--method <method>", "Filter by HTTP method")
        .choices(["GET", "POST", "PUT", "PATCH", "DELETE", "all"])
        .default("all"),
    )
    .option("--limit <count>", "Maximum rows to return", "20")
    .addOption(
      new Option("--format <format>", "Text/file render format")
        .choices(["text", "lines", "compact", "json", "ndjson"])
        .default("lines"),
    )
    .option("--output <path>", "Write rendered output to a file");
  addOutputModeOptions(command);
  command.action(function (this: Command, query: readonly string[]) {
    const opts = this.optsWithGlobals<OperationRenderOptions>();
    writeSearchResult(withQuery(opts, query), specs, resolveOutputMode(opts, "text"));
  });
}

/**
 * `docs api <selector>` — the terminal-native docs lookup. A third selector onto the same
 * `show` rendering, so no second renderer exists; only the selector grammar is new.
 */
function registerDocsCommand(parent: Command, specs: readonly OpenApiCommandSpec[]): void {
  const api = parent
    .command("docs")
    .summary("Look up generated API documentation offline")
    .description("Print generated operation documentation without calling the API.")
    .command("api")
    .summary("Show documentation for one operation")
    .description(
      [
        "Print one operation's summary, description, flags, example, and error contract.",
        "Select it by `<METHOD> <path>` (route template or concrete path), by operationId,",
        'or by CLI command path, e.g. "entities get".',
      ].join("\n"),
    )
    .argument("<selector...>", "METHOD and path, an operationId, or a CLI command path");
  addOutputModeOptions(api);
  api.action(function (this: Command, selector: readonly string[]) {
    const opts = this.optsWithGlobals<OperationRenderOptions>();
    const mode = resolveOutputMode(opts);
    const resolved = docsSelector(selector, specs);
    if (!resolved.ok || resolved.data === null) {
      emit({ mode }, resolved);
      return;
    }
    writeShowResult({ ...opts, ...resolved.data }, specs, mode);
  });
}

/** The one statement of what `docs api` accepts; every rejection repeats it verbatim. */
const DOCS_SELECTOR_FORM =
  'Accepted selectors: `<METHOD> <route template or concrete path>`, an operationId, or a CLI command path such as "entities get".';

/** Maps the accepted `docs api` selector forms onto the `command-catalog show` options. */
function docsSelector(
  selector: readonly string[],
  specs: readonly OpenApiCommandSpec[],
): ResultEnvelope<Pick<OperationRenderOptions, "command" | "operationId"> | null> {
  const [head, ...rest] = selector;
  const openApiMethod = OPENAPI_METHODS.find((candidate) => candidate === head?.toLowerCase());
  if (openApiMethod === undefined || rest.length === 0) {
    const name = selector.join(" ").trim();
    return success(
      "Resolved by name",
      specs.some((spec) => spec.operationId === name) ? { operationId: name } : { command: name },
    );
  }
  const method = aventureMethod(openApiMethod);
  const path = rest.join("");
  // Route templates match a generated spec directly; only a concrete path needs the shared OpenAPI
  // resolver, which would otherwise reject an unsubstituted `{param}` segment.
  const template = specs.find((spec) => spec.method === method && spec.path === path);
  if (template !== undefined) {
    return success("Resolved by route template", { operationId: template.operationId });
  }
  const resolved = resolveOpenApiOperationSelector({ method, path });
  if (!resolved.ok || resolved.data === null) {
    return failure(resolved.summary, [...resolved.warnings, DOCS_SELECTOR_FORM]);
  }
  return success("Resolved by method and path", {
    operationId: resolved.data.operation.operationId,
  });
}

function addShowCommand(parent: Command, specs: readonly OpenApiCommandSpec[]): void {
  const command = parent
    .command("show")
    .summary("Show one generated operation")
    .description("Show one generated operation by command path or operationId.")
    .option("--command <command>", "CLI command path, with or without aventure-cli prefix")
    .option("--operation-id <operationId>", "Generated OpenAPI operationId")
    .addOption(
      new Option("--format <format>", "Text/file render format")
        .choices(["usage", "lines", "compact", "json", "ndjson"])
        .default("usage"),
    )
    .option("--output <path>", "Write rendered output to a file");
  addOutputModeOptions(command);
  command.action(function (this: Command) {
    const opts = this.optsWithGlobals<OperationRenderOptions>();
    writeShowResult(opts, specs, resolveOutputMode(opts, "text"));
  });
}

function addDumpCommand(parent: Command, specs: readonly OpenApiCommandSpec[]): void {
  const command = parent
    .command("dump")
    .summary("Dump generated operations")
    .description("Dump generated operations for rg/grep/ag/ack or JSON/NDJSON tooling.")
    .option("--root <root>", ROOT_FILTER_HELP)
    .addOption(
      new Option("--scope <scope>", "Filter by required auth scope")
        .choices(["read", "write", "all"])
        .default("all"),
    )
    .addOption(
      new Option("--mutates <mutates>", "Filter mutating operations")
        .choices(["true", "false", "any"])
        .default("any"),
    )
    .addOption(
      new Option("--destructive <destructive>", "Filter destructive operations")
        .choices(["true", "false", "any"])
        .default("any"),
    )
    .addOption(
      new Option("--intent <intent>", "Filter by operation intent")
        .choices(["read", "lookup", "search", "write", "delete", "status", "all"])
        .default("all"),
    )
    .addOption(
      new Option("--method <method>", "Filter by HTTP method")
        .choices(["GET", "POST", "PUT", "PATCH", "DELETE", "all"])
        .default("all"),
    )
    .option("--limit <count>", "Maximum rows to return")
    .addOption(
      new Option("--format <format>", "Text/file render format")
        .choices(["text", "lines", "compact", "json", "ndjson"])
        .default("lines"),
    )
    .option("--output <path>", "Write rendered output to a file");
  addOutputModeOptions(command);
  command.action(function (this: Command) {
    const opts = this.optsWithGlobals<OperationRenderOptions>();
    writeSearchResult(opts, specs, resolveOutputMode(opts, "text"));
  });
}

function addUnifiedCommand(parent: Command): void {
  const command = parent
    .command("unified")
    .summary("Dump unified CLI/API/MCP operation JSON")
    .description("Dump the flat unified operations JSON projected from MCP_GENERATION_CONTRACT.")
    .option("--output <path>", "Write unified operations JSON to a file");
  addOutputModeOptions(command);
  command.action(function (this: Command) {
    const opts = this.optsWithGlobals<OperationRenderOptions>();
    const mode = resolveOutputMode(opts, "text");
    const payload = buildUnifiedOperations();
    if (opts.output !== undefined) {
      const result = writeUnifiedOperationsJson(opts.output, payload);
      emit(
        { mode },
        success(
          "Unified operations JSON written",
          {
            outputPath: result.target,
            byteLength: result.byteLength,
            schemaVersion: payload.schemaVersion,
          },
          { counts: { totalOperations: result.totalOperations } },
        ),
      );
      return;
    }
    if (mode === "text") {
      process.stdout.write(unifiedOperationsJson(payload));
      return;
    }
    emit(
      { mode },
      success("Unified operations JSON", payload, {
        counts: { totalOperations: payload.totalOperations },
      }),
    );
  });
}
