import { HTTP_FORBIDDEN, HTTP_UNAUTHORIZED } from "@aventurevc/api-schemas/client/http/status-code";
import {
  PersonalApiKeySchema,
  type PersonalApiKey,
} from "@aventurevc/api-schemas/personal/api-key";

import { aventureRequest, type AventureResponse } from "../../api/client.ts";
import { readEnv } from "../../api/env.ts";
import { buildOpenApiPath } from "../../api/openapi-call.ts";
import { normalizeCliApiEnvironment } from "./api-target.ts";
import { credentialSafeMessage, credentialSafeProblemSummary } from "./credential-redaction.ts";

export type CredentialVerification =
  | {
      readonly state: "verified";
      readonly summary: string;
      readonly apiKey: PersonalApiKey;
    }
  | {
      readonly state: "invalid" | "unavailable";
      readonly summary: string;
    };

/** Verify the broker-delivered key before it is persisted or acknowledged. */
export async function verifyPersonalCredentialAccess(
  secret: string,
): Promise<CredentialVerification> {
  const environment = normalizeCliApiEnvironment(readEnv());
  let response: AventureResponse<PersonalApiKey>;
  try {
    response = await aventureRequest(
      environment,
      {
        method: "GET",
        path: buildOpenApiPath("getCurrentPersonalApiKey", {}),
        headers: { Authorization: `Bearer ${secret}` },
      },
      PersonalApiKeySchema,
    );
  } catch (error) {
    return {
      state: "unavailable",
      summary: `identity verification failed before an HTTP response — ${credentialSafeMessage(error, [secret])}`,
    };
  }
  if (!response.ok) {
    const state =
      response.problem.status === HTTP_UNAUTHORIZED || response.problem.status === HTTP_FORBIDDEN
        ? "invalid"
        : "unavailable";
    return {
      state,
      summary: `identity verification: ${credentialSafeProblemSummary(response.problem, [secret])}`,
    };
  }
  if (response.data.status !== "ACTIVE") {
    return { state: "invalid", summary: "personal API-key self metadata is not active" };
  }
  return {
    state: "verified",
    summary: "personal API-key metadata verified",
    apiKey: response.data,
  };
}
