import type { JsonValue } from "@aventurevc/api-schemas/http/json-value";
import { failure, success, type ResultEnvelope } from "../../api/result-envelope.ts";
import type { OpenApiCommandSpec as GeneratedCommandSpec } from "../../mcp-server/contract.ts";

export type JsonBody = { [key: string]: JsonValue };

export function requiredBodyFilePath(spec: GeneratedCommandSpec): readonly string[] {
  const directPath = new Set((spec.bodyParameters ?? []).map(({ name }) => name));
  if (spec.bodyKind === "multipart") return spec.bodyRequiredPath;
  return spec.bodyRequiredPath.filter((path) => !directPath.has(path));
}

export function assignBodyParameter(
  body: JsonBody,
  parameterName: string,
  value: JsonValue,
): ResultEnvelope<null> {
  if (!isArrayItemPath(parameterName) || !Array.isArray(value)) {
    return assignBodyPath(body, parameterName, value);
  }
  for (const [index, entry] of value.entries()) {
    const assigned = assignBodyPath(body, parameterName, entry, index);
    if (!assigned.ok) return assigned;
  }
  return success("Body value assigned", null);
}

export function hasBodyPath(body: JsonBody, parameterName: string): boolean {
  return hasJsonPath(body, parameterName.split("."));
}

function hasJsonPath(current: JsonValue, rawPath: readonly string[]): boolean {
  const [rawPart, ...remaining] = rawPath;
  if (rawPart === undefined) return true;
  const segment = parsePathSegment(rawPart);
  if (!isJsonBody(current) || !Object.hasOwn(current, segment.key)) return false;
  const next: JsonValue = current[segment.key] ?? null;
  if (!segment.isArray) return hasJsonPath(next, remaining);
  return Array.isArray(next) && next.every((entry) => hasJsonPath(entry, remaining));
}

export function isArrayItemPath(parameterName: string): boolean {
  return parameterName.split(".").some((part) => parsePathSegment(part).isArray);
}

export function firstArrayItemPath(
  bodyParameters: readonly { readonly name: string }[],
): string | undefined {
  return bodyParameters.find((parameter) => isArrayItemPath(parameter.name))?.name;
}

export type UnknownBodyFilePath = {
  readonly path: string;
  readonly suggestion?: { readonly path: string; readonly flag: string };
};

export function unknownBodyFilePath(
  spec: GeneratedCommandSpec,
  body: JsonValue | undefined,
): UnknownBodyFilePath | null {
  if ((spec.bodyParameters?.length ?? 0) === 0 || !isJsonBody(body)) return null;
  const index = bodyPathIndex(spec.bodyParameters);
  return findUnknownBodyFilePath(body, [], index);
}

export function isJsonBody(value: JsonValue | undefined): value is JsonBody {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function assignBodyPath(
  body: JsonBody,
  parameterName: string,
  value: JsonValue,
  arrayIndex = 0,
): ResultEnvelope<null> {
  const path = parameterName.split(".");
  let target: JsonBody = body;
  for (const [index, rawPart] of path.entries()) {
    const segment = parsePathSegment(rawPart);
    const isLeaf = index === path.length - 1;
    const next = stepIntoPathSegment(target, segment, parameterName, isLeaf, value, arrayIndex);
    if (!next.ok || next.data === null) return failure(next.summary, next.warnings);
    if (isLeaf) return success("Body value assigned", null);
    target = next.data;
  }
  return failure(`${parameterName} is not a valid body option path.`);
}

function stepIntoPathSegment(
  target: JsonBody,
  segment: PathSegment,
  parameterName: string,
  isLeaf: boolean,
  value: JsonValue,
  arrayIndex: number,
): ResultEnvelope<JsonBody | null> {
  const collision = (): ResultEnvelope<JsonBody | null> =>
    failure(`${parameterName} cannot be combined with another body option at ${segment.key}.`);
  const existing = target[segment.key];
  if (segment.isArray) {
    if (existing !== undefined && !Array.isArray(existing)) return collision();
    const array: JsonValue[] = existing ?? [];
    if (existing === undefined) target[segment.key] = array;
    if (isLeaf) {
      if (array[arrayIndex] !== undefined) return collision();
      array[arrayIndex] = value;
      return success("Body value assigned", target);
    }
    const entry = array[arrayIndex];
    if (entry === undefined) {
      const created: JsonBody = {};
      array[arrayIndex] = created;
      return success("Body path created", created);
    }
    if (isJsonBody(entry)) return success("Body path stepped", entry);
    return collision();
  }
  if (isLeaf) {
    if (existing !== undefined) return collision();
    target[segment.key] = value;
    return success("Body value assigned", target);
  }
  if (existing === undefined) {
    const created: JsonBody = {};
    target[segment.key] = created;
    return success("Body path created", created);
  }
  if (isJsonBody(existing)) return success("Body path stepped", existing);
  return collision();
}

type PathSegment = { readonly key: string; readonly isArray: boolean };

function parsePathSegment(rawPart: string): PathSegment {
  const isArray = rawPart.endsWith("[]");
  return { key: isArray ? rawPart.slice(0, -2) : rawPart, isArray };
}

type BodyPathIndex = {
  readonly leaf: ReadonlySet<string>;
  readonly prefix: ReadonlySet<string>;
  readonly flagByLeaf: ReadonlyMap<string, string>;
};

function bodyPathIndex(parameters: GeneratedCommandSpec["bodyParameters"]): BodyPathIndex {
  const leaf = new Set<string>();
  const prefix = new Set<string>();
  const flagByLeaf = new Map<string, string>();
  for (const parameter of parameters) {
    const path = `${parameter.name}${parameter.schemaType === "array" ? "[]" : ""}`;
    leaf.add(path);
    flagByLeaf.set(path, parameter.flag.split(" ")[0] ?? parameter.name);
    const segments = path.split(".");
    for (let index = 1; index < segments.length; index += 1) {
      prefix.add(segments.slice(0, index).join("."));
    }
  }
  return { leaf, prefix, flagByLeaf };
}

function findUnknownBodyFilePath(
  value: JsonValue,
  path: readonly string[],
  index: BodyPathIndex,
): UnknownBodyFilePath | null {
  if (Array.isArray(value)) {
    if (value.length === 0) return null;
    for (const entry of value) {
      const unknown = findUnknownBodyFilePath(entry, path, index);
      if (unknown !== null) return unknown;
    }
    return null;
  }
  if (!isJsonBody(value)) return null;
  for (const [key, child] of Object.entries(value)) {
    const next = [...path, Array.isArray(child) ? `${key}[]` : key];
    const nextPath = next.join(".");
    if (!knownBodyPath(nextPath, index)) {
      if (!insideGeneratedArrayObject(next)) continue;
      return { path: nextPath, suggestion: closestBodyPath(next, index) };
    }
    const unknown = findUnknownBodyFilePath(child, next, index);
    if (unknown !== null) return unknown;
  }
  return null;
}

function knownBodyPath(path: string, index: BodyPathIndex): boolean {
  return index.prefix.has(path) || index.leaf.has(path);
}

function insideGeneratedArrayObject(path: readonly string[]): boolean {
  return path.slice(0, -1).some((segment) => segment.endsWith("[]"));
}

function closestBodyPath(
  path: readonly string[],
  index: BodyPathIndex,
): { readonly path: string; readonly flag: string } | undefined {
  const parent = path.slice(0, -1).join(".");
  const leaf = path.at(-1)?.replace(/\[\]$/u, "").toLowerCase() ?? "";
  const candidates = [...index.leaf].filter((candidate) => {
    const segments = candidate.split(".");
    return segments.slice(0, -1).join(".") === parent;
  });
  const scored = candidates
    .map((candidate) => ({
      path: candidate,
      score: leafSimilarity(leaf, candidate.split(".").at(-1) ?? ""),
    }))
    .filter(({ score }) => score < Number.POSITIVE_INFINITY)
    .toSorted((left, right) => left.score - right.score || left.path.localeCompare(right.path));
  const [best] = scored;
  if (best === undefined) return undefined;
  return { path: best.path, flag: index.flagByLeaf.get(best.path) ?? best.path };
}

function leafSimilarity(leaf: string, candidateLeaf: string): number {
  const candidate = candidateLeaf.replace(/\[\]$/u, "").toLowerCase();
  if (candidate === leaf) return 0;
  if (candidate.endsWith(leaf) || leaf.endsWith(candidate)) return 1;
  if (candidate.includes(leaf) || leaf.includes(candidate)) return 2;
  return Number.POSITIVE_INFINITY;
}
