import { HTTP_UNAUTHORIZED } from "@aventurevc/api-schemas/client/http/status-code";
import { PersonalApiKeySchema } from "@aventurevc/api-schemas/personal/api-key";

import { aventureRequest } from "../../api/client.ts";
import { readEnv } from "../../api/env.ts";
import { buildOpenApiTemplatePath } from "../../api/openapi-document.ts";
import { failure, success, type ResultEnvelope } from "../../api/result-envelope.ts";
import { openApiCompositeSpec } from "../../mcp-server/contract.ts";
import { GENERATED_OPENAPI_COMPOSITE_SPECS } from "../generated/openapi-composites.ts";
import { normalizeCliApiEnvironment } from "./api-target.ts";
import { credentialSafeMessage, credentialSafeProblemSummary } from "./credential-redaction.ts";
import {
  canonicalPersonalCredentialHost,
  forgetPersonalCredential,
  loadPersonalCredential,
  type StoredPersonalCredential,
} from "./personal-credential.ts";

const REVOKE_PERSONAL_CREDENTIAL = openApiCompositeSpec(
  GENERATED_OPENAPI_COMPOSITE_SPECS,
  "revoke",
);

export interface PersonalLogoutOptions {
  readonly forgetLocal: boolean;
}

/** Revoke the exact stored key remotely before removing its local keyring entry. */
export async function logoutPersonalCredential(
  options: PersonalLogoutOptions,
): Promise<ResultEnvelope<unknown>> {
  let host: string;
  try {
    host = canonicalPersonalCredentialHost(readEnv().host);
  } catch (error) {
    return failure(`auth logout: invalid API host — ${credentialSafeMessage(error)}`);
  }
  let lookup: Awaited<ReturnType<typeof loadPersonalCredential>>;
  try {
    lookup = await loadPersonalCredential(host);
  } catch (error) {
    return failure(
      `auth logout: stored credential could not be read — ${credentialSafeMessage(error)}`,
    );
  }
  if (lookup.state === "unavailable") return failure(`auth logout: ${lookup.summary}`);
  if (lookup.state === "missing") {
    return success("No personal CLI credential is stored for this API host.", {
      host,
      revoked: false,
      forgotten: false,
    });
  }
  const stored = lookup.stored;
  const revocation = await revokeStoredCredential(stored);
  const revoked = revocation.outcome === "revoked";
  // A pending record can never activate (the poll secret is not persisted) and its remote key
  // outlives the authorization deadline only after acknowledgment, so an authentication
  // rejection proves the remote key is inert and local bytes are safe to remove.
  const pendingKeyInert = stored.activation === "pending" && revocation.outcome === "rejected";
  if (!revoked && !pendingKeyInert && !options.forgetLocal) {
    return {
      ...failure(
        `auth logout: remote revocation was not confirmed; local credential preserved — ${revocation.summary}`,
        [
          "Retry when the API is available. If an earlier response was lost after revocation, the retry can be unauthorized because revoked keys cannot authenticate.",
          "Use `--forget-local` only to remove local bytes while accepting that the remote key may remain active.",
        ],
      ),
      data: logoutDiagnostics(stored, false, false),
    };
  }

  try {
    await forgetPersonalCredential(stored.host);
  } catch (error) {
    return {
      ...failure(
        `auth logout: local credential removal failed — ${credentialSafeMessage(error, [stored.credential.secret])}`,
        [
          revoked
            ? "The remote key is revoked. Re-run with `--forget-local` to retry local cleanup."
            : "Remote revocation was not confirmed; inspect auth status before retrying.",
        ],
      ),
      data: logoutDiagnostics(stored, revoked, false),
    };
  }

  return success(
    revoked
      ? "Personal CLI credential revoked remotely and removed locally."
      : pendingKeyInert
        ? "Stale pending CLI credential removed; its remote key can no longer authenticate and unacknowledged keys expire at the authorization deadline."
        : "Personal CLI credential removed locally without confirmed remote revocation.",
    logoutDiagnostics(stored, revoked, true),
    {
      ids: [stored.credential.apiKey.id],
      warnings:
        revoked || pendingKeyInert
          ? []
          : ["Remote revocation was not confirmed; the personal key may remain active."],
    },
  );
}

/**
 * Self-revocation classified by what the API proved: "revoked" confirms the exact stored Clerk key
 * identity, "rejected" means the API affirmatively refused the stored secret's authentication, and
 * "unconfirmed" covers every outcome-unknown failure.
 */
export interface PersonalCredentialRevocation {
  readonly outcome: "revoked" | "rejected" | "unconfirmed";
  readonly summary: string;
}

export async function revokeStoredCredential(
  stored: StoredPersonalCredential,
): Promise<PersonalCredentialRevocation> {
  const environment = normalizeCliApiEnvironment(readEnv());
  try {
    const response = await aventureRequest(
      environment,
      {
        method: REVOKE_PERSONAL_CREDENTIAL.method,
        path: buildOpenApiTemplatePath(
          REVOKE_PERSONAL_CREDENTIAL.path,
          {},
          REVOKE_PERSONAL_CREDENTIAL.operationId,
        ),
        headers: { Authorization: `Bearer ${stored.credential.secret}` },
      },
      PersonalApiKeySchema,
    );
    if (!response.ok) {
      // Only an API-authored 401 (a typed RFC 9457 problem) proves the stored secret can no
      // longer authenticate. An intermediary block page parses to type "about:blank" and stays
      // outcome-unknown, and a 403 means the key authenticated but was refused.
      const rejected =
        response.problem.status === HTTP_UNAUTHORIZED && response.problem.type !== "about:blank";
      return {
        outcome: rejected ? "rejected" : "unconfirmed",
        summary: credentialSafeProblemSummary(response.problem, [stored.credential.secret]),
      };
    }
    if (
      response.data.id !== stored.credential.apiKey.id ||
      response.data.subject !== stored.credential.apiKey.subject
    ) {
      return {
        outcome: "unconfirmed",
        summary: "remote response did not match the stored personal key identity",
      };
    }
    return response.data.status === "REVOKED"
      ? { outcome: "revoked", summary: "remote key revocation confirmed" }
      : { outcome: "unconfirmed", summary: "remote response did not confirm REVOKED status" };
  } catch (error) {
    return {
      outcome: "unconfirmed",
      summary: credentialSafeMessage(error, [stored.credential.secret]),
    };
  }
}

function logoutDiagnostics(stored: StoredPersonalCredential, revoked: boolean, forgotten: boolean) {
  return {
    host: stored.host,
    personalApiKeyId: stored.credential.apiKey.id,
    activation: stored.activation,
    revoked,
    forgotten,
  };
}
