/**
 * NDJSON, checkpoint, and option-parsing primitives for `aventure-cli batch`.
 *
 * Pure infrastructure for `builtin-batch.ts` — no endpoint knowledge and no
 * network calls ([MCP1b.1]); the generated OpenAPI command specs remain the
 * only contract source. Checkpoints bind to the exact input file bytes and
 * chunk size so a resume can never replay against reordered or edited rows.
 */
import { createHash } from "node:crypto";
import { existsSync, readFileSync, writeFileSync } from "node:fs";

import { JsonValueSchema, type JsonValue } from "@aventurevc/api-schemas/http/json-value";
import { failure, success, type ResultEnvelope } from "../../api/result-envelope.ts";
import type { OpenApiCommandSpec } from "../../mcp-server/contract.ts";
import { normalizeCommand } from "./operations-metadata.ts";

export type BatchCheckpoint = {
  readonly inputDigest: string;
  readonly chunkSize: number;
  readonly completedChunk: readonly number[];
};

export type NdjsonInput = {
  readonly row: readonly JsonValue[];
  readonly digest: string;
};

export const MAX_BATCH_CONCURRENCY = 8;

export function resolveSpec(
  specs: readonly OpenApiCommandSpec[],
  commandText: string,
): ResultEnvelope<OpenApiCommandSpec | null> {
  const normalized = normalizeCommand(commandText);
  const match = specs.find(
    (spec) =>
      spec.cliPath.join(" ") === normalized ||
      spec.cliAliasPath?.join(" ") === normalized ||
      spec.operationId === normalized,
  );
  if (match === undefined) {
    return failure(`No generated operation matches "${commandText}"`, [
      'Resolve the exact command with `aventure-cli command-catalog search "<query>"`.',
    ]);
  }
  return success(`Resolved ${match.operationId}`, match);
}

export function guardPathParameterFree(spec: OpenApiCommandSpec): ResultEnvelope<null> {
  if (spec.parameters.some((parameter) => parameter.location === "path")) {
    return failure(`${spec.operationId} has path parameters and cannot be batch-driven`, [
      spec.path,
    ]);
  }
  return success("no path parameters", null);
}

export function parseQueryOptions(
  values: readonly string[],
): ResultEnvelope<Record<string, string> | null> {
  const query: Record<string, string> = {};
  for (const value of values) {
    const separator = value.indexOf("=");
    if (separator <= 0) return failure(`--query expects key=value, got "${value}"`);
    query[value.slice(0, separator)] = value.slice(separator + 1);
  }
  return success("query parsed", query);
}

export function parseBoundedInt(
  name: string,
  raw: string,
  min: number,
  max: number,
): ResultEnvelope<number | null> {
  const value = Number(raw);
  if (!Number.isInteger(value) || value < min || value > max) {
    return failure(`${name} must be an integer between ${min} and ${max}, got "${raw}"`);
  }
  return success(`${name} parsed`, value);
}

/** Parse once at the trust boundary; everything downstream walks typed JsonValue. */
export function toJsonValue(value: unknown): JsonValue | undefined {
  const parsed = JsonValueSchema.safeParse(value);
  return parsed.success ? parsed.data : undefined;
}

export function pathValue(value: unknown, path: string): JsonValue | undefined {
  let cursor: JsonValue | undefined = toJsonValue(value);
  for (const segment of path.split(".")) {
    if (typeof cursor !== "object" || cursor === null || Array.isArray(cursor)) return undefined;
    cursor = cursor[segment];
  }
  return cursor;
}

export function asJsonRecord(value: unknown): Record<string, JsonValue> | null {
  const parsed = toJsonValue(value);
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) return null;
  return parsed;
}

/**
 * Unwrap the OpenAPI runner's call-result wrapper down to the response payload.
 * The wrapper itself may carry `undefined`-valued fields, so narrow to
 * `response` BEFORE parsing; only the response body is guaranteed pure JSON.
 */
export function responsePayload(content: unknown): JsonValue | undefined {
  if (typeof content === "object" && content !== null && "response" in content) {
    return toJsonValue(content.response);
  }
  return toJsonValue(content);
}

export function chunkRows(row: readonly JsonValue[], chunkSize: number): JsonValue[][] {
  const chunkList: JsonValue[][] = [];
  for (let start = 0; start < row.length; start += chunkSize) {
    chunkList.push(row.slice(start, start + chunkSize));
  }
  return chunkList;
}

export function readNdjsonRows(path: string): ResultEnvelope<NdjsonInput | null> {
  if (!existsSync(path)) return failure(`--input file not found: ${path}`);
  const content = readFileSync(path, "utf8");
  const row: JsonValue[] = [];
  const lineList = content.split("\n");
  for (const [index, line] of lineList.entries()) {
    if (line.trim() === "") continue;
    const parsed = JsonValueSchema.safeParse(safeJsonParse(line));
    if (!parsed.success) {
      return failure(`--input line ${index + 1} is not valid JSON`, [line.slice(0, 120)]);
    }
    row.push(parsed.data);
  }
  if (row.length === 0) return failure(`--input has no NDJSON rows: ${path}`);
  return success("input parsed", { row, digest: sha256(content) });
}

export function readCheckpoint(
  path: string | undefined,
  inputDigest: string,
  chunkSize: number,
): ResultEnvelope<BatchCheckpoint | null> {
  const empty: BatchCheckpoint = { inputDigest, chunkSize, completedChunk: [] };
  if (path === undefined || !existsSync(path)) return success("no checkpoint", empty);
  const parsed = safeJsonParse(readFileSync(path, "utf8"));
  if (parsed === undefined) return failure(`--checkpoint file is not valid JSON: ${path}`);
  const digest = pathValue(parsed, "inputDigest");
  const storedChunkSize = pathValue(parsed, "chunkSize");
  const completedChunk = pathValue(parsed, "completedChunk");
  if (digest !== inputDigest || storedChunkSize !== chunkSize) {
    return failure(`--checkpoint ${path} was written for different input or chunk size`, [
      "Delete the checkpoint to start over, or restore the original input file.",
    ]);
  }
  if (!Array.isArray(completedChunk)) {
    return failure(`--checkpoint ${path} has an invalid completedChunk list`);
  }
  const completedList = completedChunk.filter((value): value is number => Number.isInteger(value));
  if (completedList.length !== completedChunk.length) {
    return failure(`--checkpoint ${path} has an invalid completedChunk list`);
  }
  return success("checkpoint loaded", { inputDigest, chunkSize, completedChunk: completedList });
}

export function writeCheckpoint(
  path: string | undefined,
  inputDigest: string,
  chunkSize: number,
  completed: ReadonlySet<number>,
): void {
  if (path === undefined) return;
  const checkpoint: BatchCheckpoint = {
    inputDigest,
    chunkSize,
    completedChunk: [...completed].toSorted((left, right) => left - right),
  };
  writeFileSync(path, `${JSON.stringify(checkpoint)}\n`);
}

export function collectRepeatable(value: string, previous: readonly string[]): string[] {
  return [...previous, value];
}

function safeJsonParse(content: string): unknown {
  try {
    return JSON.parse(content);
  } catch {
    return undefined;
  }
}

function sha256(content: string): string {
  return createHash("sha256").update(content).digest("hex");
}
