/**
 * Built-in (non-generated) zero-touch onboarding: `aventure-cli agents setup`.
 *
 * Sibling of `builtin-doctor.ts` — a local environment command with no API contract of its own, so
 * nothing to generate from a Kotlin `@Schema` owner. It reads the published instruction manifest
 * through the generated agent-instruction operations, then materializes the `aventure*` skill
 * bundle and the MCP server registration into whichever agent runtimes this user actually has on
 * disk. `agent-runtime.ts` owns those locations, so nothing outside a detected runtime's own
 * configuration directory is written.
 *
 * Dry-run by default per [MCP1e]: without `--execute` it reports the planned actions and writes
 * nothing. `--status` re-reads what is installed and exits 1 while any drift remains.
 */
import { existsSync } from "node:fs";
import { join } from "node:path";

import {
  AgentInstructionDetailSchema,
  type AgentInstructionDetail,
} from "@aventurevc/api-schemas/agent/instruction-detail";
import { AgentInstructionKindSchema } from "@aventurevc/api-schemas/agent/instruction-kind";
import {
  AgentInstructionManifestSchema,
  type AgentInstructionManifest,
} from "@aventurevc/api-schemas/agent/instruction-manifest";
import { Command, Option } from "commander";
import type { z } from "zod/v4";

import { readEnv } from "../../api/env.ts";
import { mcpServerUrlFromApiHost } from "../../api/mcp-server-url.ts";
import { buildOpenApiPath, runOpenApiCall } from "../../api/openapi-call.ts";
import { failure, success, type ResultEnvelope } from "../../api/result-envelope.ts";
import type { OpenApiCommandSpec } from "../../mcp-server/contract.ts";
import {
  AGENT_RUNTIME,
  MCP_SERVER_NAME,
  SKILL_ENTRY_FILE,
  SKILL_STATE_FILE,
  readSkillState,
  registerMcp,
  registeredMcpUrl,
  runtimeDetectPath,
  runtimeDetected,
  runtimeMcpConfig,
  runtimeSkillDir,
  skillStateFile,
  writeSkillDocument,
  writeSkillState,
  type AgentRuntime,
} from "../agent-runtime.ts";
import { credentialSafeMessage } from "../auth/credential-redaction.ts";
import { GENERATED_CLI_NAMESPACES } from "../generated/cli-namespaces.ts";
import { GENERATED_OPENAPI_COMMAND_SPECS } from "../generated/openapi-commands.ts";
import { emit } from "../output.ts";
import { addOutputModeOptions, resolveOutputMode, type CliOutputOptions } from "../output-mode.ts";

/** Manifest skill names belonging to this bundle all carry this prefix. */
const SKILL_NAME_PREFIX = "aventure";

/** Every state except `current` is outstanding work; `--status` exits 1 while any one remains. */
type AgentSetupActionState = "current" | "install" | "update" | "failed";

/** One planned or completed unit of onboarding work for one runtime. */
export type AgentSetupAction = {
  readonly kind: "skill" | "mcp";
  readonly name: string;
  readonly state: AgentSetupActionState;
  readonly detail: string;
};

/** What this command found, and will do or did, for one agent runtime. */
export type AgentRuntimePlan = {
  readonly name: string;
  readonly detected: boolean;
  readonly skillDir: string | null;
  readonly mcpConfig: string;
  readonly action: readonly AgentSetupAction[];
};

/** The report payload for every mode: one entry per known runtime, in inventory order. */
export type AgentSetupReport = { readonly runtime: readonly AgentRuntimePlan[] };

type AgentSetupOptions = CliOutputOptions & {
  readonly execute?: boolean;
  readonly status?: boolean;
};

export function registerBuiltinAgentSetupCommand(parent: Command): void {
  addOutputModeOptions(
    agentsCommand(parent)
      .command("setup")
      .summary("Install the aventure skill bundle and MCP server into your agent runtimes")
      .description(
        [
          `Detect the agent runtimes installed for this user (${AGENT_RUNTIME.map((runtime) => runtime.name).join(", ")}),`,
          `install or refresh the published ${SKILL_NAME_PREFIX}* skill bundle into each runtime's own`,
          `skill directory, and register the ${MCP_SERVER_NAME} MCP server in each runtime's own config.`,
          "",
          "Dry-run by default, like every other mutation in this CLI:",
          "  aventure-cli agents setup             # report the planned actions; writes nothing",
          "  aventure-cli agents setup --execute   # write the skills and the MCP registration",
          "  aventure-cli agents setup --status    # compare what is installed; exit 1 on drift",
        ].join("\n"),
      )
      .addOption(
        new Option("--execute", "write the planned actions; default is dry-run")
          .default(false)
          .conflicts(["status"]),
      )
      .addOption(
        new Option(
          "--status",
          "report installed skill versions against the manifest and exit 1 on drift; compares recorded versions, not file content, and writes nothing",
        )
          .default(false)
          .conflicts(["execute"]),
      ),
  ).action(async function (this: Command, opts: AgentSetupOptions) {
    // Root --environment is validated by its own choices() list; apply it like builtin-auth does.
    const globals = this.optsWithGlobals<{ readonly environment?: string }>();
    if (globals.environment !== undefined) process.env.API_ENV = globals.environment;
    emit({ mode: resolveOutputMode(opts) }, await agentSetupEnvelope(opts));
  });
}

/** Reuse the generated `agents` namespace so this sits beside `agents instructions`. */
function agentsCommand(parent: Command): Command {
  const namespace = "agents";
  const existing = parent.commands.find((command) => command.name() === namespace);
  if (existing !== undefined) return existing;
  const summary = GENERATED_CLI_NAMESPACES[namespace]?.summary ?? namespace;
  return parent.command(namespace).summary(summary).description(summary);
}

export async function agentSetupEnvelope(
  opts: AgentSetupOptions,
): Promise<ResultEnvelope<AgentSetupReport | null>> {
  const mcpUrl = mcpServerUrl();
  if (!mcpUrl.ok || mcpUrl.data === null) return { ...mcpUrl, data: null };
  const manifest = await readInstruction(
    "getAgentInstructionManifest",
    AgentInstructionManifestSchema,
  );
  if (!manifest.ok || manifest.data === null) return { ...manifest, data: null };
  const published = manifest.data;
  const mcpEndpoint = mcpUrl.data;
  const bundle = Object.keys(published.skill)
    .filter((name) => name.startsWith(SKILL_NAME_PREFIX))
    .toSorted();
  if (bundle.length === 0) {
    return failure(
      `The agent instruction manifest carries no ${SKILL_NAME_PREFIX}* skill; nothing to install.`,
    );
  }
  const planned = AGENT_RUNTIME.map((runtime) =>
    planRuntime(runtime, published, bundle, mcpEndpoint),
  );
  const runtime =
    opts.execute === true ? await applyPlan(planned, published, mcpEndpoint) : planned;
  return reportEnvelope({ runtime }, opts, mcpEndpoint);
}

function reportEnvelope(
  report: AgentSetupReport,
  opts: AgentSetupOptions,
  mcpEndpoint: string,
): ResultEnvelope<AgentSetupReport> {
  const detected = report.runtime.filter((entry) => entry.detected);
  const pending = detected.flatMap((entry) =>
    entry.action.filter((action) => action.state !== "current"),
  );
  const failed = pending.filter((action) => action.state === "failed");
  const counts = {
    runtimeDetected: detected.length,
    actionPending: pending.length,
    actionFailed: failed.length,
  };
  // The resolved endpoint leads the summary in every mode: it is what `--execute` persists into the
  // user's configs, and `api/env.ts` lets API_URL outrank `--environment` when both are set.
  const summary = [
    `agents setup: ${detected.length} runtime detected, ${pending.length} action pending, mcp ${mcpEndpoint}`,
    ...report.runtime.map(runtimeLine),
  ].join("\n");
  // A plan that still has work to do is a successful report; a failed write, `--status` finding
  // drift, or no runtime installed at all is a failing run.
  if (detected.length === 0) {
    const expected = AGENT_RUNTIME.map((entry) => `${entry.name}: no ${runtimeDetectPath(entry)}`);
    return { ...failure(summary, expected, { counts }), data: report };
  }
  const blocking = failed.length > 0 ? failed : opts.status === true ? pending : [];
  return blocking.length === 0
    ? success(summary, report, { counts })
    : { ...failure(summary, blocking.map(actionLine), { counts }), data: report };
}

function runtimeLine(plan: AgentRuntimePlan): string {
  if (!plan.detected) return `  ${plan.name} not installed`;
  const pending = plan.action.filter((action) => action.state !== "current");
  return pending.length === 0
    ? `  ${plan.name} current (${plan.action.length} item)`
    : `  ${plan.name} ${pending.length} pending — ${pending.map(actionLine).join("; ")}`;
}

function actionLine(action: AgentSetupAction): string {
  return `${action.kind} ${action.name} ${action.state}: ${action.detail}`;
}

function setupAction(
  kind: AgentSetupAction["kind"],
  name: string,
  state: AgentSetupActionState,
  detail: string,
): AgentSetupAction {
  return { kind, name, state, detail };
}

function planRuntime(
  runtime: AgentRuntime,
  manifest: AgentInstructionManifest,
  bundle: readonly string[],
  mcpUrl: string,
): AgentRuntimePlan {
  const skillDir = runtimeSkillDir(runtime);
  const mcpConfig = runtimeMcpConfig(runtime);
  const plan = { name: runtime.name, skillDir, mcpConfig };
  if (!runtimeDetected(runtime)) return { ...plan, detected: false, action: [] };
  // Registration is keyed by server name, so a config routed through a local MCP proxy counts as
  // registered; the stored endpoint is reported so a caller can see where it actually points.
  const registered = registeredMcpUrl(runtime);
  const mcp =
    registered === null
      ? setupAction("mcp", MCP_SERVER_NAME, "install", `register ${mcpUrl} in ${mcpConfig}`)
      : setupAction("mcp", MCP_SERVER_NAME, "current", `${registered} in ${mcpConfig}`);
  return {
    ...plan,
    detected: true,
    action: [...(skillDir === null ? [] : planSkill(skillDir, manifest, bundle)), mcp],
  };
}

function planSkill(
  skillDir: string,
  manifest: AgentInstructionManifest,
  bundle: readonly string[],
): readonly AgentSetupAction[] {
  const installed = readSkillState(skillStateFile(skillDir));
  return bundle.map((name) => {
    const published = manifest.skill[name]?.version ?? "";
    const local = installed[name]?.version;
    const target = join(skillDir, name, SKILL_ENTRY_FILE);
    if (local === undefined || !existsSync(target)) {
      return setupAction("skill", name, "install", `write ${target} at version ${published}`);
    }
    return local === published
      ? setupAction("skill", name, "current", `${target} at version ${published}`)
      : setupAction("skill", name, "update", `${target} ${local} -> ${published}`);
  });
}

/** Fetch each outstanding skill document once, then write it into every runtime that wants it. */
async function applyPlan(
  planned: readonly AgentRuntimePlan[],
  manifest: AgentInstructionManifest,
  mcpUrl: string,
): Promise<readonly AgentRuntimePlan[]> {
  const outstanding = planned.flatMap((plan) =>
    plan.action
      .filter((entry) => entry.kind === "skill" && entry.state !== "current")
      .map((entry) => entry.name),
  );
  const document = new Map<string, ResultEnvelope<AgentInstructionDetail | null>>();
  for (const name of [...new Set(outstanding)].toSorted())
    document.set(name, await readSkill(name));
  return planned.map((plan) => {
    const runtime = AGENT_RUNTIME.find((entry) => entry.name === plan.name);
    if (!plan.detected || runtime === undefined) return plan;
    const written: string[] = [];
    const applied = plan.action.map((entry) => {
      if (entry.state === "current") return entry;
      if (entry.kind === "mcp") return applyMcp(runtime, plan.mcpConfig, mcpUrl);
      const result = applySkill(plan.skillDir, entry.name, document.get(entry.name));
      if (result.state === "current") written.push(entry.name);
      return result;
    });
    const problem =
      plan.skillDir === null || written.length === 0
        ? null
        : writeSkillState(plan.skillDir, manifest, written);
    const state =
      problem === null ? [] : [setupAction("skill", SKILL_STATE_FILE, "failed", problem)];
    return { ...plan, action: [...applied, ...state] };
  });
}

function applyMcp(runtime: AgentRuntime, mcpConfig: string, url: string): AgentSetupAction {
  const problem = registerMcp(runtime, url);
  return problem === null
    ? setupAction("mcp", MCP_SERVER_NAME, "current", `registered ${url} in ${mcpConfig}`)
    : setupAction("mcp", MCP_SERVER_NAME, "failed", problem);
}

function applySkill(
  skillDir: string | null,
  name: string,
  document: ResultEnvelope<AgentInstructionDetail | null> | undefined,
): AgentSetupAction {
  if (skillDir === null || document === undefined || !document.ok || document.data === null) {
    return setupAction(
      "skill",
      name,
      "failed",
      document?.summary ?? `no document fetched for ${name}`,
    );
  }
  const problem = writeSkillDocument(skillDir, name, document.data.content);
  return problem === null
    ? setupAction(
        "skill",
        name,
        "current",
        `${join(skillDir, name, SKILL_ENTRY_FILE)} at version ${document.data.core.version}`,
      )
    : setupAction("skill", name, "failed", problem);
}

async function readSkill(name: string): Promise<ResultEnvelope<AgentInstructionDetail | null>> {
  return await readInstruction("getAgentInstruction", AgentInstructionDetailSchema, {
    kind: AgentInstructionKindSchema.enum.SKILL,
    name,
  });
}

/**
 * Call one generated agent-instruction operation and validate its body against the canonical
 * api-schemas contract, so neither the route nor the response shape is restated here.
 */
async function readInstruction<T>(
  operationId: string,
  schema: z.ZodType<T>,
  pathParams: Record<string, string> = {},
): Promise<ResultEnvelope<T | null>> {
  const spec = generatedSpec(operationId);
  if (spec === undefined) {
    return failure(
      `The generated command catalog carries no ${operationId} operation; regenerate it with \`make mcp-generate-contracts\` and reinstall.`,
    );
  }
  let path: string;
  try {
    path = buildOpenApiPath(spec.operationId, pathParams);
  } catch (error) {
    return failure(`Cannot address ${operationId}: ${credentialSafeMessage(error)}`);
  }
  const envelope = await runOpenApiCall({
    method: spec.method,
    path,
    auth: spec.auth,
    execute: true,
    responseFormat: "json",
  }).catch((error: unknown) => failure(credentialSafeMessage(error)));
  if (!envelope.ok) {
    return {
      ...envelope,
      summary: `${spec.method} ${path} failed: ${envelope.summary}`,
      data: null,
    };
  }
  const body = envelope.data;
  const parsed = schema.safeParse(
    typeof body === "object" && body !== null && "response" in body ? body.response : undefined,
  );
  return parsed.success
    ? success(`${spec.method} ${path} answered`, parsed.data)
    : failure(`${path} returned an unexpected body: ${parsed.error.message}`);
}

function generatedSpec(operationId: string): OpenApiCommandSpec | undefined {
  return GENERATED_OPENAPI_COMMAND_SPECS.find((spec) => spec.operationId === operationId);
}

/**
 * The deployed MCP server sits on the `mcp` sibling of the resolved API host
 * (`api.staging.aventure.vc` and `mcp.staging.aventure.vc` are the same deployment pair), so the
 * URL derives from `api/env.ts` instead of restating a second host inventory here.
 */
function mcpServerUrl(): ResultEnvelope<string | null> {
  try {
    return success("MCP host derived", mcpServerUrlFromApiHost(readEnv().host, "/mcp").href);
  } catch (error) {
    return failure(
      `Correct API_ENV or pass \`--environment <name>\` — ${credentialSafeMessage(error)}.`,
    );
  }
}
