import { execFile } from "node:child_process";
import { platform } from "node:os";

import type { CliAuthorizationStart } from "@aventurevc/api-schemas/cli/authorization-start";

import { isLoopbackHostname } from "./api-target.ts";

const CLI_AUTHORIZATION_FRAGMENT_FIELD_COUNT = 2;

type BrowserAuthorizationStart = Pick<
  CliAuthorizationStart,
  "id" | "verificationUrl" | "pollSecret"
>;

export type BrowserOpenResult =
  | { readonly state: "opened"; readonly reason: null }
  | { readonly state: "skipped" | "failed"; readonly reason: string };

export interface BrowserOpenOptions {
  readonly noBrowser: boolean;
  readonly environment?: NodeJS.ProcessEnv;
  readonly operatingSystem?: NodeJS.Platform;
}

/** Return a display-safe reference after validating the possession-bound browser fragment. */
export function redactedVerificationUrl(
  started: BrowserAuthorizationStart,
  expectedOrigin: string,
): string {
  return validatedBrowserAuthorization(started, expectedOrigin).redactedUrl;
}

/**
 * Open the exact secret-bearing URL without reflecting it through diagnostics or result values.
 * The fragment keeps browser possession material out of HTTP requests and server access logs.
 */
export async function openVerificationUrl(
  started: BrowserAuthorizationStart,
  expectedOrigin: string,
  options: BrowserOpenOptions,
): Promise<BrowserOpenResult> {
  const authorization = validatedBrowserAuthorization(started, expectedOrigin);
  const environment = options.environment ?? process.env;
  const operatingSystem = options.operatingSystem ?? platform();
  const skipReason = browserSkipReason(options.noBrowser, environment, operatingSystem);
  if (skipReason !== null) return { state: "skipped", reason: skipReason };

  const invocation = openerInvocation(operatingSystem, authorization.openerUrl);
  if (invocation === null) {
    return { state: "failed", reason: `unsupported browser-opening platform: ${operatingSystem}` };
  }
  try {
    await runOpener(invocation.command, invocation.arguments);
    return { state: "opened", reason: null };
  } catch {
    return { state: "failed", reason: "browser opener failed" };
  }
}

interface ValidatedBrowserAuthorization {
  readonly openerUrl: string;
  readonly redactedUrl: string;
}

/** Bind the broker URL to the expected origin, request, and independent browser possession secret. */
function validatedBrowserAuthorization(
  started: BrowserAuthorizationStart,
  expectedOrigin: string,
): ValidatedBrowserAuthorization {
  const { id: authorizationId, verificationUrl, pollSecret } = started;
  let candidate: URL;
  let expected: URL;
  try {
    candidate = new URL(verificationUrl);
    expected = new URL(expectedOrigin);
  } catch {
    throw new Error("broker returned an invalid browser verification URL");
  }
  if (
    expected.username.length > 0 ||
    expected.password.length > 0 ||
    expected.pathname !== "/" ||
    expected.search.length > 0 ||
    expected.hash.length > 0
  ) {
    throw new Error("configured browser origin must contain only an origin");
  }
  const loopback = isLoopbackHostname(expected.hostname);
  if (expected.protocol !== "https:" && !(expected.protocol === "http:" && loopback)) {
    throw new Error("configured browser origin must use HTTPS except for loopback development");
  }
  const fragment = new URLSearchParams(candidate.hash.slice(1));
  const fragmentName = [...fragment.keys()];
  const authorizationIdValue = fragment.getAll("cliAuthorizationId");
  const browserSecretValue = fragment.getAll("browserSecret");
  const browserSecret = browserSecretValue[0] ?? "";
  if (
    candidate.origin !== expected.origin ||
    candidate.protocol !== expected.protocol ||
    candidate.username.length > 0 ||
    candidate.password.length > 0 ||
    candidate.pathname !== "/settings/developer" ||
    candidate.search.length > 0 ||
    fragmentName.length !== CLI_AUTHORIZATION_FRAGMENT_FIELD_COUNT ||
    authorizationIdValue.length !== 1 ||
    authorizationIdValue[0] !== authorizationId ||
    browserSecretValue.length !== 1 ||
    browserSecret.length === 0 ||
    pollSecret.length === 0 ||
    browserSecret === pollSecret
  ) {
    throw new Error(
      "broker returned a browser verification URL outside the configured first-party approval flow",
    );
  }
  let decodedUrl: string;
  try {
    decodedUrl = decodeURIComponent(verificationUrl);
  } catch {
    throw new Error(
      "broker returned a browser verification URL outside the configured first-party approval flow",
    );
  }
  if (verificationUrl.includes(pollSecret) || decodedUrl.includes(pollSecret)) {
    throw new Error(
      "broker returned a browser verification URL outside the configured first-party approval flow",
    );
  }

  const redacted = new URL(candidate);
  redacted.hash = new URLSearchParams({
    cliAuthorizationId: authorizationId,
    browserSecret: "<redacted>",
  }).toString();
  return {
    openerUrl: verificationUrl,
    redactedUrl: redacted.toString(),
  };
}

export function browserSkipReason(
  noBrowser: boolean,
  environment: NodeJS.ProcessEnv,
  operatingSystem: NodeJS.Platform,
): string | null {
  if (noBrowser) return "--no-browser was set";
  if (operatingSystem === "darwin" && environment.CODEX_SESSION_ID) {
    return "macOS Codex browser process boundary";
  }
  if (environment.SSH_CONNECTION || environment.SSH_CLIENT || environment.SSH_TTY) {
    return "SSH/headless session detected";
  }
  if (
    (operatingSystem === "linux" || operatingSystem === "freebsd") &&
    !environment.DISPLAY &&
    !environment.WAYLAND_DISPLAY
  ) {
    return "no graphical display detected";
  }
  return null;
}

function openerInvocation(
  operatingSystem: NodeJS.Platform,
  verificationUrl: string,
): { readonly command: string; readonly arguments: readonly string[] } | null {
  if (operatingSystem === "darwin") return { command: "open", arguments: [verificationUrl] };
  if (operatingSystem === "win32") {
    return {
      command: "rundll32.exe",
      arguments: ["url.dll,FileProtocolHandler", verificationUrl],
    };
  }
  if (operatingSystem === "linux" || operatingSystem === "freebsd") {
    return { command: "xdg-open", arguments: [verificationUrl] };
  }
  return null;
}

function runOpener(command: string, openerArguments: readonly string[]): Promise<void> {
  return new Promise((resolve, reject) => {
    execFile(command, [...openerArguments], { timeout: 5_000, windowsHide: true }, (error) =>
      error ? reject(error) : resolve(),
    );
  });
}
