/**
 * Generated command-tree recovery for Commander parse errors.
 *
 * Commander owns same-command spelling suggestions. These handlers add only
 * recovery that requires the completed generated tree or command catalog, and
 * keep every hint on stderr so the stdout envelope channel stays clean.
 */
import { Option, type Command, type CommanderError } from "commander";

import { visibleOpenApiCommandSpecsForCurrentAuth } from "../../mcp-server/contract-visibility.ts";
import { GENERATED_CLI_NAMESPACES } from "../generated/cli-namespaces.ts";
import { GENERATED_OPENAPI_COMMAND_SPECS } from "../generated/openapi-commands.ts";
import { payloadOperandHint, rejectPayloadOperand } from "./payload-operand-guard.ts";

function missingRequiredFlag(error: CommanderError): string | undefined {
  return error.message.match(/required option '([^']+)' not specified/iu)?.[1]?.split(/\s+/u)[0];
}

function unknownFlag(error: CommanderError): string | undefined {
  return error.message.match(/unknown option '([^']+)'/iu)?.[1];
}

function unknownCommand(error: CommanderError): string | undefined {
  return error.message.match(/unknown command '([^']+)'/iu)?.[1];
}

function flagName(option: Command["options"][number]): string {
  return option.flags.split(" ")[0] ?? option.flags;
}

function missingParentSelectorHint(failed: Command, error: CommanderError): string | undefined {
  const missing = missingRequiredFlag(error);
  if (missing === undefined) return undefined;
  const missingIndex = failed.options.findIndex((option) => flagName(option) === missing);
  if (missingIndex < 0) return undefined;

  const suppliedChildSelector = failed.options
    .slice(missingIndex + 1)
    .filter((option) => option.mandatory)
    .map((option) => [flagName(option), failed.getOptionValue(option.attributeName())] as const)
    .find(([, value]) => typeof value === "string" && value.length > 0)?.[0];
  if (suppliedChildSelector === undefined) return undefined;

  return `hint: ${missing} is still required for this nested command; supplied child selector ${suppliedChildSelector} does not replace the parent selector.`;
}

function commandPath(command: Command): string[] {
  const path: string[] = [];
  for (
    let node: Command | null = command;
    node !== null && node.parent !== null;
    node = node.parent
  ) {
    path.unshift(node.name());
  }
  return path;
}

function leafCommands(command: Command): Command[] {
  if (command.commands.length === 0) return [command];
  return command.commands.flatMap(leafCommands);
}

function relativePath(parent: Command, descendant: Command): string[] {
  return commandPath(descendant).slice(commandPath(parent).length);
}

function rootCommand(command: Command): Command {
  let root = command;
  while (root.parent !== null) root = root.parent;
  return root;
}

function preferredLeaf(parent: Command, candidates: readonly Command[]): Command | undefined {
  return candidates.toSorted((left, right) => {
    const leftPath = relativePath(parent, left);
    const rightPath = relativePath(parent, right);
    const leftDefault = leftPath.at(-1) === "get" ? 0 : 1;
    const rightDefault = rightPath.at(-1) === "get" ? 0 : 1;
    return leftPath.length - rightPath.length || leftDefault - rightDefault;
  })[0];
}

function shellArgument(argument: string): string {
  return /^[A-Za-z0-9_./:=@+-]+$/u.test(argument)
    ? argument
    : `'${argument.replaceAll("'", `'"'"'`)}'`;
}

function invocationWithLeaf(failed: Command, leaf: Command): string {
  const failedPath = commandPath(failed);
  const supplied = process.argv.slice(2 + failedPath.length);
  return [rootCommand(failed).name(), ...failedPath, ...relativePath(failed, leaf), ...supplied]
    .map(shellArgument)
    .join(" ");
}

function descendantFlagHint(failed: Command, error: CommanderError): string | undefined {
  const unknown = unknownFlag(error);
  if (unknown === undefined || failed.commands.length === 0) return undefined;
  const candidates = leafCommands(failed).filter((leaf) =>
    leaf.options.some((option) => flagName(option) === unknown),
  );
  const leaf = preferredLeaf(failed, candidates);
  if (leaf === undefined) return undefined;
  return `hint: run: ${invocationWithLeaf(failed, leaf)}`;
}

function generatedNamespace(segment: string | undefined): boolean {
  return segment !== undefined && Object.hasOwn(GENERATED_CLI_NAMESPACES, segment);
}

function commandAt(root: Command, path: readonly string[]): Command | undefined {
  let current = root;
  for (const segment of path) {
    const child = current.commands.find((command) => command.name() === segment);
    if (child === undefined) return undefined;
    current = child;
  }
  return current;
}

function rootEquivalentGeneratedPath(failed: Command, unknown: string): string[] | undefined {
  const failedPath = commandPath(failed);
  const candidatePath = [...failedPath.slice(1), unknown];
  if (!generatedNamespace(failedPath.at(0)) || !generatedNamespace(candidatePath.at(0))) {
    return undefined;
  }

  const rootCandidate = commandAt(rootCommand(failed), candidatePath);
  if (rootCandidate === undefined) return undefined;
  let candidate: Command = rootCandidate;
  for (const argument of process.argv.slice(2 + failedPath.length + 1)) {
    if (argument.startsWith("-")) break;
    const child = candidate.commands.find((command) => command.name() === argument);
    if (child === undefined) break;
    candidatePath.push(argument);
    candidate = child;
  }
  return candidatePath;
}

function rootLeafGeneratedPath(failed: Command, unknown: string): string[] | undefined {
  const [activeRoot] = commandPath(failed);
  if (!generatedNamespace(activeRoot)) return undefined;
  const candidatePath = [activeRoot, unknown];
  return commandAt(rootCommand(failed), candidatePath)?.commands.length === 0
    ? candidatePath
    : undefined;
}

function suppliedCommandWords(command: Command): string[] {
  const [unknown, ...supplied] = command.args;
  if (unknown === undefined) return [];
  const commandPaths = leafCommands(rootCommand(command)).map(commandPath);
  const wordEnd = supplied.findIndex((word, index) => {
    const candidate = [...supplied.slice(0, index), word];
    return !commandPaths.some((path) =>
      path.some(
        (segment, start) =>
          segment === candidate[0] &&
          candidate.every((candidateWord, offset) => path[start + offset] === candidateWord),
      ),
    );
  });
  return [unknown, ...(wordEnd < 0 ? supplied : supplied.slice(0, wordEnd))];
}

/**
 * Wrong-namespace leaf recovery: when the invocation fails at a wrong root/group but the remaining
 * words name a generated leaf elsewhere (`entities media get` → `media get`), hint the runnable
 * command instead of a catalog search. An exact full-path match wins (a valid path typed under a
 * wrong parent, e.g. `media jobs get` → `jobs get`); otherwise a single unique cross-namespace
 * suffix match; ambiguity (two or more matches) falls through to the catalog-search hint.
 */
function crossNamespaceLeafHint(failed: Command, words: readonly string[]): string | undefined {
  const failedPath = commandPath(failed);
  const supplied = process.argv.slice(2 + failedPath.length);
  if (words.length === 0 || words.some((word, index) => supplied[index] !== word)) return undefined;

  // Hint only commands the caller's credentials can see and run [contract-visibility].
  const matches = visibleOpenApiCommandSpecsForCurrentAuth(GENERATED_OPENAPI_COMMAND_SPECS)
    .map((spec) => spec.cliPath)
    .filter(
      (cliPath) =>
        cliPath[0] !== failedPath[0] &&
        cliPath.length >= words.length &&
        words.every((word, index) => cliPath[cliPath.length - words.length + index] === word),
    );
  const exact = matches.find(
    (cliPath) => cliPath.length === words.length && cliPath.every((word, i) => word === words[i]),
  );
  const resolved = exact ?? (matches.length === 1 ? matches[0] : undefined);
  if (resolved === undefined) return undefined;

  const invocation = [rootCommand(failed).name(), ...resolved].map(shellArgument).join(" ");
  return `hint: run: ${invocation}`;
}

/**
 * Spurious-group recovery: `entities detail get` names a real generated leaf once the intermediate
 * group is dropped, so hand back the runnable command with the caller's flags rather than a catalog
 * search they still have to translate. Operands typed before the first flag are prose, not input.
 */
function droppedGroupLeafHint(
  failed: Command,
  leafPath: readonly string[],
  words: readonly string[],
): string | undefined {
  if (!generatedCommandPath(leafPath)) return undefined;
  const tail = failed.args.slice(words.length);
  const firstFlag = tail.findIndex((argument) => argument.startsWith("-"));
  const invocation = [
    rootCommand(failed).name(),
    ...leafPath,
    ...(firstFlag < 0 ? [] : tail.slice(firstFlag)),
  ]
    .map(shellArgument)
    .join(" ");
  return `hint: Did you mean: ${invocation}`;
}

function generatedGroupHelpHint(failed: Command): string | undefined {
  const path = commandPath(failed);
  if (path.at(1) === undefined || !generatedNamespace(path.at(0))) return undefined;
  const invocation = [rootCommand(failed).name(), ...path, "--help"].map(shellArgument).join(" ");
  return `hint: inspect generated command group: ${invocation}`;
}

/**
 * Does a generated spec own this exact command path, by canonical or alias path? `writeLane`
 * narrows the match to write (dry-run) or read specs; omit it to accept either.
 */
function generatedCommandPath(path: readonly string[], writeLane?: boolean): boolean {
  const pathKey = path.join(" ");
  return GENERATED_OPENAPI_COMMAND_SPECS.some((spec) => {
    const aliasPath = "cliAliasPath" in spec ? spec.cliAliasPath : undefined;
    if (spec.cliPath.join(" ") !== pathKey && aliasPath?.join(" ") !== pathKey) return false;
    return writeLane === undefined || spec.dryRun === writeLane;
  });
}

function generatedCommandHelpHint(failed: Command): string | undefined {
  const path = commandPath(failed);
  if (!generatedNamespace(path.at(0)) || !generatedCommandPath(path)) return undefined;
  const invocation = [rootCommand(failed).name(), ...path, "--help"].map(shellArgument).join(" ");
  return `hint: inspect generated command: ${invocation}`;
}

/**
 * Flags the CLI registers on a generated leaf solely because its spec is dry-run: carried by every
 * write leaf and by no read leaf, which today means `--execute`. Deriving the set from the built
 * tree keeps the hint correct when the write-lane flag is renamed at its registration owner.
 */
function dryRunOnlyFlag(root: Command): ReadonlySet<string> {
  const readFlag = new Set<string>();
  const writeLeafFlag: (readonly string[])[] = [];
  for (const spec of GENERATED_OPENAPI_COMMAND_SPECS) {
    const leaf = commandAt(root, spec.cliPath);
    if (leaf === undefined) continue;
    const flag = leaf.options.map(flagName);
    if (spec.dryRun) writeLeafFlag.push(flag);
    else for (const name of flag) readFlag.add(name);
  }
  const [firstWriteLeafFlag = [], ...remainingWriteLeafFlag] = writeLeafFlag;
  return new Set(
    firstWriteLeafFlag.filter(
      (name) =>
        !readFlag.has(name) && remainingWriteLeafFlag.every((other) => other.includes(name)),
    ),
  );
}

/**
 * `--execute` exists only on write leaves, so a catalog search for it from a read command can only
 * come back empty. Name the read/write rule that made the flag unavailable instead.
 */
function writeLaneFlagHint(failed: Command, unknown: string): string | undefined {
  const path = commandPath(failed);
  if (!generatedCommandPath(path, false)) return undefined;
  if (!dryRunOnlyFlag(rootCommand(failed)).has(unknown)) return undefined;
  return `hint: ${path.join(" ")} is a read operation; ${unknown} applies only to write operations (catalog dryRunSupported=true)`;
}

function commandCatalogSearchHint(
  failed: Command,
  query: string,
  filterActiveRoot = true,
): string | undefined {
  const root = rootCommand(failed);
  const catalog = root.commands.find((command) => command.name() === "command-catalog");
  const search = catalog?.commands.find((command) => command.name() === "search");
  if (catalog === undefined || search === undefined) return undefined;

  const invocation = [root.name(), catalog.name(), search.name(), query];
  const activeRoot = commandPath(failed).at(0);
  const rootFilter = search.options.find((option) => flagName(option) === "--root");
  if (
    filterActiveRoot &&
    activeRoot !== undefined &&
    rootFilter !== undefined &&
    generatedNamespace(activeRoot)
  ) {
    invocation.push(flagName(rootFilter), activeRoot);
  }
  return `hint: search generated commands: ${invocation.map(shellArgument).join(" ")}`;
}

function unknownCommandHint(failed: Command, error: CommanderError): string | undefined {
  const unknown = unknownCommand(error);
  if (unknown === undefined) return undefined;
  if (error.message.includes("\n(Did you mean ")) return undefined;
  const commandWords = suppliedCommandWords(failed);
  const leafHint = crossNamespaceLeafHint(failed, commandWords);
  if (leafHint !== undefined) return leafHint;
  const rootEquivalentPath = rootEquivalentGeneratedPath(failed, unknown);
  if (rootEquivalentPath !== undefined) {
    return commandCatalogSearchHint(failed, rootEquivalentPath.join(" "), false);
  }
  const rootLeafPath = rootLeafGeneratedPath(failed, unknown);
  if (rootLeafPath !== undefined) {
    return (
      droppedGroupLeafHint(failed, rootLeafPath, commandWords) ??
      commandCatalogSearchHint(failed, rootLeafPath.join(" "), false)
    );
  }
  const query = commandWords.join(" ") || unknown;
  return generatedGroupHelpHint(failed) ?? commandCatalogSearchHint(failed, query);
}

/**
 * Build a Commander `exitOverride` callback bound to one command. For a missing
 * required option it names the full missing-required set in one line (Commander
 * itself reports only the first), then exits with the code Commander chose.
 * Unknown commands, descendant flags, and excess operands receive only exact
 * generated-tree or catalog guidance.
 */
function commandExitHandler(command: Command): (error: CommanderError) => never {
  return (error) => {
    if (error.code === "commander.missingMandatoryOptionValue") {
      const missing = command.options.filter(
        (option) =>
          option.mandatory && command.getOptionValue(option.attributeName()) === undefined,
      );
      // One combined line saves the caller one failed retry per remaining required flag.
      if (missing.length > 1) {
        const flags = missing.map((option) => option.flags.split(", ").at(-1) ?? option.flags);
        process.stderr.write(`error: missing required options: ${flags.join(", ")}\n`);
      }
      for (const hint of [payloadOperandHint(command), missingParentSelectorHint(command, error)]) {
        if (hint !== undefined) process.stderr.write(`${hint}\n`);
      }
    } else if (error.code === "commander.excessArguments") {
      const hint = payloadOperandHint(command) ?? generatedCommandHelpHint(command);
      if (hint !== undefined) process.stderr.write(`${hint}\n`);
    } else if (error.code === "commander.unknownOption") {
      const unknown = unknownFlag(error);
      const hint =
        descendantFlagHint(command, error) ??
        (unknown !== undefined && !error.message.includes("\n(Did you mean ")
          ? (writeLaneFlagHint(command, unknown) ??
            commandCatalogSearchHint(command, unknown.replace(/^--/u, "")))
          : undefined);
      if (hint !== undefined) process.stderr.write(`${hint}\n`);
    } else if (error.code === "commander.unknownCommand") {
      const hint = unknownCommandHint(command, error);
      if (hint !== undefined) process.stderr.write(`${hint}\n`);
    }
    process.exit(error.exitCode);
  };
}

/**
 * Help option for a command that only dispatches to children. Commander resolves `--help` before it
 * reports an unknown subcommand (`_parseCommand` runs `_outputHelpIfRequested` ahead of
 * `unknownCommand`), so `aventure-cli entity get --help` printed the root usage and exited 0. This
 * option stands down once the first operand names no child, which lets the unknown-command error —
 * carrying Commander's own spelling suggestion — run instead of a usage dump.
 */
class GroupHelpOption extends Option {
  private readonly group: Command;

  constructor(group: Command) {
    super("-h, --help", "display help for command");
    this.group = group;
  }

  is(argument: string): boolean {
    if (argument !== this.short && argument !== this.long) return false;
    const operand = this.group.args.at(0);
    if (operand === undefined || operand.startsWith("-")) return true;
    return this.group.commands.some(
      (child) => child.name() === operand || child.aliases().includes(operand),
    );
  }
}

/**
 * Install error handlers only after the full command tree exists. Commander copies exit settings
 * when a child is added, so a late root override does not reach existing children. Binding every
 * node also catches root and group errors before they can reach a generated leaf.
 */
export function installMissingOptionExitHandlers(command: Command): void {
  command.showHelpAfterError(false).exitOverride(commandExitHandler(command));
  // Leaves only: operands resolve there, and Commander passes the leaf as the action command.
  if (command.commands.length === 0) command.hook("preAction", rejectPayloadOperand);
  else command.addHelpOption(new GroupHelpOption(command));
  for (const child of command.commands) installMissingOptionExitHandlers(child);
}
