import { webcrypto } from "node:crypto";
import { TextDecoder } from "node:util";

import type { CliAuthorizationDelivery } from "@aventurevc/api-schemas/cli/authorization-delivery";

const AES_256_KEY_BYTE_LENGTH = 32;

export interface CliAuthorizationKeyPair {
  readonly publicKey: string;
  readonly privateKey: CryptoKey;
}

/** Create the ephemeral keypair that binds one browser-authorization request to this process. */
export async function createCliAuthorizationKeyPair(): Promise<CliAuthorizationKeyPair> {
  const keyPair = await webcrypto.subtle.generateKey(
    {
      name: "RSA-OAEP",
      modulusLength: 2048,
      publicExponent: new Uint8Array([1, 0, 1]),
      hash: "SHA-256",
    },
    true,
    ["encrypt", "decrypt"],
  );
  const publicKey = await webcrypto.subtle.exportKey("spki", keyPair.publicKey);
  return {
    publicKey: Buffer.from(publicKey).toString("base64"),
    privateKey: keyPair.privateKey,
  };
}

/** Open the broker's RSA-OAEP-256 wrapped AES-256-GCM one-time credential. */
export async function decryptCliAuthorizationCredential(
  privateKey: CryptoKey,
  delivery: CliAuthorizationDelivery,
): Promise<string> {
  const { wrappedKey, nonce, ciphertext, authenticationTag } = delivery;
  const wrappedKeyBytes = decodeBase64(wrappedKey, "wrapped key", 128, 1_024);
  const nonceBytes = decodeBase64(nonce, "nonce", 12, 12);
  const ciphertextBytes = decodeBase64(ciphertext, "ciphertext", 1, 65_536);
  const authenticationTagBytes = decodeBase64(authenticationTag, "authentication tag", 16, 16);

  let unwrappedKey: ArrayBuffer;
  try {
    unwrappedKey = await webcrypto.subtle.decrypt(
      { name: "RSA-OAEP" },
      privateKey,
      wrappedKeyBytes,
    );
  } catch {
    throw new Error("broker credential key could not be decrypted");
  }
  const unwrappedKeyBytes = new Uint8Array(unwrappedKey);
  try {
    if (unwrappedKeyBytes.byteLength !== AES_256_KEY_BYTE_LENGTH) {
      throw new Error("broker credential used an invalid AES-256 key");
    }
    const aesKey = await webcrypto.subtle.importKey(
      "raw",
      unwrappedKeyBytes,
      { name: "AES-GCM" },
      false,
      ["decrypt"],
    );
    const encryptedPayload = new Uint8Array(
      ciphertextBytes.byteLength + authenticationTagBytes.byteLength,
    );
    encryptedPayload.set(ciphertextBytes);
    encryptedPayload.set(authenticationTagBytes, ciphertextBytes.byteLength);
    let plaintext: ArrayBuffer;
    try {
      plaintext = await webcrypto.subtle.decrypt(
        { name: "AES-GCM", iv: nonceBytes, tagLength: 128 },
        aesKey,
        encryptedPayload,
      );
    } catch {
      throw new Error("broker credential payload failed authentication");
    }
    const secret = new TextDecoder("utf-8", { fatal: true }).decode(plaintext);
    if (secret.trim().length === 0) throw new Error("broker returned a blank credential");
    return secret;
  } finally {
    unwrappedKeyBytes.fill(0);
  }
}

function decodeBase64(
  encoded: string,
  field: string,
  minimumBytes: number,
  maximumBytes: number,
): Uint8Array<ArrayBuffer> {
  const normalized = encoded.replace(/=+$/u, "");
  const decoded = Uint8Array.from(Buffer.from(encoded, "base64"));
  const canonical = Buffer.from(decoded).toString("base64").replace(/=+$/u, "");
  if (
    normalized.length === 0 ||
    canonical !== normalized ||
    decoded.byteLength < minimumBytes ||
    decoded.byteLength > maximumBytes
  ) {
    throw new Error(`broker returned an invalid ${field}`);
  }
  return decoded;
}
